-- >>> BEGIN MIGRATION: 20260226140000_chat.sql <<<
-- Chat: direktan razgovor kupac–prodavac

-- 1. Razgovori (jedan po par kupac–prodavac, opciono vezan za porudžbinu)
CREATE TABLE IF NOT EXISTS public.conversations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  buyer_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  seller_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  order_id UUID REFERENCES public.orders(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(buyer_id, seller_id)
);

-- 2. Poruke
CREATE TABLE IF NOT EXISTS public.messages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id UUID NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,
  sender_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  body TEXT NOT NULL,
  read_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_messages_conversation ON public.messages(conversation_id);
CREATE INDEX IF NOT EXISTS idx_conversations_buyer ON public.conversations(buyer_id);
CREATE INDEX IF NOT EXISTS idx_conversations_seller ON public.conversations(seller_id);

ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;

-- Kupac i prodavac vide samo svoje razgovore
DROP POLICY IF EXISTS "Users see own conversations" ON public.conversations;
CREATE POLICY "Users see own conversations"
  ON public.conversations FOR ALL
  TO authenticated
  USING (auth.uid() = buyer_id OR auth.uid() = seller_id)
  WITH CHECK (auth.uid() = buyer_id OR auth.uid() = seller_id);

-- Poruke: vidljive učesnicima razgovora
DROP POLICY IF EXISTS "Participants see messages" ON public.messages;
CREATE POLICY "Participants see messages"
  ON public.messages FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = conversation_id AND (c.buyer_id = auth.uid() OR c.seller_id = auth.uid())
    )
  );

DROP POLICY IF EXISTS "Participants insert messages" ON public.messages;
CREATE POLICY "Participants insert messages"
  ON public.messages FOR INSERT
  TO authenticated
  WITH CHECK (
    auth.uid() = sender_id AND
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = conversation_id AND (c.buyer_id = auth.uid() OR c.seller_id = auth.uid())
    )
  );

DROP POLICY IF EXISTS "Participants update read_at" ON public.messages;
CREATE POLICY "Participants update read_at"
  ON public.messages FOR UPDATE
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = conversation_id AND (c.buyer_id = auth.uid() OR c.seller_id = auth.uid())
    )
  );

-- Trigger: ažuriraj updated_at na conversations kada stigne nova poruka
CREATE OR REPLACE FUNCTION public.conversation_updated_on_message()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE public.conversations SET updated_at = NOW() WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS on_message_insert ON public.messages;
CREATE TRIGGER on_message_insert
  AFTER INSERT ON public.messages
  FOR EACH ROW EXECUTE FUNCTION public.conversation_updated_on_message();

-- >>> END MIGRATION: 20260226140000_chat.sql <<<

-- >>> BEGIN MIGRATION: 20260226150000_badges_sort.sql <<<
-- Badge „Popularno“ (broj prodaja) i sortiranje po oceni
-- RPC: broj isporučenih/prihvaćenih porudžbina po proizvodu (bypass RLS)

CREATE OR REPLACE FUNCTION public.get_product_sales_counts()
RETURNS TABLE (product_id uuid, order_count bigint)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT product_id, COUNT(*)::bigint
  FROM orders
  WHERE status IN ('accepted', 'delivered')
  GROUP BY product_id;
$$;

-- RPC: prosečna ocena i broj recenzija po proizvodu
CREATE OR REPLACE FUNCTION public.get_product_ratings()
RETURNS TABLE (product_id uuid, avg_rating numeric, review_count bigint)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT product_id, AVG(rating)::numeric, COUNT(*)::bigint
  FROM reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id;
$$;

-- >>> END MIGRATION: 20260226150000_badges_sort.sql <<<

