-- >>> BEGIN MIGRATION: 20260226190000_home_products_rpc.sql <<<
-- RPC get_home_products – jedan poziv umesto getProducts + getProductSalesCounts
-- Vraća proizvode sa order_count, sortirane: novo (14 dana) → popularno (2+ prodaje) → ostalo
-- LIMIT smanjuje količinu podataka na telefonu

CREATE OR REPLACE FUNCTION public.get_home_products(
  p_limit int DEFAULT 50,
  p_region text DEFAULT NULL,
  p_category text DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  seller_id uuid,
  category text,
  name text,
  price_per_kg numeric,
  min_order_kg numeric,
  available_kg numeric,
  description text,
  image_urls text[],
  pickup_options text[],
  location text,
  is_domestic boolean,
  available_now boolean,
  created_at timestamptz,
  order_count bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH sales AS (
    SELECT product_id, COUNT(*)::bigint AS cnt
    FROM orders
    WHERE status IN ('accepted', 'delivered')
    GROUP BY product_id
  )
  SELECT
    p.id, p.seller_id, p.category, p.name, p.price_per_kg, p.min_order_kg,
    p.available_kg, p.description, p.image_urls, p.pickup_options, p.location,
    p.is_domestic, p.available_now, p.created_at,
    COALESCE(s.cnt, 0)::bigint AS order_count
  FROM products p
  LEFT JOIN sales s ON s.product_id = p.id
  WHERE (p_region IS NULL OR p_region = '' OR p.location = p_region)
    AND (p_category IS NULL OR p_category = '' OR p.category = p_category)
  ORDER BY
    (p.created_at >= NOW() - INTERVAL '14 days') DESC,
    COALESCE(s.cnt, 0) DESC,
    p.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 100));
$$;

-- >>> END MIGRATION: 20260226190000_home_products_rpc.sql <<<

-- >>> BEGIN MIGRATION: 20260226200000_favorite_sellers_products_rpc.sql <<<
-- RPC get_products_from_favorite_sellers – jedan poziv umesto getFavoriteSellerIds + products.inFilter
-- JOIN u bazi umesto 2 round-trip-a

CREATE OR REPLACE FUNCTION public.get_products_from_favorite_sellers(p_user_id uuid)
RETURNS SETOF public.products
LANGUAGE sql
SECURITY INVOKER
SET search_path = public
AS $$
  SELECT p.*
  FROM products p
  JOIN favorite_sellers fs ON fs.seller_id = p.seller_id
  WHERE fs.user_id = p_user_id
  ORDER BY p.created_at DESC;
$$;

-- >>> END MIGRATION: 20260226200000_favorite_sellers_products_rpc.sql <<<

-- >>> BEGIN MIGRATION: 20260226210000_products_with_stats_view.sql <<<
-- View products_with_stats – proširenje products_with_ratings sa order_count
-- Za badge „Popularno“ bez posebnog getProductSalesCounts poziva

DROP VIEW IF EXISTS public.products_with_ratings;

CREATE VIEW public.products_with_ratings AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.available_kg,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric AS avg_rating,
  COALESCE(r.review_count, 0)::bigint AS review_count,
  COALESCE(s.order_count, 0)::bigint AS order_count
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id
LEFT JOIN (
  SELECT product_id, COUNT(*)::bigint AS order_count
  FROM public.orders
  WHERE status IN ('accepted', 'delivered', 'Sent', 'Delivered', 'Arhivirano')
  GROUP BY product_id
) s ON p.id = s.product_id;

GRANT SELECT ON public.products_with_ratings TO anon;
GRANT SELECT ON public.products_with_ratings TO authenticated;

-- >>> END MIGRATION: 20260226210000_products_with_stats_view.sql <<<

-- >>> BEGIN MIGRATION: 20260226220000_favorite_sellers_profiles_rpc.sql <<<
-- RPC get_favorite_sellers_with_profiles – jedan poziv umesto getFavoriteSellerIds + profiles.inFilter
-- JOIN favorite_sellers sa profiles u bazi

CREATE OR REPLACE FUNCTION public.get_favorite_sellers_with_profiles(p_user_id uuid)
RETURNS SETOF public.profiles
LANGUAGE sql
SECURITY INVOKER
SET search_path = public
AS $$
  SELECT p.*
  FROM profiles p
  JOIN favorite_sellers fs ON fs.seller_id = p.id
  WHERE fs.user_id = p_user_id
    AND p.role = 'seller';
$$;

