-- >>> BEGIN MIGRATION: 20260228110000_seller_stats_rpc.sql <<<
-- Statistika prodavca: broj porudžbina, prosečna ocena, prosečno vreme odgovora
-- Sve se računa na nivou baze (COUNT, AVG) — bez iteracije na klijentu.

CREATE OR REPLACE FUNCTION public.get_seller_stats(p_seller_id UUID)
RETURNS JSON
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH
    -- Broj isporučenih porudžbina
    order_stats AS (
      SELECT COUNT(*)::int AS delivered_count
      FROM public.orders
      WHERE seller_id = p_seller_id
        AND status = 'delivered'
    ),

    -- Prosečna ocena i broj recenzija
    rating_stats AS (
      SELECT
        COUNT(*)::int                          AS review_count,
        ROUND(AVG(rating)::numeric, 1)::float  AS avg_rating
      FROM public.reviews
      WHERE seller_id = p_seller_id
    ),

    -- Prva porudžbina svakog kupca prema ovom prodavcu
    first_orders AS (
      SELECT DISTINCT ON (buyer_id)
        buyer_id,
        created_at AS order_created_at
      FROM public.orders
      WHERE seller_id = p_seller_id
      ORDER BY buyer_id, created_at ASC
    ),

    -- Prva poruka prodavca u razgovoru sa svakim kupcem
    first_replies AS (
      SELECT
        c.buyer_id,
        MIN(m.created_at) AS first_reply_at
      FROM public.conversations c
      JOIN public.messages m
        ON m.conversation_id = c.id
       AND m.sender_id       = p_seller_id
      WHERE c.seller_id = p_seller_id
      GROUP BY c.buyer_id
    ),

    -- Razlika u satima (samo pozitivne, max 7 dana da se filtriraju outlieri)
    response_times AS (
      SELECT
        EXTRACT(EPOCH FROM (fr.first_reply_at - fo.order_created_at)) / 3600.0 AS hours
      FROM first_orders fo
      JOIN first_replies fr ON fr.buyer_id = fo.buyer_id
      WHERE fr.first_reply_at > fo.order_created_at
        AND EXTRACT(EPOCH FROM (fr.first_reply_at - fo.order_created_at)) / 3600.0 < 168
    )

  SELECT json_build_object(
    'orders_count',        (SELECT delivered_count FROM order_stats),
    'avg_rating',          (SELECT avg_rating       FROM rating_stats),
    'review_count',        (SELECT review_count     FROM rating_stats),
    'avg_response_hours',  (SELECT AVG(hours)::float FROM response_times)
  );
$$;

-- Dostupno i anonimnim korisnicima (profil prodavca je javan)
GRANT EXECUTE ON FUNCTION public.get_seller_stats(UUID) TO anon, authenticated;

-- >>> END MIGRATION: 20260228110000_seller_stats_rpc.sql <<<

-- >>> BEGIN MIGRATION: 20260228120000_seller_reply.sql <<<
-- Odgovor prodavca na recenziju
-- seller_reply_at pamti kada je prvi put odgovoreno (nepromenjivo nakon snimanja)

ALTER TABLE public.reviews
  ADD COLUMN IF NOT EXISTS seller_reply    TEXT,
  ADD COLUMN IF NOT EXISTS seller_reply_at TIMESTAMPTZ;

-- RPC funkcija — jedino mesto gde se vrši izmena odgovora.
-- SECURITY DEFINER + ručne provere umesto UPDATE policy-a, jer trebamo
-- atomičnu validaciju "nije prošlo 24h od prvog odgovora".
CREATE OR REPLACE FUNCTION public.add_seller_reply(
  p_review_id UUID,
  p_reply     TEXT
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_seller_id      UUID;
  v_has_reply      BOOLEAN;
  v_reply_at       TIMESTAMPTZ;
BEGIN
  SELECT seller_id,
         seller_reply IS NOT NULL,
         seller_reply_at
  INTO   v_seller_id, v_has_reply, v_reply_at
  FROM   public.reviews
  WHERE  id = p_review_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'review_not_found';
  END IF;

  -- Samo vlasnik profila prodavca može odgovoriti
  IF v_seller_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  -- Izmena odgovora dozvoljena samo unutar 24h od prvog odgovora
  IF v_has_reply AND v_reply_at IS NOT NULL
     AND NOW() - v_reply_at > INTERVAL '24 hours'
  THEN
    RAISE EXCEPTION 'reply_not_editable_after_24h';
  END IF;

  UPDATE public.reviews
  SET
    seller_reply    = p_reply,
    -- Čuva originalni timestamp pri izmeni (ne pomiče rok od 24h)
    seller_reply_at = COALESCE(seller_reply_at, NOW())
  WHERE id = p_review_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.add_seller_reply(UUID, TEXT) TO authenticated;

-- Eksplicitno zabrani direktan UPDATE na seller_reply kolone svima
-- (sve izmene moraju ići kroz RPC funkciju)
DROP POLICY IF EXISTS "Seller can update own reply" ON public.reviews;

-- >>> END MIGRATION: 20260228120000_seller_reply.sql <<<

-- >>> BEGIN MIGRATION: 20260228130000_perf_rpcs.sql <<<
-- ─────────────────────────────────────────────────────────────────────────────
-- 1. get_conversations_for_user
--    Zamenjuje 3N DB poziva u ChatService.getConversations().
--    Jedan round-trip: conversations JOIN profili + LATERAL poslednja poruka
--    + correlated subquery za broj nepročitanih (sve u DB-u, nema Flutter iteracije).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_conversations_for_user(p_user_id UUID)
RETURNS JSONB
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    jsonb_agg(row_to_json(t)::jsonb ORDER BY (row_to_json(t) ->> 'updated_at') DESC),
    '[]'::jsonb
  )
  FROM (
    SELECT
      c.id,
      c.buyer_id,
      c.seller_id,
      c.order_id,
      c.created_at,
      c.updated_at,
      COALESCE(
        CASE WHEN c.buyer_id = p_user_id
             THEN COALESCE(ps.farm_name, ps.display_name)
             ELSE COALESCE(pb.farm_name, pb.display_name)
        END,
        'Korisnik'
      )                                                                    AS other_party_name,
      CASE WHEN c.buyer_id = p_user_id
           THEN ps.profile_image_url
           ELSE pb.profile_image_url
      END                                                                  AS other_party_image_url,
      lm.body                                                              AS last_message_body,
      lm.created_at                                                        AS last_message_at,
      (SELECT COUNT(*)::int
         FROM messages m2
        WHERE m2.conversation_id = c.id
          AND m2.sender_id      != p_user_id
          AND m2.read_at         IS NULL)                                  AS unread_count
    FROM conversations c
    JOIN profiles pb ON pb.id = c.buyer_id
    JOIN profiles ps ON ps.id = c.seller_id
    LEFT JOIN LATERAL (
      SELECT body, created_at
        FROM messages
       WHERE conversation_id = c.id
       ORDER BY created_at DESC
       LIMIT 1
    ) lm ON true
    WHERE c.buyer_id = p_user_id OR c.seller_id = p_user_id
    ORDER BY c.updated_at DESC
    LIMIT 50
  ) t;
$$;

GRANT EXECUTE ON FUNCTION public.get_conversations_for_user(UUID) TO authenticated;


-- ─────────────────────────────────────────────────────────────────────────────
-- 2. get_seller_stats_dashboard
--    Zamenjuje N+N+1 loop u OrdersService.getSellerStats().
--    Jedan round-trip: COUNT na orders + JOIN sa products za prihod.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_seller_stats_dashboard(p_seller_id UUID)
RETURNS JSON
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH
    order_counts AS (
      SELECT
        COUNT(*)::int                                  AS total_count,
        COUNT(*) FILTER (WHERE status = 'sent')::int   AS pending_count
      FROM orders
      WHERE seller_id = p_seller_id
    ),
    -- Porudžbine sa jednim proizvodom (product_id direktno na order redu)
    single_revenue AS (
      SELECT COALESCE(SUM(o.quantity_kg * p.price_per_kg), 0.0) AS rev
      FROM   orders o
      JOIN   products p ON p.id = o.product_id
      WHERE  o.seller_id  = p_seller_id
        AND  o.product_id IS NOT NULL
        AND  o.status      IN ('accepted', 'delivered')
    ),
    -- Porudžbine sa više proizvoda (stavke u order_items)
    multi_revenue AS (
      SELECT COALESCE(SUM(oi.quantity_kg * p.price_per_kg), 0.0) AS rev
      FROM   orders o
      JOIN   order_items oi ON oi.order_id  = o.id
      JOIN   products    p  ON p.id         = oi.product_id
      WHERE  o.seller_id  = p_seller_id
        AND  o.product_id IS NULL
        AND  o.status      IN ('accepted', 'delivered')
    )
  SELECT json_build_object(
    'pending_count', (SELECT pending_count FROM order_counts),
    'total_count',   (SELECT total_count   FROM order_counts),
    'revenue',       (SELECT rev FROM single_revenue) + (SELECT rev FROM multi_revenue)
  );
$$;

GRANT EXECUTE ON FUNCTION public.get_seller_stats_dashboard(UUID) TO authenticated;


-- ─────────────────────────────────────────────────────────────────────────────
-- 3. get_reviewable_order
--    Zamenjuje N+1 loop + extra N upita u ReviewsService.getReviewableOrder().
--    Direktan query sa NOT EXISTS — vraća prvu isporučenu nerecenziranu porudžbinu.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_reviewable_order(
  p_buyer_id  UUID,
  p_seller_id UUID
)
RETURNS JSON
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT json_build_object(
    'order_id',     o.id,
    'product_id',   COALESCE(o.product_id,   oi.product_id),
    'product_name', COALESCE(o.product_name, oi.product_name)
  )
  FROM orders o
  LEFT JOIN LATERAL (
    SELECT product_id, product_name
      FROM order_items
     WHERE order_id = o.id
     ORDER BY created_at ASC
     LIMIT 1
  ) oi ON o.product_id IS NULL
  WHERE  o.buyer_id  = p_buyer_id
    AND  o.seller_id = p_seller_id
    AND  o.status    = 'delivered'
    AND  NOT EXISTS (
           SELECT 1 FROM reviews r
            WHERE r.order_id  = o.id
              AND r.buyer_id  = p_buyer_id
         )
    AND  COALESCE(o.product_id, oi.product_id) IS NOT NULL
  ORDER BY o.created_at DESC
  LIMIT 1;
$$;

GRANT EXECUTE ON FUNCTION public.get_reviewable_order(UUID, UUID) TO authenticated;

