-- >>> BEGIN MIGRATION: 20260301100000_orders_total_and_item_prices.sql <<<
-- orders: ukupna suma porudžbine (za spec: total_amount)
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS total_amount NUMERIC;

