-- >>> BEGIN MIGRATION: 20260301110000_orders_archive_and_retention.sql <<<
-- Automatska arhivacija i data retention za porudžbine
-- 30 dana: status -> arhivirano, archived_at = now()
-- 12 meseci: trajno brisanje porudžbine i order_items (CASCADE)

-- Kolone na orders
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS archived_at TIMESTAMPTZ;
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;

-- Status 'arhivirano' u dozvoljene vrednosti
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_status_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_status_check
  CHECK (status IN ('sent', 'accepted', 'rejected', 'delivered', 'cancelled_by_seller', 'arhivirano'));

-- Funkcija: arhiviraj stare (30 dana) i obriši istekle (12 meseci)
-- U bazi je status = 'sent' (ne 'poslato')
CREATE OR REPLACE FUNCTION public.archive_and_expire_orders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- 1) Arhiviraj samo porudžbine u statusu 'sent' starije od 30 dana
  UPDATE public.orders
  SET status = 'arhivirano', archived_at = now()
  WHERE status = 'sent'
    AND created_at <= now() - interval '30 days';

  -- 2) Trajno obriši porudžbine sa expires_at <= now() (order_items se brišu CASCADE)
  DELETE FROM public.orders
  WHERE expires_at IS NOT NULL AND expires_at <= now();
END;
$$;

-- Zakazani posao (pg_cron): svaki dan u 02:00 UTC
-- Unschedule samo ako job postoji (inače pg_cron baca grešku)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'archive-and-expire-orders') THEN
      PERFORM cron.unschedule('archive-and-expire-orders');
    END IF;
  END IF;
EXCEPTION WHEN undefined_object THEN NULL;
END
$$;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.schedule(
      'archive-and-expire-orders',
      '0 2 * * *',
      'SELECT public.archive_and_expire_orders()'
    );
  END IF;
EXCEPTION WHEN undefined_object THEN NULL;
END
$$;

-- >>> END MIGRATION: 20260301110000_orders_archive_and_retention.sql <<<

-- >>> BEGIN MIGRATION: 20260301120000_order_retention_steps.sql <<<
-- =============================================================================
-- Predlozi za arhiviranje i retention – primenjeno korak po korak
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Korak 1: Funkcija za arhiviranje i brisanje
-- U bazi je status = 'sent' (ne 'poslato') – CHECK constraint u orders
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.handle_order_retention()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Arhiviranje: samo status 'sent', starije od 30 dana
  UPDATE public.orders
  SET status = 'arhivirano',
      archived_at = now()
  WHERE status = 'sent'
    AND created_at <= now() - interval '30 days';

  -- Brisanje: expires_at <= sada (order_items se brišu CASCADE)
  DELETE FROM public.orders
  WHERE expires_at <= now();
END;
$$;

-- Zadržavamo i staru funkciju kao wrapper (cron može da poziva bilo koju)
CREATE OR REPLACE FUNCTION public.archive_and_expire_orders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.handle_order_retention();
END;
$$;


-- -----------------------------------------------------------------------------
-- Korak 2: FOREIGN KEY sa ON DELETE CASCADE na order_items
-- (Već postoji u 20260228000000_order_items.sql; ovde eksplicitno osiguravamo.)
-- -----------------------------------------------------------------------------
ALTER TABLE public.order_items
  DROP CONSTRAINT IF EXISTS order_items_order_id_fkey;

ALTER TABLE public.order_items
  ADD CONSTRAINT order_items_order_id_fkey
  FOREIGN KEY (order_id)
  REFERENCES public.orders(id)
  ON DELETE CASCADE;


-- -----------------------------------------------------------------------------
-- Korak 3: pg_cron – dnevno u 03:00
-- Unschedule samo ako job postoji (inače pg_cron baca grešku)
-- -----------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'archive-and-expire-orders') THEN
      PERFORM cron.unschedule('archive-and-expire-orders');
    END IF;
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'daily_order_retention') THEN
      PERFORM cron.unschedule('daily_order_retention');
    END IF;
  END IF;
EXCEPTION WHEN undefined_object THEN NULL;
END
$$;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.schedule(
      'daily_order_retention',
      '0 3 * * *',
      'SELECT public.handle_order_retention()'
    );
  END IF;
EXCEPTION WHEN undefined_object THEN NULL;
END
$$;


-- -----------------------------------------------------------------------------
-- Korak 4: expires_at NOT NULL + DEFAULT (100% sigurnost)
-- Prvo popunimo postojeće redove, pa constraint i default za buduće insert-e
-- -----------------------------------------------------------------------------
UPDATE public.orders
SET expires_at = created_at + interval '12 months'
WHERE expires_at IS NULL;

ALTER TABLE public.orders
  ALTER COLUMN expires_at SET NOT NULL;

-- Pri kreiranju porudžbine: ako expires_at nije poslat, baza postavlja now() + 12 meseci
ALTER TABLE public.orders
  ALTER COLUMN expires_at SET DEFAULT (now() + interval '12 months');

-- >>> END MIGRATION: 20260301120000_order_retention_steps.sql <<<

-- >>> BEGIN MIGRATION: 20260301130000_orders_retention_indexes.sql <<<
-- Indeksi za brzo arhiviranje, brisanje i listanje porudžbina (100k+ redova)
-- =============================================================================
-- Za produkciju bez locka: pokreni indekse ručno sa CONCURRENTLY (van migracije).

-- 1) Arhiviranje: UPDATE ... WHERE status = 'sent' AND created_at <= ...
CREATE INDEX IF NOT EXISTS idx_orders_status_created_at
  ON public.orders (status, created_at)
  WHERE status = 'sent';

-- 2) Brisanje isteklih: DELETE ... WHERE expires_at <= now()
CREATE INDEX IF NOT EXISTS idx_orders_expires_at
  ON public.orders (expires_at);

-- 3) Listanje po kupcu: buyer_id + status + created_at DESC
CREATE INDEX IF NOT EXISTS idx_orders_buyer_status_created
  ON public.orders (buyer_id, status, created_at DESC);

-- 4) Listanje po prodavcu: seller_id + status + created_at DESC
CREATE INDEX IF NOT EXISTS idx_orders_seller_status_created
  ON public.orders (seller_id, status, created_at DESC);

-- >>> END MIGRATION: 20260301130000_orders_retention_indexes.sql <<<

-- >>> BEGIN MIGRATION: 20260301140000_seller_inbox_rpc.sql <<<
-- RPC za seller inbox – jedan round-trip umesto 2+5C+2O upita
-- Zamenjuje N+1 petlju u SellerInboxService.getInboxItems()

ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS buyer_address TEXT;

CREATE OR REPLACE FUNCTION public.get_seller_inbox(
  p_seller_id UUID,
  p_limit INT DEFAULT 20,
  p_offset INT DEFAULT 0
)
RETURNS JSONB
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH
  -- Konverzacije sa JOIN-ovima
  conv_rows AS (
    SELECT
      'conversation'::text AS item_type,
      c.updated_at AS sort_date,
      c.id AS conversation_id,
      c.order_id AS order_id,
      c.buyer_id AS buyer_id,
      COALESCE(pb.farm_name, pb.display_name, 'Kupac') AS other_party_name,
      pb.profile_image_url AS other_party_image_url,
      lm.body AS last_message_body,
      (SELECT COUNT(*)::int FROM messages m2
       WHERE m2.conversation_id = c.id
         AND m2.sender_id != p_seller_id
         AND m2.read_at IS NULL) AS unread_count,
      COALESCE(o.product_name, oi_first.product_name) AS product_name,
      COALESCE(o.quantity_kg::float8, oi_first.quantity_kg::float8) AS quantity_kg,
      COALESCE(o.unit_type, oi_first.unit_type) AS unit_type,
      o.status AS status,
      CASE o.status
        WHEN 'sent' THEN 'Poslato'
        WHEN 'accepted' THEN 'Prihvaćeno'
        WHEN 'rejected' THEN 'Odbijeno'
        WHEN 'delivered' THEN 'Isporučeno'
        WHEN 'cancelled_by_seller' THEN 'Otkazano'
        WHEN 'arhivirano' THEN 'Arhivirano'
        ELSE 'Poslato'
      END AS status_label,
      o.buyer_phone AS buyer_phone,
      o.note AS note,
      o.buyer_city AS buyer_city,
      o.buyer_address AS buyer_address
    FROM conversations c
    JOIN profiles pb ON pb.id = c.buyer_id
    LEFT JOIN orders o ON o.id = c.order_id
    LEFT JOIN LATERAL (
      SELECT
        CASE WHEN (SELECT COUNT(*) FROM order_items WHERE order_id = c.order_id) > 1
             THEN (SELECT COUNT(*)::text FROM order_items WHERE order_id = c.order_id) || ' proizvoda'
             ELSE (SELECT product_name FROM order_items WHERE order_id = c.order_id LIMIT 1)
        END AS product_name,
        (SELECT quantity_kg FROM order_items WHERE order_id = c.order_id LIMIT 1) AS quantity_kg,
        (SELECT unit_type FROM order_items WHERE order_id = c.order_id LIMIT 1) AS unit_type
    ) oi_first ON c.order_id IS NOT NULL AND o.product_id IS NULL
    LEFT JOIN LATERAL (
      SELECT body FROM messages
      WHERE conversation_id = c.id
      ORDER BY created_at DESC
      LIMIT 1
    ) lm ON true
    WHERE c.seller_id = p_seller_id
  ),
  -- Porudžbine bez konverzacije
  order_ids_with_conv AS (
    SELECT DISTINCT order_id FROM conversations
    WHERE seller_id = p_seller_id AND order_id IS NOT NULL
  ),
  order_rows AS (
    SELECT
      'order'::text AS item_type,
      o.created_at AS sort_date,
      o.id AS order_id,
      NULL::uuid AS conversation_id,
      o.buyer_id AS buyer_id,
      COALESCE(pb.farm_name, pb.display_name, 'Kupac') AS other_party_name,
      pb.profile_image_url AS other_party_image_url,
      NULL::text AS last_message_body,
      0 AS unread_count,
      COALESCE(o.product_name, oi_first.product_name) AS product_name,
      COALESCE(o.quantity_kg::float8, oi_first.quantity_kg::float8) AS quantity_kg,
      COALESCE(o.unit_type, oi_first.unit_type) AS unit_type,
      o.status AS status,
      CASE o.status
        WHEN 'sent' THEN 'Poslato'
        WHEN 'accepted' THEN 'Prihvaćeno'
        WHEN 'rejected' THEN 'Odbijeno'
        WHEN 'delivered' THEN 'Isporučeno'
        WHEN 'cancelled_by_seller' THEN 'Otkazano'
        WHEN 'arhivirano' THEN 'Arhivirano'
        ELSE 'Poslato'
      END AS status_label,
      o.buyer_phone AS buyer_phone,
      o.note AS note,
      o.buyer_city AS buyer_city,
      o.buyer_address AS buyer_address
    FROM orders o
    JOIN profiles pb ON pb.id = o.buyer_id
    LEFT JOIN LATERAL (
      SELECT
        CASE WHEN (SELECT COUNT(*) FROM order_items WHERE order_id = o.id) > 1
             THEN (SELECT COUNT(*)::text FROM order_items WHERE order_id = o.id) || ' proizvoda'
             ELSE (SELECT product_name FROM order_items WHERE order_id = o.id LIMIT 1)
        END AS product_name,
        (SELECT quantity_kg FROM order_items WHERE order_id = o.id LIMIT 1) AS quantity_kg,
        (SELECT unit_type FROM order_items WHERE order_id = o.id LIMIT 1) AS unit_type
    ) oi_first ON o.product_id IS NULL
    WHERE o.seller_id = p_seller_id
      AND o.id NOT IN (SELECT order_id FROM order_ids_with_conv WHERE order_id IS NOT NULL)
  ),
  -- Multi-item: product_name = "N proizvoda"
  combined AS (
    SELECT * FROM conv_rows
    UNION ALL
    SELECT * FROM order_rows
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'type', item_type,
        'sort_date', to_char(sort_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS'),
        'order_id', order_id,
        'conversation_id', conversation_id,
        'buyer_id', buyer_id,
        'other_party_name', other_party_name,
        'other_party_image_url', other_party_image_url,
        'product_name', product_name,
        'quantity_kg', quantity_kg,
        'unit_type', unit_type,
        'status', status,
        'last_message_body', last_message_body,
        'unread_count', unread_count,
        'status_label', status_label,
        'buyer_phone', buyer_phone,
        'note', note,
        'buyer_city', buyer_city,
        'buyer_address', buyer_address
      )
      ORDER BY sort_date DESC
    ),
    '[]'::jsonb
  )
  FROM (
    SELECT * FROM combined
    LIMIT p_limit OFFSET p_offset
  ) AS limited_combined;
$$;

GRANT EXECUTE ON FUNCTION public.get_seller_inbox(UUID, INT, INT) TO authenticated;

