-- >>> BEGIN MIGRATION: 20260307170000_strict_bible_units_and_order_validation.sql <<<
-- Strict Bible backend rules:
-- 1) Allowed units are kg, L, kom.
-- 2) Legacy g rows are normalized to kg.
-- 3) create_order_with_items enforces min quantity + system step on server side.

-- Normalize legacy unit values before tightening constraints.
UPDATE public.products SET unit_type = 'kg' WHERE unit_type = 'g';
UPDATE public.orders SET unit_type = 'kg' WHERE unit_type = 'g';
UPDATE public.order_items SET unit_type = 'kg' WHERE unit_type = 'g';

-- Tighten unit constraints.
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_unit_type_check;
ALTER TABLE public.products
  ADD CONSTRAINT products_unit_type_check
  CHECK (unit_type IN ('kg', 'L', 'kom'));

ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_unit_type_check;
ALTER TABLE public.orders
  ADD CONSTRAINT orders_unit_type_check
  CHECK (unit_type IN ('kg', 'L', 'kom'));

ALTER TABLE public.order_items DROP CONSTRAINT IF EXISTS order_items_unit_type_check;
ALTER TABLE public.order_items
  ADD CONSTRAINT order_items_unit_type_check
  CHECK (unit_type IN ('kg', 'L', 'kom'));

CREATE OR REPLACE FUNCTION public.create_order_with_items(
  p_buyer_id UUID,
  p_seller_id UUID,
  p_buyer_phone TEXT,
  p_items JSONB,
  p_note TEXT DEFAULT '',
  p_buyer_city TEXT DEFAULT '',
  p_buyer_address TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_order_id UUID;
  v_item JSONB;
  v_expires_at TIMESTAMPTZ;
  v_item_product_id UUID;
  v_item_quantity NUMERIC;
  v_item_unit_price NUMERIC;
  v_item_total_price NUMERIC;
  v_step NUMERIC;
  v_delta NUMERIC;
  v_total_amount NUMERIC := 0;
  v_product RECORD;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_buyer_id THEN
    RAISE EXCEPTION 'Unauthorized: buyer_id must match authenticated user';
  END IF;

  IF p_buyer_phone IS NULL OR TRIM(p_buyer_phone) = '' THEN
    RAISE EXCEPTION 'buyer_phone is required';
  END IF;

  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'items are required';
  END IF;

  v_expires_at := NOW() + INTERVAL '365 days';

  INSERT INTO public.orders (
    buyer_id, seller_id, product_id, product_name, quantity_kg,
    total_amount, note, buyer_city, buyer_phone, buyer_address,
    status, archived_at, expires_at
  )
  VALUES (
    p_buyer_id, p_seller_id, NULL, NULL, NULL,
    0,
    NULLIF(TRIM(p_note), ''), NULLIF(TRIM(p_buyer_city), ''), p_buyer_phone, p_buyer_address,
    'sent', NULL, v_expires_at
  )
  RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_item_product_id := (v_item->>'product_id')::UUID;
    v_item_quantity := (v_item->>'quantity_kg')::NUMERIC;

    IF v_item_product_id IS NULL THEN
      RAISE EXCEPTION 'product_id is required for each item';
    END IF;

    IF v_item_quantity IS NULL OR v_item_quantity <= 0 THEN
      RAISE EXCEPTION 'quantity_kg must be > 0 for product %', v_item_product_id;
    END IF;

    SELECT
      p.id,
      p.seller_id,
      p.name,
      p.category,
      p.unit_type,
      p.min_order_kg,
      p.price_per_kg,
      p.available_now
    INTO v_product
    FROM public.products p
    WHERE p.id = v_item_product_id
      AND p.seller_id = p_seller_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product % not found for seller %', v_item_product_id, p_seller_id;
    END IF;

    IF v_product.available_now IS NOT TRUE THEN
      RAISE EXCEPTION 'product % is currently unavailable', v_product.name;
    END IF;

    IF v_product.unit_type NOT IN ('kg', 'L', 'kom') THEN
      RAISE EXCEPTION 'invalid unit for product %', v_product.name;
    END IF;

    IF (lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%med%'
        OR lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%honey%')
       AND v_product.unit_type <> 'kg' THEN
      RAISE EXCEPTION 'honey products must use kg unit';
    END IF;

    IF v_item_quantity < v_product.min_order_kg THEN
      RAISE EXCEPTION 'quantity for % is below min_order_kg', v_product.name;
    END IF;

    v_step := CASE
      WHEN v_product.unit_type = 'kom' THEN 10::NUMERIC
      WHEN v_product.unit_type = 'L' THEN 1::NUMERIC
      WHEN lower(coalesce(v_product.category, '')) LIKE '%suhomesnat%' THEN 0.1::NUMERIC
      ELSE 0.5::NUMERIC
    END;

    v_delta := v_item_quantity - v_product.min_order_kg;

    IF abs(v_delta - (ROUND(v_delta / v_step) * v_step)) > 0.000001 THEN
      RAISE EXCEPTION 'quantity for % must align with system step %', v_product.name, v_step;
    END IF;

    v_item_unit_price := v_product.price_per_kg;
    v_item_total_price := v_item_quantity * v_item_unit_price;

    INSERT INTO public.order_items (
      order_id, product_id, product_name, quantity_kg, unit_type,
      unit_price, total_price
    )
    VALUES (
      v_order_id,
      v_item_product_id,
      v_product.name,
      v_item_quantity,
      v_product.unit_type,
      v_item_unit_price,
      v_item_total_price
    );

    v_total_amount := v_total_amount + v_item_total_price;
  END LOOP;

  UPDATE public.orders
  SET total_amount = v_total_amount
  WHERE id = v_order_id;

  RETURN v_order_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_order_with_items(UUID, UUID, TEXT, JSONB, TEXT, TEXT, TEXT) TO authenticated;

-- >>> END MIGRATION: 20260307170000_strict_bible_units_and_order_validation.sql <<<

-- >>> BEGIN MIGRATION: 20260307190000_use_product_order_step_in_order_validation.sql <<<
-- Keep strict backend validation, but prioritize product.order_step when provided.

CREATE OR REPLACE FUNCTION public.create_order_with_items(
  p_buyer_id UUID,
  p_seller_id UUID,
  p_buyer_phone TEXT,
  p_items JSONB,
  p_note TEXT DEFAULT '',
  p_buyer_city TEXT DEFAULT '',
  p_buyer_address TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_order_id UUID;
  v_item JSONB;
  v_expires_at TIMESTAMPTZ;
  v_item_product_id UUID;
  v_item_quantity NUMERIC;
  v_item_unit_price NUMERIC;
  v_item_total_price NUMERIC;
  v_step NUMERIC;
  v_delta NUMERIC;
  v_total_amount NUMERIC := 0;
  v_product RECORD;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_buyer_id THEN
    RAISE EXCEPTION 'Unauthorized: buyer_id must match authenticated user';
  END IF;

  IF p_buyer_phone IS NULL OR TRIM(p_buyer_phone) = '' THEN
    RAISE EXCEPTION 'buyer_phone is required';
  END IF;

  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'items are required';
  END IF;

  v_expires_at := NOW() + INTERVAL '365 days';

  INSERT INTO public.orders (
    buyer_id, seller_id, product_id, product_name, quantity_kg,
    total_amount, note, buyer_city, buyer_phone, buyer_address,
    status, archived_at, expires_at
  )
  VALUES (
    p_buyer_id, p_seller_id, NULL, NULL, NULL,
    0,
    NULLIF(TRIM(p_note), ''), NULLIF(TRIM(p_buyer_city), ''), p_buyer_phone, p_buyer_address,
    'sent', NULL, v_expires_at
  )
  RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_item_product_id := (v_item->>'product_id')::UUID;
    v_item_quantity := (v_item->>'quantity_kg')::NUMERIC;

    IF v_item_product_id IS NULL THEN
      RAISE EXCEPTION 'product_id is required for each item';
    END IF;

    IF v_item_quantity IS NULL OR v_item_quantity <= 0 THEN
      RAISE EXCEPTION 'quantity_kg must be > 0 for product %', v_item_product_id;
    END IF;

    SELECT
      p.id,
      p.seller_id,
      p.name,
      p.category,
      p.unit_type,
      p.min_order_kg,
      p.order_step,
      p.price_per_kg,
      p.available_now
    INTO v_product
    FROM public.products p
    WHERE p.id = v_item_product_id
      AND p.seller_id = p_seller_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product % not found for seller %', v_item_product_id, p_seller_id;
    END IF;

    IF v_product.available_now IS NOT TRUE THEN
      RAISE EXCEPTION 'product % is currently unavailable', v_product.name;
    END IF;

    IF v_product.unit_type NOT IN ('kg', 'L', 'kom') THEN
      RAISE EXCEPTION 'invalid unit for product %', v_product.name;
    END IF;

    IF (lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%med%'
        OR lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%honey%')
       AND v_product.unit_type <> 'kg' THEN
      RAISE EXCEPTION 'honey products must use kg unit';
    END IF;

    IF v_item_quantity < v_product.min_order_kg THEN
      RAISE EXCEPTION 'quantity for % is below min_order_kg', v_product.name;
    END IF;

    v_step := CASE
      WHEN v_product.order_step IS NOT NULL AND v_product.order_step > 0
        THEN v_product.order_step::NUMERIC
      WHEN v_product.unit_type = 'kom' THEN 10::NUMERIC
      WHEN v_product.unit_type = 'L' THEN 1::NUMERIC
      WHEN lower(coalesce(v_product.category, '')) LIKE '%suhomesnat%' THEN 0.1::NUMERIC
      ELSE 0.5::NUMERIC
    END;

    v_delta := v_item_quantity - v_product.min_order_kg;

    IF abs(v_delta - (ROUND(v_delta / v_step) * v_step)) > 0.000001 THEN
      RAISE EXCEPTION 'quantity for % must align with order step %', v_product.name, v_step;
    END IF;

    v_item_unit_price := v_product.price_per_kg;
    v_item_total_price := v_item_quantity * v_item_unit_price;

    INSERT INTO public.order_items (
      order_id, product_id, product_name, quantity_kg, unit_type,
      unit_price, total_price
    )
    VALUES (
      v_order_id,
      v_item_product_id,
      v_product.name,
      v_item_quantity,
      v_product.unit_type,
      v_item_unit_price,
      v_item_total_price
    );

    v_total_amount := v_total_amount + v_item_total_price;
  END LOOP;

  UPDATE public.orders
  SET total_amount = v_total_amount
  WHERE id = v_order_id;

  RETURN v_order_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_order_with_items(UUID, UUID, TEXT, JSONB, TEXT, TEXT, TEXT) TO authenticated;

-- >>> END MIGRATION: 20260307190000_use_product_order_step_in_order_validation.sql <<<

-- >>> BEGIN MIGRATION: 20260307203000_order_step_lte_min_order_constraint.sql <<<
-- Enforce explicit product order step bounds in database.
-- Rule: order_step must be positive and cannot exceed min_order_kg.

UPDATE public.products
SET min_order_kg = 1
WHERE min_order_kg IS NULL OR min_order_kg <= 0;

UPDATE public.products
SET order_step = min_order_kg
WHERE order_step IS NULL OR order_step <= 0 OR order_step > min_order_kg;

ALTER TABLE public.products
  DROP CONSTRAINT IF EXISTS products_min_order_positive;

ALTER TABLE public.products
  ADD CONSTRAINT products_min_order_positive
  CHECK (min_order_kg > 0);

ALTER TABLE public.products
  DROP CONSTRAINT IF EXISTS products_order_step_lte_min_order;

ALTER TABLE public.products
  ADD CONSTRAINT products_order_step_lte_min_order
  CHECK (order_step <= min_order_kg);

-- >>> END MIGRATION: 20260307203000_order_step_lte_min_order_constraint.sql <<<

-- >>> BEGIN MIGRATION: 20260307220000_kackavalj_order_step_100g.sql <<<
-- Enforce 100g ordering step for kackavalj products.
-- Rule: order_step = 0.1 kg when unit is kg and min_order_kg >= 0.1.

UPDATE public.products
SET order_step = 0.1
WHERE unit_type = 'kg'
  AND min_order_kg >= 0.1
  AND (
    lower(category) LIKE '%ka%kavalj%'
    OR lower(name) LIKE '%ka%kavalj%'
  );

-- >>> END MIGRATION: 20260307220000_kackavalj_order_step_100g.sql <<<

-- >>> BEGIN MIGRATION: 20260307232000_buyer_reviews.sql <<<
-- Seller -> buyer reviews so both sides have ratings.

CREATE TABLE IF NOT EXISTS public.buyer_reviews (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  buyer_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  rating SMALLINT NOT NULL CHECK (rating >= 1 AND rating <= 5),
  comment TEXT DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (seller_id, order_id)
);

CREATE INDEX IF NOT EXISTS idx_buyer_reviews_buyer_id
  ON public.buyer_reviews (buyer_id);

CREATE INDEX IF NOT EXISTS idx_buyer_reviews_seller_id
  ON public.buyer_reviews (seller_id);

ALTER TABLE public.buyer_reviews ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Buyer reviews are viewable by everyone" ON public.buyer_reviews;
CREATE POLICY "Buyer reviews are viewable by everyone"
  ON public.buyer_reviews FOR SELECT
  TO public
  USING (true);

DROP POLICY IF EXISTS "Sellers can insert buyer reviews" ON public.buyer_reviews;
CREATE POLICY "Sellers can insert buyer reviews"
  ON public.buyer_reviews FOR INSERT
  TO authenticated
  WITH CHECK (
    auth.uid() = seller_id
    AND EXISTS (
      SELECT 1
      FROM public.orders o
      WHERE o.id = order_id
        AND o.seller_id = seller_id
        AND o.buyer_id = buyer_id
        AND (o.status = 'delivered' OR o.status = 'arhivirano')
    )
  );

