-- >>> BEGIN MIGRATION: 20260308002000_enforce_order_status_transitions.sql <<<
-- Enforce forward-only order status transitions at DB level.
-- Prevents invalid backward jumps and stale/racy updates.

CREATE OR REPLACE FUNCTION public.enforce_order_status_transition()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_allowed BOOLEAN := false;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_allowed := CASE OLD.status
    WHEN 'sent' THEN NEW.status IN ('accepted', 'rejected')
    WHEN 'accepted' THEN NEW.status IN ('shipped', 'cancelled_by_seller')
    WHEN 'shipped' THEN NEW.status IN ('delivered', 'cancelled_by_seller')
    WHEN 'rejected' THEN NEW.status = 'arhivirano'
    WHEN 'cancelled_by_seller' THEN NEW.status = 'arhivirano'
    WHEN 'delivered' THEN NEW.status = 'arhivirano'
    WHEN 'arhivirano' THEN false
    ELSE false
  END;

  IF NOT v_allowed THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Nedozvoljena tranzicija statusa porudzbine.',
      DETAIL = format('order_id=%s, old_status=%s, new_status=%s', NEW.id, OLD.status, NEW.status),
      HINT = 'Dozvoljeno: sent->accepted/rejected; accepted->shipped/cancelled_by_seller; shipped->delivered/cancelled_by_seller; rejected/cancelled_by_seller/delivered->arhivirano.';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_order_status_transition ON public.orders;
CREATE TRIGGER trg_enforce_order_status_transition
  BEFORE UPDATE OF status ON public.orders
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_order_status_transition();

-- >>> END MIGRATION: 20260308002000_enforce_order_status_transitions.sql <<<

-- >>> BEGIN MIGRATION: 20260308003000_order_status_audit_log.sql <<<
-- Audit trail for order status changes (who changed status and when).

CREATE TABLE IF NOT EXISTS public.order_status_audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  old_status TEXT NOT NULL,
  new_status TEXT NOT NULL,
  changed_by_role TEXT NOT NULL CHECK (changed_by_role IN ('buyer', 'seller', 'system')),
  changed_by_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_order_status_audit_logs_order_changed_at
  ON public.order_status_audit_logs (order_id, changed_at DESC);

ALTER TABLE public.order_status_audit_logs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Order participants can view status audit logs" ON public.order_status_audit_logs;
CREATE POLICY "Order participants can view status audit logs"
  ON public.order_status_audit_logs FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1
      FROM public.orders o
      WHERE o.id = order_id
        AND (auth.uid() = o.buyer_id OR auth.uid() = o.seller_id)
    )
  );

GRANT SELECT ON public.order_status_audit_logs TO authenticated;

CREATE OR REPLACE FUNCTION public.log_order_status_change_audit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id UUID;
  v_actor_role TEXT;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_actor_id := auth.uid();

  IF v_actor_id IS NOT NULL AND v_actor_id = NEW.buyer_id THEN
    v_actor_role := 'buyer';
  ELSIF v_actor_id IS NOT NULL AND v_actor_id = NEW.seller_id THEN
    v_actor_role := 'seller';
  ELSE
    v_actor_role := 'system';
  END IF;

  INSERT INTO public.order_status_audit_logs (
    order_id,
    old_status,
    new_status,
    changed_by_role,
    changed_by_user_id,
    changed_at
  )
  VALUES (
    NEW.id,
    OLD.status,
    NEW.status,
    v_actor_role,
    v_actor_id,
    NOW()
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_log_order_status_change_audit ON public.orders;
CREATE TRIGGER trg_log_order_status_change_audit
  AFTER UPDATE OF status ON public.orders
  FOR EACH ROW
  EXECUTE FUNCTION public.log_order_status_change_audit();

-- >>> END MIGRATION: 20260308003000_order_status_audit_log.sql <<<

-- >>> BEGIN MIGRATION: 20260312090000_seller_loyalty_stats.sql <<<
-- Statistika lojalnosti kupaca za prodavca:
-- - broj kupaca koji su poručivali 2+ puta
-- - ukupan broj "ponovljenih" kupovina (sve preko prve po kupcu)
--
-- Računa se samo nad porudžbinama koje su uspešno završene
-- (isporučene ili arhivirane nakon isporuke).

CREATE OR REPLACE FUNCTION public.get_seller_loyalty_stats(p_seller_id UUID)
RETURNS JSON
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH buyer_orders AS (
    SELECT
      buyer_id,
      COUNT(*)::int AS cnt
    FROM public.orders
    WHERE seller_id = p_seller_id
      AND status IN ('delivered', 'arhivirano')
    GROUP BY buyer_id
  )
  SELECT json_build_object(
    'repeat_buyers', COALESCE(COUNT(*) FILTER (WHERE cnt >= 2), 0),
    'repeat_orders', COALESCE(SUM(GREATEST(cnt - 1, 0))::int, 0)
  )
  FROM buyer_orders;
$$;

GRANT EXECUTE ON FUNCTION public.get_seller_loyalty_stats(UUID) TO anon, authenticated;

-- >>> END MIGRATION: 20260312090000_seller_loyalty_stats.sql <<<

