-- >>> BEGIN MIGRATION: 20260322120000_buyer_reply_on_buyer_reviews.sql <<<
-- Odgovor kupca na recenziju prodavca (jedan odgovor, izmena do 24h kao kod add_seller_reply)

ALTER TABLE public.buyer_reviews
  ADD COLUMN IF NOT EXISTS buyer_reply    TEXT,
  ADD COLUMN IF NOT EXISTS buyer_reply_at TIMESTAMPTZ;

CREATE OR REPLACE FUNCTION public.add_buyer_reply(
  p_review_id UUID,
  p_reply     TEXT
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_buyer_id      UUID;
  v_has_reply     BOOLEAN;
  v_reply_at      TIMESTAMPTZ;
BEGIN
  IF p_reply IS NULL OR trim(p_reply) = '' THEN
    RAISE EXCEPTION 'empty_reply';
  END IF;

  SELECT buyer_id,
         buyer_reply IS NOT NULL AND trim(buyer_reply) <> '',
         buyer_reply_at
  INTO   v_buyer_id, v_has_reply, v_reply_at
  FROM   public.buyer_reviews
  WHERE  id = p_review_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'review_not_found';
  END IF;

  IF v_buyer_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF v_has_reply AND v_reply_at IS NOT NULL
     AND NOW() - v_reply_at > INTERVAL '24 hours'
  THEN
    RAISE EXCEPTION 'reply_not_editable_after_24h';
  END IF;

  UPDATE public.buyer_reviews
  SET
    buyer_reply    = trim(p_reply),
    buyer_reply_at = COALESCE(buyer_reply_at, NOW())
  WHERE id = p_review_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.add_buyer_reply(UUID, TEXT) TO authenticated;

-- >>> END MIGRATION: 20260322120000_buyer_reply_on_buyer_reviews.sql <<<

-- >>> BEGIN MIGRATION: 20260322140000_notify_on_new_reviews.sql <<<
-- In-app + push kada neko dobije novu recenziju (isti tok kao za porudžbine → invoke_send_push).

-- Kupac oceni prodavca → obaveštenje prodavcu
CREATE OR REPLACE FUNCTION public.notify_new_review_for_seller()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  snippet TEXT;
BEGIN
  snippet := trim(COALESCE(NEW.comment, ''));
  IF length(snippet) > 100 THEN
    snippet := left(snippet, 97) || '...';
  END IF;

  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (
    NEW.seller_id,
    NEW.order_id,
    'new_review',
    'Nova recenzija',
    'Kupac je ostavio ocenu ' || NEW.rating::text || '/5.' ||
      CASE WHEN snippet <> '' THEN ' „' || snippet || '“' ELSE '' END
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_review_insert_notify_seller ON public.reviews;
CREATE TRIGGER on_review_insert_notify_seller
  AFTER INSERT ON public.reviews
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_new_review_for_seller();

-- Prodavac oceni kupca → obaveštenje kupcu
CREATE OR REPLACE FUNCTION public.notify_new_buyer_review_for_buyer()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  snippet TEXT;
BEGIN
  snippet := trim(COALESCE(NEW.comment, ''));
  IF length(snippet) > 100 THEN
    snippet := left(snippet, 97) || '...';
  END IF;

  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (
    NEW.buyer_id,
    NEW.order_id,
    'new_buyer_review',
    'Nova recenzija o tebi',
    'Prodavac je ostavio ocenu ' || NEW.rating::text || '/5.' ||
      CASE WHEN snippet <> '' THEN ' „' || snippet || '“' ELSE '' END
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_buyer_review_insert_notify_buyer ON public.buyer_reviews;
CREATE TRIGGER on_buyer_review_insert_notify_buyer
  AFTER INSERT ON public.buyer_reviews
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_new_buyer_review_for_buyer();

-- >>> END MIGRATION: 20260322140000_notify_on_new_reviews.sql <<<

-- >>> BEGIN MIGRATION: 20260322140100_notification_type_enum_review_values.sql <<<
-- Hosted Supabase projekti često koriste enum public.notification_type za notifications.type.
-- Triggeri iz 20260322140000_notify_on_new_reviews.sql umeću 'new_review' i 'new_buyer_review';
-- bez ovih vrednosti INSERT pada sa: invalid input value for enum notification_type.

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public'
      AND t.typname = 'notification_type'
  ) THEN
    EXECUTE 'ALTER TYPE public.notification_type ADD VALUE IF NOT EXISTS ''new_review''';
    EXECUTE 'ALTER TYPE public.notification_type ADD VALUE IF NOT EXISTS ''new_buyer_review''';
  END IF;
END $$;

-- >>> END MIGRATION: 20260322140100_notification_type_enum_review_values.sql <<<

-- >>> BEGIN MIGRATION: 20260322140200_orders_rls_buyer_update.sql <<<
-- Kupac mora moći UPDATE (ručno arhiviranje, itd.). Do sada je postojala samo prodavčeva UPDATE politika.
DROP POLICY IF EXISTS "Buyers can update own orders" ON public.orders;
CREATE POLICY "Buyers can update own orders" ON public.orders
  FOR UPDATE TO authenticated
  USING (auth.uid() = buyer_id)
  WITH CHECK (auth.uid() = buyer_id);

-- >>> END MIGRATION: 20260322140200_orders_rls_buyer_update.sql <<<

-- >>> BEGIN MIGRATION: 20260322180000_orders_rls_consolidate_auth_select.sql <<<
-- Performance: izbegavati direktan auth.uid() u RLS izrazima (per-row eval).
-- Koristi se (SELECT auth.uid()) — preporuka Supabase Database Advisor.
-- Konsolidacija: jedna permissive UPDATE politika za učesnike (kupac ili prodavac),
-- umesto više odvojenih UPDATE politika za istu ulogu.

-- Ukloni sve poznate varijante (rep + moguća imena sa hosta / Dashboard-a).
DROP POLICY IF EXISTS "Buyers and sellers can view their orders" ON public.orders;
DROP POLICY IF EXISTS "Authenticated users can create orders" ON public.orders;
DROP POLICY IF EXISTS "Sellers can update order status" ON public.orders;
DROP POLICY IF EXISTS "Buyers can update own orders" ON public.orders;
DROP POLICY IF EXISTS "Buyers can archive their orders" ON public.orders;

CREATE POLICY "Buyers and sellers can view their orders" ON public.orders
  FOR SELECT TO authenticated
  USING (
    (SELECT auth.uid()) = buyer_id OR (SELECT auth.uid()) = seller_id
  );

CREATE POLICY "Authenticated users can create orders" ON public.orders
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT auth.uid()) = buyer_id);

-- Jedna UPDATE politika: i kupac i prodavac (poslovna pravila i dalje na triggerima).
CREATE POLICY "Participants can update their orders" ON public.orders
  FOR UPDATE TO authenticated
  USING (
    (SELECT auth.uid()) = buyer_id OR (SELECT auth.uid()) = seller_id
  )
  WITH CHECK (
    (SELECT auth.uid()) = buyer_id OR (SELECT auth.uid()) = seller_id
  );

-- >>> END MIGRATION: 20260322180000_orders_rls_consolidate_auth_select.sql <<<

