-- >>> BEGIN MIGRATION: 20260325001000_fix_product_stats_view.sql <<<
-- Ispravka: Brojanje svih relevantnih order statusa u product stats
-- Problem: View je brojao samo 'accepted' i 'delivered', ali statusi su 'Sent', 'Delivered', 'Arhivirano'

DROP VIEW IF EXISTS public.products_with_ratings CASCADE;

CREATE VIEW public.products_with_ratings AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.available_kg,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric AS avg_rating,
  COALESCE(r.review_count, 0)::bigint AS review_count,
  COALESCE(s.order_count, 0)::bigint AS order_count
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id
LEFT JOIN (
  SELECT product_id, COUNT(*)::bigint AS order_count
  FROM public.orders
  WHERE status IN ('accepted', 'delivered', 'Sent', 'Delivered', 'Arhivirano')
  GROUP BY product_id
) s ON p.id = s.product_id;

GRANT SELECT ON public.products_with_ratings TO anon;
GRANT SELECT ON public.products_with_ratings TO authenticated;

-- >>> END MIGRATION: 20260325001000_fix_product_stats_view.sql <<<

-- >>> BEGIN MIGRATION: 20260325002000_fix_product_stats_lowercase.sql <<<
-- Ispravka: Koristi lowercase statuse ('sent', 'arhivirano', 'delivered')
DROP VIEW IF EXISTS public.products_with_ratings CASCADE;

CREATE VIEW public.products_with_ratings AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.available_kg,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric AS avg_rating,
  COALESCE(r.review_count, 0)::bigint AS review_count,
  COALESCE(s.order_count, 0)::bigint AS order_count
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id
LEFT JOIN (
  SELECT product_id, COUNT(*)::bigint AS order_count
  FROM public.orders
  WHERE status IN ('accepted', 'delivered', 'sent', 'arhivirano')
  GROUP BY product_id
) s ON p.id = s.product_id;

GRANT SELECT ON public.products_with_ratings TO anon;
GRANT SELECT ON public.products_with_ratings TO authenticated;

-- >>> END MIGRATION: 20260325002000_fix_product_stats_lowercase.sql <<<

-- >>> BEGIN MIGRATION: 20260325003000_fix_product_stats_order_items.sql <<<
-- Ispravka: Brojanje prodaja iz order_items tabele (jer proizvodi mogu biti u multi-item narudžbinama)
DROP VIEW IF EXISTS public.products_with_ratings CASCADE;

CREATE VIEW public.products_with_ratings AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.available_kg,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric AS avg_rating,
  COALESCE(r.review_count, 0)::bigint AS review_count,
  COALESCE(s.order_count, 0)::bigint AS order_count
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id
LEFT JOIN (
  -- Brojanje iz order_items jer proizvodi mogu biti u multi-item narudžbinama
  SELECT DISTINCT oi.product_id, COUNT(DISTINCT oi.order_id)::bigint AS order_count
  FROM public.order_items oi
  INNER JOIN public.orders o ON oi.order_id = o.id
  WHERE o.status IN ('accepted', 'delivered', 'sent', 'arhivirano')
  GROUP BY oi.product_id
) s ON p.id = s.product_id;

GRANT SELECT ON public.products_with_ratings TO anon;
GRANT SELECT ON public.products_with_ratings TO authenticated;

-- >>> END MIGRATION: 20260325003000_fix_product_stats_order_items.sql <<<

-- >>> BEGIN MIGRATION: 20260325004000_fix_home_products_rpc.sql <<<
-- Ispravka: get_home_products RPC - broji iz order_items, ne iz orders
-- Problem: RPC je brojao iz orders.product_id direktno sa statusima ('accepted', 'delivered')
-- Ali: proizvodi su u order_items tabeli, i narudžbine imaju statusе ('sent', 'arhivirano', 'delivered')
-- Rezultat: sve prodaje su stale 0

DROP FUNCTION IF EXISTS public.get_home_products(int, text, text);

CREATE FUNCTION public.get_home_products(
  p_limit int DEFAULT 50,
  p_region text DEFAULT NULL,
  p_category text DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  seller_id uuid,
  category text,
  name text,
  price_per_kg numeric,
  min_order_kg numeric,
  available_kg numeric,
  description text,
  image_urls text[],
  pickup_options text[],
  location text,
  is_domestic boolean,
  available_now boolean,
  created_at timestamptz,
  order_count bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH sales AS (
    -- Broji iz order_items jer proizvodi mogu biti u multi-item narudžbinama
    SELECT oi.product_id, COUNT(DISTINCT oi.order_id)::bigint AS cnt
    FROM order_items oi
    INNER JOIN orders o ON oi.order_id = o.id
    WHERE o.status IN ('accepted', 'delivered', 'sent', 'arhivirano')
    GROUP BY oi.product_id
  )
  SELECT
    p.id, p.seller_id, p.category, p.name, p.price_per_kg, p.min_order_kg,
    p.available_kg, p.description, p.image_urls, p.pickup_options, p.location,
    p.is_domestic, p.available_now, p.created_at,
    COALESCE(s.cnt, 0)::bigint AS order_count
  FROM products p
  LEFT JOIN sales s ON s.product_id = p.id
  WHERE (p_region IS NULL OR p_region = '' OR p.location = p_region)
    AND (p_category IS NULL OR p_category = '' OR p.category = p_category)
  ORDER BY
    (p.created_at >= NOW() - INTERVAL '14 days') DESC,
    COALESCE(s.cnt, 0) DESC,
    p.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 100));
$$;

-- >>> END MIGRATION: 20260325004000_fix_home_products_rpc.sql <<<

-- >>> BEGIN MIGRATION: 20260326010000_fix_notifications_rls_insert.sql <<<
-- Omogući backend sistemima da kreiraju notifikacije
-- Zadržavamo SELECT politiku da korisnici vide samo svoje
-- Dodajemo INSERT politiku za system/triggers

-- Prvo, hajde da vidimo šta imamo
DROP POLICY IF EXISTS "Users manage own notifications" ON public.notifications;
DROP POLICY IF EXISTS "Users see own notifications" ON public.notifications;

-- SELECT: Korisnici vide samo svoje notifikacije
CREATE POLICY "Users see own notifications"
  ON public.notifications FOR SELECT
  TO authenticated
  USING (auth.uid() = user_id);

-- INSERT: Backend sistemi (trigger, Edge Functions) mogu da kreiraju notifikacije
-- Bez provere auth.uid() da backend može da kreira notifikacije za druge korisnike
CREATE POLICY "System can create notifications"
  ON public.notifications FOR INSERT
  TO authenticated, service_role
  WITH CHECK (true);

-- UPDATE: Samo korisnik može da ažurira svoje notifikacije (npr. mark as read)
CREATE POLICY "Users update own notifications"
  ON public.notifications FOR UPDATE
  TO authenticated
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- DELETE: Korisnik može da briše svoje notifikacije
CREATE POLICY "Users delete own notifications"
  ON public.notifications FOR DELETE
  TO authenticated
  USING (auth.uid() = user_id);

-- >>> END MIGRATION: 20260326010000_fix_notifications_rls_insert.sql <<<

-- >>> BEGIN MIGRATION: 20260326020000_test_push_notifications.sql <<<
-- Test push notifikacija
-- Ova skriptura pronalazi korisnika sa registrovanim tokenom i kreira test notifikaciju

DO $$
DECLARE
  test_user_id UUID;
  token_count INT;
BEGIN
  -- Pronađi bilo kog korisnika sa registrovanim FCM tokenom
  SELECT user_id INTO test_user_id
  FROM user_push_tokens
  LIMIT 1;

  -- Prebroj ukupne tokene
  SELECT COUNT(*) INTO token_count FROM user_push_tokens;

  IF test_user_id IS NOT NULL THEN
    RAISE NOTICE 'Pronađen korisnik sa tokenom: %', test_user_id;
    RAISE NOTICE 'Ukupni tokeni u sistemu: %', token_count;

    -- Kreiraj test notifikaciju
    INSERT INTO notifications (user_id, type, title, body)
    VALUES (
      test_user_id,
      'test_notification',
      '🧪 Test Notifikacija',
      'Ovo je test poruka. Ako vidite ovu notifikaciju, sistem radi!'
    );

    RAISE NOTICE 'Test notifikacija kreirana za korisnika: %', test_user_id;
  ELSE
    RAISE WARNING 'Nema korisnika sa registrovanim tokenom. Prvo musites da se prijave korisnici.';
  END IF;
END $$;

-- Prikaži sve registrovane tokene
SELECT
  user_id,
  platform,
  LEFT(token, 30) || '...' as token_preview,
  COUNT(*) OVER (PARTITION BY user_id) as tokens_per_user
FROM user_push_tokens
LIMIT 10;

