-- >>> BEGIN MIGRATION: 20260326150000_refine_multi_item_notification_text_and_total.sql <<<
-- Refine multi-item new order notification wording and include total amount.
-- Example: "2 proizvoda, prva stavka: Domaće mleko 3 L. Ukupno: 1250 RSD"

CREATE OR REPLACE FUNCTION public.build_order_notification_body(
  p_order_id UUID,
  p_fallback_product_name TEXT DEFAULT NULL,
  p_fallback_quantity NUMERIC DEFAULT NULL,
  p_fallback_unit_type TEXT DEFAULT 'kg'
)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
SET search_path = public
AS $$
DECLARE
  v_item_count INT;
  v_product_name TEXT;
  v_quantity NUMERIC;
  v_unit_type TEXT;
  v_quantity_text TEXT;
  v_total_amount NUMERIC;
  v_total_text TEXT;
BEGIN
  SELECT COUNT(*) INTO v_item_count
  FROM public.order_items
  WHERE order_id = p_order_id;

  SELECT o.total_amount
  INTO v_total_amount
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_total_amount IS NULL THEN
    SELECT COALESCE(SUM(oi.total_price), 0)
    INTO v_total_amount
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id;
  END IF;

  IF v_item_count >= 1 THEN
    SELECT product_name, quantity_kg, unit_type
    INTO v_product_name, v_quantity, v_unit_type
    FROM public.order_items
    WHERE order_id = p_order_id
    ORDER BY product_name ASC, product_id ASC
    LIMIT 1;
  ELSE
    v_product_name := p_fallback_product_name;
    v_quantity := p_fallback_quantity;
    v_unit_type := COALESCE(NULLIF(p_fallback_unit_type, ''), 'kg');
  END IF;

  IF v_product_name IS NULL OR btrim(v_product_name) = '' THEN
    RETURN 'Nova porudžbina';
  END IF;

  v_quantity_text := CASE
    WHEN v_quantity IS NULL THEN NULL
    WHEN trunc(v_quantity) = v_quantity THEN trunc(v_quantity)::text
    ELSE trim(trailing '.' from trim(trailing '0' from v_quantity::text))
  END;

  v_total_text := CASE
    WHEN v_total_amount IS NULL OR v_total_amount <= 0 THEN NULL
    WHEN trunc(v_total_amount) = v_total_amount THEN trunc(v_total_amount)::text
    ELSE trim(trailing '.' from trim(trailing '0' from v_total_amount::text))
  END;

  IF v_item_count > 1 THEN
    IF v_quantity_text IS NULL OR v_quantity_text = '' THEN
      IF v_total_text IS NULL THEN
        RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name;
      END IF;
      RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name || '. Ukupno: ' || v_total_text || ' RSD';
    END IF;

    IF v_total_text IS NULL THEN
      RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name || ' – ' || v_quantity_text || ' ' || COALESCE(NULLIF(v_unit_type, ''), 'kg');
    END IF;

    RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name || ' – ' || v_quantity_text || ' ' || COALESCE(NULLIF(v_unit_type, ''), 'kg') || '. Ukupno: ' || v_total_text || ' RSD';
  END IF;

  IF v_quantity_text IS NULL OR v_quantity_text = '' THEN
    RETURN 'Proizvod: ' || v_product_name;
  END IF;

  RETURN 'Proizvod: ' || v_product_name || ' – ' || v_quantity_text || ' ' || COALESCE(NULLIF(v_unit_type, ''), 'kg');
END;
$$;

UPDATE public.notifications n
SET body = public.build_order_notification_body(
  n.order_id,
  o.product_name,
  o.quantity_kg,
  o.unit_type
)
FROM public.orders o
WHERE n.order_id = o.id
  AND n.type = 'new_order';

-- >>> END MIGRATION: 20260326150000_refine_multi_item_notification_text_and_total.sql <<<

-- >>> BEGIN MIGRATION: 20260326153000_add_multi_item_units_summary_to_notifications.sql <<<
-- Add unit/quantity summary for multi-item new order notifications.
-- Example: "2 proizvoda, prva stavka: Domaće mleko – 3 L. Jedinice: 2 (6 kg + 3 L). Ukupno: 4080 RSD"

CREATE OR REPLACE FUNCTION public.build_order_notification_body(
  p_order_id UUID,
  p_fallback_product_name TEXT DEFAULT NULL,
  p_fallback_quantity NUMERIC DEFAULT NULL,
  p_fallback_unit_type TEXT DEFAULT 'kg'
)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
SET search_path = public
AS $$
DECLARE
  v_item_count INT;
  v_product_name TEXT;
  v_quantity NUMERIC;
  v_unit_type TEXT;
  v_quantity_text TEXT;
  v_total_amount NUMERIC;
  v_total_text TEXT;
  v_unit_kind_count INT;
  v_units_summary TEXT;
BEGIN
  SELECT COUNT(*) INTO v_item_count
  FROM public.order_items
  WHERE order_id = p_order_id;

  SELECT o.total_amount
  INTO v_total_amount
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_total_amount IS NULL THEN
    SELECT COALESCE(SUM(oi.total_price), 0)
    INTO v_total_amount
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id;
  END IF;

  IF v_item_count >= 1 THEN
    SELECT product_name, quantity_kg, unit_type
    INTO v_product_name, v_quantity, v_unit_type
    FROM public.order_items
    WHERE order_id = p_order_id
    ORDER BY product_name ASC, product_id ASC
    LIMIT 1;

    SELECT COUNT(*) INTO v_unit_kind_count
    FROM (
      SELECT oi.unit_type
      FROM public.order_items oi
      WHERE oi.order_id = p_order_id
      GROUP BY oi.unit_type
    ) u;

    SELECT string_agg(
      qty_text || ' ' || unit_type,
      ' + '
      ORDER BY unit_type
    )
    INTO v_units_summary
    FROM (
      SELECT
        oi.unit_type,
        CASE
          WHEN trunc(SUM(oi.quantity_kg)) = SUM(oi.quantity_kg)
            THEN trunc(SUM(oi.quantity_kg))::text
          ELSE trim(trailing '.' from trim(trailing '0' from SUM(oi.quantity_kg)::text))
        END AS qty_text
      FROM public.order_items oi
      WHERE oi.order_id = p_order_id
      GROUP BY oi.unit_type
    ) s;
  ELSE
    v_product_name := p_fallback_product_name;
    v_quantity := p_fallback_quantity;
    v_unit_type := COALESCE(NULLIF(p_fallback_unit_type, ''), 'kg');
    v_unit_kind_count := NULL;
    v_units_summary := NULL;
  END IF;

  IF v_product_name IS NULL OR btrim(v_product_name) = '' THEN
    RETURN 'Nova porudžbina';
  END IF;

  v_quantity_text := CASE
    WHEN v_quantity IS NULL THEN NULL
    WHEN trunc(v_quantity) = v_quantity THEN trunc(v_quantity)::text
    ELSE trim(trailing '.' from trim(trailing '0' from v_quantity::text))
  END;

  v_total_text := CASE
    WHEN v_total_amount IS NULL OR v_total_amount <= 0 THEN NULL
    WHEN trunc(v_total_amount) = v_total_amount THEN trunc(v_total_amount)::text
    ELSE trim(trailing '.' from trim(trailing '0' from v_total_amount::text))
  END;

  IF v_item_count > 1 THEN
    IF v_quantity_text IS NULL OR v_quantity_text = '' THEN
      RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name
        || CASE WHEN v_unit_kind_count IS NOT NULL AND v_units_summary IS NOT NULL
                THEN '. Jedinice: ' || v_unit_kind_count::text || ' (' || v_units_summary || ')'
                ELSE ''
           END
        || CASE WHEN v_total_text IS NOT NULL
                THEN '. Ukupno: ' || v_total_text || ' RSD'
                ELSE ''
           END;
    END IF;

    RETURN v_item_count::text || ' proizvoda, prva stavka: ' || v_product_name || ' – ' || v_quantity_text || ' ' || COALESCE(NULLIF(v_unit_type, ''), 'kg')
      || CASE WHEN v_unit_kind_count IS NOT NULL AND v_units_summary IS NOT NULL
              THEN '. Jedinice: ' || v_unit_kind_count::text || ' (' || v_units_summary || ')'
              ELSE ''
         END
      || CASE WHEN v_total_text IS NOT NULL
              THEN '. Ukupno: ' || v_total_text || ' RSD'
              ELSE ''
         END;
  END IF;

  IF v_quantity_text IS NULL OR v_quantity_text = '' THEN
    RETURN 'Proizvod: ' || v_product_name;
  END IF;

  RETURN 'Proizvod: ' || v_product_name || ' – ' || v_quantity_text || ' ' || COALESCE(NULLIF(v_unit_type, ''), 'kg');
END;
$$;

UPDATE public.notifications n
SET body = public.build_order_notification_body(
  n.order_id,
  o.product_name,
  o.quantity_kg,
  o.unit_type
)
FROM public.orders o
WHERE n.order_id = o.id
  AND n.type = 'new_order';

-- >>> END MIGRATION: 20260326153000_add_multi_item_units_summary_to_notifications.sql <<<

-- >>> BEGIN MIGRATION: 20260327000000_optimize_categories_indexes.sql <<<
-- Optimizuj kategorije za brže lookup-e i sortiranje
-- Index za parent_id lookup (za getChildCategories i grouping)
CREATE INDEX IF NOT EXISTS idx_categories_parent_id
ON categories(parent_id, "order");

-- Index za order sorting (ako se često sortira samo po order)
CREATE INDEX IF NOT EXISTS idx_categories_order
ON categories("order");

-- Composite index za kombinovanu pretagu (parent_id i order)
-- Smanjuje potrebu za multi-step soriranjem
COMMENT ON INDEX idx_categories_parent_id IS 'Enables fast category grouping by parent and ordering within groups';

-- >>> END MIGRATION: 20260327000000_optimize_categories_indexes.sql <<<

-- >>> BEGIN MIGRATION: 20260327010000_optimize_fcm_batch_operations.sql <<<
-- Optimizuj FCM batch operations za brže slanje push notifikacija
-- Dodaj indeks na token za brže lookup-e pri brisanju
CREATE INDEX IF NOT EXISTS idx_user_push_tokens_token
ON user_push_tokens(token);

-- Dodaj composite index za brže brisanja (token, user_id)
CREATE INDEX IF NOT EXISTS idx_user_push_tokens_token_user_id
ON user_push_tokens(token, user_id);

-- Dodaj indeks na user_id ako već ne postoji (za getToken)
CREATE INDEX IF NOT EXISTS idx_user_push_tokens_user_id_created
ON user_push_tokens(user_id, created_at DESC);

COMMENT ON INDEX idx_user_push_tokens_token IS 'Enables fast single token lookup and bulk delete operations in FCM batch processing';
COMMENT ON INDEX idx_user_push_tokens_token_user_id IS 'Composite index for efficient token cleanup during batch operations';
COMMENT ON INDEX idx_user_push_tokens_user_id_created IS 'Enables fast user token queries with temporal ordering for cleanup jobs';

-- >>> END MIGRATION: 20260327010000_optimize_fcm_batch_operations.sql <<<

-- >>> BEGIN MIGRATION: 20260328150000_fix_order_status_notification_diacritics.sql <<<
-- Ensure order status notifications use Serbian diacritics.

CREATE OR REPLACE FUNCTION public.notify_order_status_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_title TEXT;
  v_body TEXT;
  v_target_user UUID;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'accepted' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina prihvaćena';
    v_body := 'Prodavac je prihvatio vašu porudžbinu.';
  ELSIF NEW.status = 'shipped' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina poslata';
    v_body := 'Prodavac je označio porudžbinu kao poslatu.';
  ELSIF NEW.status = 'rejected' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina odbijena';
    v_body := 'Prodavac je odbio vašu porudžbinu.';
  ELSIF NEW.status = 'cancelled_by_seller' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina otkazana';
    v_body := 'Prodavac je otkazao porudžbinu.';
  ELSIF NEW.status = 'delivered' THEN
    v_target_user := NEW.seller_id;
    v_title := 'Kupac potvrdio prijem';
    v_body := 'Kupac je potvrdio da je primio porudžbinu.';
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (v_target_user, NEW.id, 'order_status_changed', v_title, v_body);

  RETURN NEW;
END;
$$;

-- Backfill legacy ASCII-only texts so existing notifications are shown correctly.
UPDATE public.notifications
SET
  title = CASE title
    WHEN 'Porudzbina prihvacena' THEN 'Porudžbina prihvaćena'
    WHEN 'Porudzbina poslata' THEN 'Porudžbina poslata'
    WHEN 'Porudzbina odbijena' THEN 'Porudžbina odbijena'
    WHEN 'Porudzbina otkazana' THEN 'Porudžbina otkazana'
    ELSE title
  END,
  body = CASE body
    WHEN 'Prodavac je prihvatio vasu porudzbinu.' THEN 'Prodavac je prihvatio vašu porudžbinu.'
    WHEN 'Prodavac je oznacio porudzbinu kao poslatu.' THEN 'Prodavac je označio porudžbinu kao poslatu.'
    WHEN 'Prodavac je odbio vasu porudzbinu.' THEN 'Prodavac je odbio vašu porudžbinu.'
    WHEN 'Prodavac je otkazao porudzbinu.' THEN 'Prodavac je otkazao porudžbinu.'
    WHEN 'Kupac je potvrdio da je primio porudzbinu.' THEN 'Kupac je potvrdio da je primio porudžbinu.'
    ELSE body
  END
WHERE type = 'order_status_changed';

-- >>> END MIGRATION: 20260328150000_fix_order_status_notification_diacritics.sql <<<

