-- >>> BEGIN MIGRATION: 20260405130000_notify_admin_on_support_ticket.sql <<<
-- Na novi support tiket kreiraj adminima in-app notifikaciju.
-- Push se zatim automatski šalje preko postojećeg triggera na public.notifications.

CREATE OR REPLACE FUNCTION public.notify_admins_on_support_ticket()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  ticket_label text;
  title_text text;
  body_text text;
BEGIN
  ticket_label := COALESCE(NULLIF(NEW.ticket_number, ''), 'novi tiket');
  title_text := 'Novi tiket podrške';
  body_text := '[' || ticket_label || '] '
    || COALESCE(NULLIF(NEW.subject, ''), 'Bez naslova');

  INSERT INTO public.notifications (user_id, type, title, body)
  SELECT p.id, 'support_ticket_created', title_text, body_text
  FROM public.profiles p
  WHERE p.is_admin = true;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_support_ticket_notify_admins ON public.support_tickets;
CREATE TRIGGER on_support_ticket_notify_admins
  AFTER INSERT ON public.support_tickets
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_admins_on_support_ticket();

-- >>> END MIGRATION: 20260405130000_notify_admin_on_support_ticket.sql <<<

-- >>> BEGIN MIGRATION: 20260405140000_notification_type_support_ticket_created.sql <<<
-- Hosted projekat koristi notification_type enum.
-- Support tiket trigger upisuje support_ticket_created, pa vrednost mora postojati.

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public'
      AND t.typname = 'notification_type'
  ) THEN
    ALTER TYPE public.notification_type
      ADD VALUE IF NOT EXISTS 'support_ticket_created';
  END IF;
END
$$;

