-- >>> BEGIN MIGRATION: 20260405200000_conversation_user_prefs.sql <<<
-- Conversation user preferences: favorites & hidden per user per conversation
-- Fixes: set_conversation_user_prefs RPC and is_favorite/hidden missing from DB

CREATE TABLE IF NOT EXISTS public.conversation_user_prefs (
  conversation_id UUID NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  is_favorite     BOOLEAN NOT NULL DEFAULT false,
  hidden          BOOLEAN NOT NULL DEFAULT false,
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (conversation_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_conv_user_prefs_user
  ON public.conversation_user_prefs(user_id);

ALTER TABLE public.conversation_user_prefs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users manage own conversation prefs" ON public.conversation_user_prefs;
CREATE POLICY "Users manage own conversation prefs"
  ON public.conversation_user_prefs FOR ALL
  TO authenticated
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- ─── RPC: set_conversation_user_prefs ────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.set_conversation_user_prefs(
  p_conversation_id UUID,
  p_is_favorite     BOOLEAN DEFAULT NULL,
  p_hidden          BOOLEAN DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Verify caller participates in the conversation
  IF NOT EXISTS (
    SELECT 1 FROM public.conversations
    WHERE id = p_conversation_id
      AND (buyer_id = auth.uid() OR seller_id = auth.uid())
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  INSERT INTO public.conversation_user_prefs (conversation_id, user_id, is_favorite, hidden, updated_at)
  VALUES (
    p_conversation_id,
    auth.uid(),
    COALESCE(p_is_favorite, false),
    COALESCE(p_hidden, false),
    NOW()
  )
  ON CONFLICT (conversation_id, user_id) DO UPDATE SET
    is_favorite = COALESCE(p_is_favorite, conversation_user_prefs.is_favorite),
    hidden      = COALESCE(p_hidden,      conversation_user_prefs.hidden),
    updated_at  = NOW();
END;
$$;

GRANT EXECUTE ON FUNCTION public.set_conversation_user_prefs(UUID, BOOLEAN, BOOLEAN) TO authenticated;

-- ─── Update get_conversations_for_user to include is_favorite and hidden ─────

CREATE OR REPLACE FUNCTION public.get_conversations_for_user(p_user_id UUID)
RETURNS JSONB
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    jsonb_agg(row_to_json(t)::jsonb ORDER BY (row_to_json(t) ->> 'updated_at') DESC),
    '[]'::jsonb
  )
  FROM (
    SELECT
      c.id,
      c.buyer_id,
      c.seller_id,
      c.order_id,
      c.created_at,
      c.updated_at,
      COALESCE(
        CASE WHEN c.buyer_id = p_user_id
             THEN COALESCE(ps.farm_name, ps.display_name)
             ELSE COALESCE(pb.farm_name, pb.display_name)
        END,
        'Korisnik'
      )                                                                    AS other_party_name,
      CASE WHEN c.buyer_id = p_user_id
           THEN ps.profile_image_url
           ELSE pb.profile_image_url
      END                                                                  AS other_party_image_url,
      lm.body                                                              AS last_message_body,
      lm.created_at                                                        AS last_message_at,
      (SELECT COUNT(*)::int
         FROM messages m2
        WHERE m2.conversation_id = c.id
          AND m2.sender_id      != p_user_id
          AND m2.read_at         IS NULL)                                  AS unread_count,
      COALESCE(cup.is_favorite, false)                                     AS is_favorite,
      COALESCE(cup.hidden, false)                                          AS hidden
    FROM conversations c
    JOIN profiles pb ON pb.id = c.buyer_id
    JOIN profiles ps ON ps.id = c.seller_id
    LEFT JOIN conversation_user_prefs cup
      ON cup.conversation_id = c.id AND cup.user_id = p_user_id
    LEFT JOIN LATERAL (
      SELECT body, created_at
        FROM messages
       WHERE conversation_id = c.id
       ORDER BY created_at DESC
       LIMIT 1
    ) lm ON true
    WHERE (c.buyer_id = p_user_id OR c.seller_id = p_user_id)
      AND p_user_id = auth.uid()
    ORDER BY c.updated_at DESC
    LIMIT 50
  ) t;
$$;

GRANT EXECUTE ON FUNCTION public.get_conversations_for_user(UUID) TO authenticated;

-- >>> END MIGRATION: 20260405200000_conversation_user_prefs.sql <<<

-- >>> BEGIN MIGRATION: 20260409073500_add_push_health_checks.sql <<<
-- Push health checks for quick production diagnostics

CREATE OR REPLACE FUNCTION public.push_health_summary()
RETURNS TABLE (
  checked_at TIMESTAMPTZ,
  edge_config_ok BOOLEAN,
  functions_base_url TEXT,
  anon_key_present BOOLEAN,
  total_tokens BIGINT,
  users_with_tokens BIGINT,
  tokens_created_24h BIGINT,
  notifications_24h BIGINT,
  deliveries_24h BIGINT,
  successful_deliveries_24h BIGINT,
  failed_deliveries_24h BIGINT,
  success_rate_pct NUMERIC,
  last_notification_at TIMESTAMPTZ,
  last_delivery_at TIMESTAMPTZ,
  delivery_backlog_minutes NUMERIC,
  health TEXT
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $function$
WITH config AS (
  SELECT
    MAX(CASE WHEN key = 'functions_base_url' THEN value END) AS functions_base_url,
    MAX(CASE WHEN key = 'anon_key' THEN value END) AS anon_key
  FROM public.edge_config
),
token_stats AS (
  SELECT
    COUNT(*) AS total_tokens,
    COUNT(DISTINCT user_id) AS users_with_tokens,
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') AS tokens_created_24h
  FROM public.user_push_tokens
),
notification_stats AS (
  SELECT
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') AS notifications_24h,
    MAX(created_at) AS last_notification_at
  FROM public.notifications
),
delivery_stats AS (
  SELECT
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') AS deliveries_24h,
    COUNT(*) FILTER (
      WHERE created_at > NOW() - INTERVAL '24 hours'
        AND status = 'success'
    ) AS successful_deliveries_24h,
    COUNT(*) FILTER (
      WHERE created_at > NOW() - INTERVAL '24 hours'
        AND status IN ('error', 'partial', 'no_tokens', 'invalid_request')
    ) AS failed_deliveries_24h,
    MAX(created_at) AS last_delivery_at
  FROM public.push_delivery_logs
),
summary AS (
  SELECT
    NOW() AS checked_at,
    (config.functions_base_url IS NOT NULL AND config.functions_base_url <> ''
      AND config.anon_key IS NOT NULL AND config.anon_key <> '') AS edge_config_ok,
    config.functions_base_url,
    (config.anon_key IS NOT NULL AND config.anon_key <> '') AS anon_key_present,
    token_stats.total_tokens,
    token_stats.users_with_tokens,
    token_stats.tokens_created_24h,
    notification_stats.notifications_24h,
    delivery_stats.deliveries_24h,
    delivery_stats.successful_deliveries_24h,
    delivery_stats.failed_deliveries_24h,
    ROUND(
      CASE
        WHEN delivery_stats.deliveries_24h = 0 THEN 0
        ELSE (delivery_stats.successful_deliveries_24h::NUMERIC / delivery_stats.deliveries_24h::NUMERIC) * 100
      END,
      2
    ) AS success_rate_pct,
    notification_stats.last_notification_at,
    delivery_stats.last_delivery_at,
    ROUND(
      CASE
        WHEN notification_stats.last_notification_at IS NULL THEN 0
        WHEN delivery_stats.last_delivery_at IS NULL THEN EXTRACT(EPOCH FROM (NOW() - notification_stats.last_notification_at)) / 60.0
        WHEN delivery_stats.last_delivery_at < notification_stats.last_notification_at THEN EXTRACT(EPOCH FROM (notification_stats.last_notification_at - delivery_stats.last_delivery_at)) / 60.0
        ELSE 0
      END,
      2
    ) AS delivery_backlog_minutes
  FROM config, token_stats, notification_stats, delivery_stats
)
SELECT
  checked_at,
  edge_config_ok,
  functions_base_url,
  anon_key_present,
  total_tokens,
  users_with_tokens,
  tokens_created_24h,
  notifications_24h,
  deliveries_24h,
  successful_deliveries_24h,
  failed_deliveries_24h,
  success_rate_pct,
  last_notification_at,
  last_delivery_at,
  delivery_backlog_minutes,
  CASE
    WHEN NOT edge_config_ok THEN 'misconfigured'
    WHEN last_notification_at IS NOT NULL
      AND (last_delivery_at IS NULL OR last_delivery_at < last_notification_at - INTERVAL '5 minutes') THEN 'stalled'
    WHEN deliveries_24h > 0 AND success_rate_pct < 80 THEN 'degraded'
    ELSE 'ok'
  END AS health
FROM summary;
$function$;

CREATE OR REPLACE FUNCTION public.push_user_health(target_user_id UUID)
RETURNS TABLE (
  checked_at TIMESTAMPTZ,
  user_id UUID,
  token_count BIGINT,
  latest_token_at TIMESTAMPTZ,
  notifications_7d BIGINT,
  latest_notification_at TIMESTAMPTZ,
  latest_delivery_at TIMESTAMPTZ,
  latest_delivery_status TEXT,
  latest_delivery_error_count INTEGER,
  health TEXT
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $function$
WITH token_stats AS (
  SELECT
    COUNT(*) AS token_count,
    MAX(created_at) AS latest_token_at
  FROM public.user_push_tokens
  WHERE user_id = target_user_id
),
notification_stats AS (
  SELECT
    COUNT(*) FILTER (WHERE created_at > NOW() - INTERVAL '7 days') AS notifications_7d,
    MAX(created_at) AS latest_notification_at
  FROM public.notifications
  WHERE user_id = target_user_id
),
delivery_stats AS (
  SELECT
    created_at AS latest_delivery_at,
    status AS latest_delivery_status,
    CASE
      WHEN jsonb_typeof(errors) = 'array' THEN jsonb_array_length(errors)
      ELSE 0
    END AS latest_delivery_error_count
  FROM public.push_delivery_logs
  WHERE user_id = target_user_id
  ORDER BY created_at DESC
  LIMIT 1
)
SELECT
  NOW() AS checked_at,
  target_user_id AS user_id,
  token_stats.token_count,
  token_stats.latest_token_at,
  notification_stats.notifications_7d,
  notification_stats.latest_notification_at,
  delivery_stats.latest_delivery_at,
  delivery_stats.latest_delivery_status,
  COALESCE(delivery_stats.latest_delivery_error_count, 0) AS latest_delivery_error_count,
  CASE
    WHEN token_stats.token_count = 0 THEN 'missing_token'
    WHEN notification_stats.latest_notification_at IS NOT NULL
      AND (delivery_stats.latest_delivery_at IS NULL OR delivery_stats.latest_delivery_at < notification_stats.latest_notification_at - INTERVAL '5 minutes') THEN 'stalled'
    WHEN delivery_stats.latest_delivery_status IN ('error', 'partial', 'no_tokens', 'invalid_request') THEN delivery_stats.latest_delivery_status
    ELSE 'ok'
  END AS health
FROM token_stats
CROSS JOIN notification_stats
LEFT JOIN delivery_stats ON TRUE;
$function$;

COMMENT ON FUNCTION public.push_health_summary() IS
'High-level push pipeline health snapshot: config, token coverage, recent notifications, delivery success rate, and backlog signal.';

COMMENT ON FUNCTION public.push_user_health(UUID) IS
'User-scoped push health snapshot: token presence, latest notification, latest delivery result, and current health classification.';

-- >>> END MIGRATION: 20260409073500_add_push_health_checks.sql <<<

-- >>> BEGIN MIGRATION: 20260409074500_add_push_health_views.sql <<<
-- Dashboard-friendly views for push health monitoring

DROP VIEW IF EXISTS public.push_health_dashboard;

CREATE VIEW public.push_health_dashboard AS
SELECT
  checked_at,
  health,
  edge_config_ok,
  functions_base_url,
  anon_key_present,
  total_tokens,
  users_with_tokens,
  tokens_created_24h,
  notifications_24h,
  deliveries_24h,
  successful_deliveries_24h,
  failed_deliveries_24h,
  success_rate_pct,
  last_notification_at,
  last_delivery_at,
  delivery_backlog_minutes
FROM public.push_health_summary();

DROP VIEW IF EXISTS public.push_health_user_issues;

CREATE VIEW public.push_health_user_issues AS
WITH recent_users AS (
  SELECT DISTINCT user_id
  FROM public.notifications
  WHERE created_at > NOW() - INTERVAL '7 days'

  UNION

  SELECT DISTINCT user_id
  FROM public.user_push_tokens

  UNION

  SELECT DISTINCT user_id
  FROM public.push_delivery_logs
  WHERE created_at > NOW() - INTERVAL '7 days'
)
SELECT
  health.checked_at,
  health.user_id,
  health.health,
  health.token_count,
  health.latest_token_at,
  health.notifications_7d,
  health.latest_notification_at,
  health.latest_delivery_at,
  health.latest_delivery_status,
  health.latest_delivery_error_count
FROM recent_users users
CROSS JOIN LATERAL public.push_user_health(users.user_id) AS health
WHERE health.health <> 'ok';

COMMENT ON VIEW public.push_health_dashboard IS
'Single-row dashboard view over push_health_summary() for admin monitoring.';

COMMENT ON VIEW public.push_health_user_issues IS
'Dashboard view listing recent users with non-ok push health states.';

GRANT SELECT ON public.push_health_dashboard TO authenticated;
GRANT SELECT ON public.push_health_user_issues TO authenticated;

