-- >>> BEGIN MIGRATION: 20260415140000_product_fts_search.sql <<<
-- Full-text pretraga proizvoda
-- Unapređenje od ILIKE (samo name, bez indeksa) na FTS (name + description, GIN index, rangiranje)
-- Uključuje unaccent za srpske dijakritičke znakove (cajevi = Čajevi, kajmak = Kajmak)

-- 1. Ekstenzija za dijakritike
CREATE EXTENSION IF NOT EXISTS unaccent;

-- 2. search_vector kolona
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS search_vector tsvector;

-- 3. Trigger funkcija
CREATE OR REPLACE FUNCTION products_search_vector_update()
RETURNS trigger AS $$
BEGIN
  NEW.search_vector := to_tsvector('simple',
    unaccent(coalesce(NEW.name, '')) || ' ' ||
    unaccent(coalesce(NEW.description, ''))
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 4. Trigger na INSERT i UPDATE name/description
DROP TRIGGER IF EXISTS trg_products_search_vector ON public.products;
CREATE TRIGGER trg_products_search_vector
  BEFORE INSERT OR UPDATE OF name, description ON public.products
  FOR EACH ROW EXECUTE FUNCTION products_search_vector_update();

-- 5. Backfill svih postojećih redova
UPDATE public.products
SET search_vector = to_tsvector('simple',
  unaccent(coalesce(name, '')) || ' ' ||
  unaccent(coalesce(description, ''))
);

-- 6. GIN index za brzu pretragu (zamenjuje seq scan koji koristi ILIKE)
CREATE INDEX IF NOT EXISTS products_search_vector_gin
  ON public.products USING gin(search_vector);

-- 7. RPC za FTS pretragu sa rangiranjem relevantnosti
--    Koristi websearch_to_tsquery sintaksu: "domaći sir" = domaći AND sir
--    Vraća isti shape kao products_with_ratings, sortiran po relevantnosti
CREATE OR REPLACE FUNCTION search_products_fts(
  p_query             text,
  p_category          text    DEFAULT NULL,
  p_region            text    DEFAULT NULL,
  p_available_now     boolean DEFAULT NULL,
  p_exclude_seller_id uuid    DEFAULT NULL,
  p_limit             int     DEFAULT 20,
  p_offset            int     DEFAULT 0
)
RETURNS SETOF public.products_with_ratings
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT pwr.*
  FROM public.products_with_ratings pwr
  JOIN public.products p ON p.id = pwr.id
  WHERE
    (p_category         IS NULL OR pwr.category    = p_category)       AND
    (p_region           IS NULL OR pwr.location    = p_region)         AND
    (p_available_now    IS NULL OR pwr.available_now = p_available_now) AND
    (p_exclude_seller_id IS NULL OR pwr.seller_id  <> p_exclude_seller_id) AND
    p.search_vector @@ websearch_to_tsquery('simple', unaccent(p_query))
  ORDER BY
    ts_rank(p.search_vector, websearch_to_tsquery('simple', unaccent(p_query))) DESC,
    pwr.created_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION search_products_fts TO anon, authenticated;

-- >>> END MIGRATION: 20260415140000_product_fts_search.sql <<<

-- >>> BEGIN MIGRATION: 20260415150000_seller_verified_in_view.sql <<<
-- Dodaj seller_is_verified u products_with_ratings view
-- Kupci mogu videti verified badge na product card-u bez dodatnog API poziva

DROP VIEW IF EXISTS public.products_with_ratings CASCADE;

CREATE VIEW public.products_with_ratings AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.order_step,
  p.available_kg,
  p.unit_type,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.delivery_mode,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric   AS avg_rating,
  COALESCE(r.review_count, 0)::bigint  AS review_count,
  COALESCE(s.order_count, 0)::bigint   AS order_count,
  COALESCE(pr.is_verified, false)      AS seller_is_verified
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id
LEFT JOIN (
  SELECT product_id, COUNT(*)::bigint AS order_count
  FROM public.orders
  WHERE status IN ('accepted', 'delivered')
  GROUP BY product_id
) s ON p.id = s.product_id
LEFT JOIN public.profiles pr ON p.seller_id = pr.id;

GRANT SELECT ON public.products_with_ratings TO anon;
GRANT SELECT ON public.products_with_ratings TO authenticated;

-- Ponovo kreiraj search_products_fts jer CASCADE ga je obrisao
CREATE OR REPLACE FUNCTION search_products_fts(
  p_query             text,
  p_category          text    DEFAULT NULL,
  p_region            text    DEFAULT NULL,
  p_available_now     boolean DEFAULT NULL,
  p_exclude_seller_id uuid    DEFAULT NULL,
  p_limit             int     DEFAULT 20,
  p_offset            int     DEFAULT 0
)
RETURNS SETOF public.products_with_ratings
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT pwr.*
  FROM public.products_with_ratings pwr
  JOIN public.products p ON p.id = pwr.id
  WHERE
    (p_category         IS NULL OR pwr.category    = p_category)       AND
    (p_region           IS NULL OR pwr.location    = p_region)         AND
    (p_available_now    IS NULL OR pwr.available_now = p_available_now) AND
    (p_exclude_seller_id IS NULL OR pwr.seller_id  <> p_exclude_seller_id) AND
    p.search_vector @@ websearch_to_tsquery('simple', unaccent(p_query))
  ORDER BY
    ts_rank(p.search_vector, websearch_to_tsquery('simple', unaccent(p_query))) DESC,
    pwr.created_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION search_products_fts TO anon, authenticated;

-- RPC za admin: toggle is_verified za prodavca
CREATE OR REPLACE FUNCTION admin_set_seller_verified(
  p_seller_id uuid,
  p_verified  boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true
  ) THEN
    RAISE EXCEPTION 'Pristup odbijen: nije admin';
  END IF;

  UPDATE public.profiles
  SET is_verified = p_verified
  WHERE id = p_seller_id;
END;
$$;

GRANT EXECUTE ON FUNCTION admin_set_seller_verified TO authenticated;

-- >>> END MIGRATION: 20260415150000_seller_verified_in_view.sql <<<

-- >>> BEGIN MIGRATION: 20260418100000_add_courier_pickup_delivery_methods.sql <<<
-- Add 'courier' and 'pickup' as valid delivery methods.
-- 'agreement' is kept for backward compatibility with existing orders.

ALTER TABLE public.orders
  DROP CONSTRAINT IF EXISTS orders_delivery_method_check;

ALTER TABLE public.orders
  ADD CONSTRAINT orders_delivery_method_check
  CHECK (delivery_method IN ('agreement', 'pickup', 'courier', 'seller_delivery'));

-- Update RPC to accept new delivery methods
CREATE OR REPLACE FUNCTION public.create_order_with_items(
  p_buyer_id UUID,
  p_seller_id UUID,
  p_buyer_phone TEXT,
  p_items JSONB,
  p_note TEXT DEFAULT '',
  p_buyer_city TEXT DEFAULT '',
  p_buyer_address TEXT DEFAULT NULL,
  p_delivery_method TEXT DEFAULT 'courier',
  p_delivery_point_id UUID DEFAULT NULL,
  p_delivery_slot_id UUID DEFAULT NULL,
  p_delivery_fee_rsd NUMERIC DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_order_id UUID;
  v_item JSONB;
  v_expires_at TIMESTAMPTZ;
  v_item_product_id UUID;
  v_item_quantity NUMERIC;
  v_item_unit_price NUMERIC;
  v_item_total_price NUMERIC;
  v_step NUMERIC;
  v_delta NUMERIC;
  v_total_amount NUMERIC := 0;
  v_product RECORD;
  v_delivery_method TEXT := COALESCE(NULLIF(TRIM(p_delivery_method), ''), 'courier');
  v_delivery_point public.seller_delivery_points%ROWTYPE;
  v_delivery_slot public.seller_delivery_slots%ROWTYPE;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_buyer_id THEN
    RAISE EXCEPTION 'Unauthorized: buyer_id must match authenticated user';
  END IF;

  IF p_buyer_phone IS NULL OR TRIM(p_buyer_phone) = '' THEN
    RAISE EXCEPTION 'buyer_phone is required';
  END IF;

  IF p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'items are required';
  END IF;

  IF v_delivery_method NOT IN ('agreement', 'pickup', 'courier', 'seller_delivery') THEN
    RAISE EXCEPTION 'invalid delivery_method';
  END IF;

  IF v_delivery_method = 'seller_delivery' THEN
    IF p_delivery_point_id IS NULL OR p_delivery_slot_id IS NULL THEN
      RAISE EXCEPTION 'delivery point and slot are required for seller_delivery';
    END IF;

    SELECT *
    INTO v_delivery_point
    FROM public.seller_delivery_points
    WHERE id = p_delivery_point_id
      AND seller_id = p_seller_id
      AND is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'delivery point not found or inactive';
    END IF;

    SELECT *
    INTO v_delivery_slot
    FROM public.seller_delivery_slots
    WHERE id = p_delivery_slot_id
      AND delivery_point_id = p_delivery_point_id
      AND is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'delivery slot not found or inactive';
    END IF;
  END IF;

  v_expires_at := NOW() + INTERVAL '365 days';

  INSERT INTO public.orders (
    buyer_id,
    seller_id,
    product_id,
    product_name,
    quantity_kg,
    total_amount,
    note,
    buyer_city,
    buyer_phone,
    buyer_address,
    delivery_method,
    delivery_city,
    delivery_point_id,
    delivery_point_label,
    delivery_address,
    delivery_weekday,
    delivery_time_from,
    delivery_time_to,
    delivery_fee_rsd,
    status,
    archived_at,
    expires_at
  )
  VALUES (
    p_buyer_id,
    p_seller_id,
    NULL,
    NULL,
    NULL,
    0,
    NULLIF(TRIM(p_note), ''),
    NULLIF(TRIM(p_buyer_city), ''),
    p_buyer_phone,
    NULLIF(TRIM(p_buyer_address), ''),
    v_delivery_method,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_point.city ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_point.id ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_point.label ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_point.address ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_slot.weekday ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_slot.time_from ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN v_delivery_slot.time_to ELSE NULL END,
    CASE WHEN v_delivery_method = 'seller_delivery' THEN COALESCE(p_delivery_fee_rsd, v_delivery_slot.delivery_fee_rsd) ELSE NULL END,
    'sent',
    NULL,
    v_expires_at
  )
  RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_item_product_id := (v_item->>'product_id')::UUID;
    v_item_quantity := (v_item->>'quantity_kg')::NUMERIC;

    IF v_item_product_id IS NULL THEN
      RAISE EXCEPTION 'product_id is required for each item';
    END IF;

    IF v_item_quantity IS NULL OR v_item_quantity <= 0 THEN
      RAISE EXCEPTION 'quantity_kg must be > 0 for product %', v_item_product_id;
    END IF;

    SELECT
      p.id,
      p.seller_id,
      p.name,
      p.category,
      p.unit_type,
      p.min_order_kg,
      p.order_step,
      p.price_per_kg,
      p.available_now,
      p.delivery_mode
    INTO v_product
    FROM public.products p
    WHERE p.id = v_item_product_id
      AND p.seller_id = p_seller_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product % not found for seller %', v_item_product_id, p_seller_id;
    END IF;

    IF v_delivery_method = 'seller_delivery' THEN
      IF COALESCE(v_product.delivery_mode, 'none') = 'none' THEN
        RAISE EXCEPTION 'product % does not support seller delivery', v_product.name;
      END IF;

      IF v_product.delivery_mode = 'selected_points'
         AND NOT EXISTS (
           SELECT 1
           FROM public.product_delivery_points pdp
           WHERE pdp.product_id = v_item_product_id
             AND pdp.delivery_point_id = p_delivery_point_id
         ) THEN
        RAISE EXCEPTION 'delivery point is not allowed for product %', v_product.name;
      END IF;
    END IF;

    IF v_product.available_now IS NOT TRUE THEN
      RAISE EXCEPTION 'product % is currently unavailable', v_product.name;
    END IF;

    IF v_product.unit_type NOT IN ('kg', 'L', 'kom') THEN
      RAISE EXCEPTION 'invalid unit for product %', v_product.name;
    END IF;

    IF (lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%med%'
        OR lower(coalesce(v_product.name, '') || ' ' || coalesce(v_product.category, '')) LIKE '%honey%')
       AND v_product.unit_type <> 'kg' THEN
      RAISE EXCEPTION 'honey products must use kg unit';
    END IF;

    IF v_item_quantity < v_product.min_order_kg THEN
      RAISE EXCEPTION 'quantity for % is below min_order_kg', v_product.name;
    END IF;

    v_step := CASE
      WHEN v_product.order_step IS NOT NULL AND v_product.order_step > 0
        THEN v_product.order_step::NUMERIC
      WHEN v_product.unit_type = 'kom' THEN 10::NUMERIC
      WHEN v_product.unit_type = 'L' THEN 1::NUMERIC
      WHEN lower(coalesce(v_product.category, '')) LIKE '%suhomesnat%' THEN 0.1::NUMERIC
      ELSE 0.5::NUMERIC
    END;

    v_delta := v_item_quantity - v_product.min_order_kg;

    IF abs(v_delta - (ROUND(v_delta / v_step) * v_step)) > 0.000001 THEN
      RAISE EXCEPTION 'quantity for % must align with order step %', v_product.name, v_step;
    END IF;

    v_item_unit_price := v_product.price_per_kg;
    v_item_total_price := v_item_quantity * v_item_unit_price;

    INSERT INTO public.order_items (
      order_id, product_id, product_name, quantity_kg, unit_type,
      unit_price, total_price
    )
    VALUES (
      v_order_id,
      v_item_product_id,
      v_product.name,
      v_item_quantity,
      v_product.unit_type,
      v_item_unit_price,
      v_item_total_price
    );

    v_total_amount := v_total_amount + v_item_total_price;
  END LOOP;

  IF v_delivery_method = 'seller_delivery'
     AND v_delivery_slot.min_order_amount_rsd IS NOT NULL
     AND v_total_amount < v_delivery_slot.min_order_amount_rsd THEN
    RAISE EXCEPTION 'order total is below delivery slot minimum amount';
  END IF;

  UPDATE public.orders
  SET total_amount = v_total_amount
  WHERE id = v_order_id;

  RETURN v_order_id;
END;
$$;

-- >>> END MIGRATION: 20260418100000_add_courier_pickup_delivery_methods.sql <<<

-- >>> BEGIN MIGRATION: 20260418140000_fix_delivery_snapshot_check.sql <<<
-- Fix orders_delivery_snapshot_required_check to allow courier and pickup
-- without requiring delivery snapshot fields (which are only needed for seller_delivery).

ALTER TABLE public.orders
  DROP CONSTRAINT IF EXISTS orders_delivery_snapshot_required_check;

ALTER TABLE public.orders
  ADD CONSTRAINT orders_delivery_snapshot_required_check
  CHECK (
    delivery_method IN ('agreement', 'courier', 'pickup')
    OR (
      delivery_method = 'seller_delivery'
      AND delivery_city IS NOT NULL
      AND delivery_point_label IS NOT NULL
      AND delivery_address IS NOT NULL
      AND delivery_weekday IS NOT NULL
      AND delivery_time_from IS NOT NULL
      AND delivery_time_to IS NOT NULL
    )
  );

