-- Personalizovana obaveštenja: dodaj ime kupca u new_order notifikaciju

CREATE OR REPLACE FUNCTION public.notify_new_order()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  body_text TEXT;
  buyer_name TEXT;
BEGIN
  SELECT COALESCE(NULLIF(btrim(display_name), ''), 'Kupac')
  INTO buyer_name
  FROM public.profiles
  WHERE id = NEW.buyer_id;

  body_text := COALESCE(buyer_name, 'Kupac') || ': ' ||
    public.build_order_notification_body(
      NEW.id,
      NEW.product_name,
      NEW.quantity_kg,
      NEW.unit_type
    );

  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (NEW.seller_id, NEW.id, 'new_order', '🚜 Nova porudžbina', body_text);

  RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20260418180000_personalize_order_notifications.sql <<<

-- >>> BEGIN MIGRATION: 20260425171000_cleanup_duplicate_order_notifications.sql <<<
-- Cleanup and consolidate new order notifications.
-- Ensures only ONE personalized notification is sent for each new order.

-- 1. Drop all possible trigger names that might have been used for new order notifications
-- both regular and constraint triggers.
DROP TRIGGER IF EXISTS on_new_order ON public.orders;
DROP TRIGGER IF EXISTS trg_notify_new_order ON public.orders;
DROP TRIGGER IF EXISTS on_order_inserted ON public.orders;
DROP TRIGGER IF EXISTS notify_new_order_trigger ON public.orders;

-- 2. Ensure the personalized notification function is up to date.
-- Uses '🚜 Nova porudžbina' as title and 'Buyer: Product Info' as body.
CREATE OR REPLACE FUNCTION public.notify_new_order()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  body_text TEXT;
  buyer_name TEXT;
BEGIN
  -- Fetch buyer display name
  SELECT COALESCE(NULLIF(btrim(display_name), ''), 'Kupac')
  INTO buyer_name
  FROM public.profiles
  WHERE id = NEW.buyer_id;

  -- Build detailed body from order_items (if exist) or order fields (fallback)
  body_text := COALESCE(buyer_name, 'Kupac') || ': ' ||
    public.build_order_notification_body(
      NEW.id,
      NEW.product_name,
      NEW.quantity_kg,
      NEW.unit_type
    );

  -- Insert only ONE notification record.
  -- The type 'new_order' is used by the edge function to handle push delivery.
  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (NEW.seller_id, NEW.id, 'new_order', '🚜 Nova porudžbina', body_text);

  RETURN NEW;
END;
$$;

-- 3. Re-create the trigger as a CONSTRAINT TRIGGER.
-- This ensures it fires AFTER all operations in the transaction (like order_items insertion)
-- are complete, allowing build_order_notification_body to fetch correct item info.
CREATE CONSTRAINT TRIGGER on_new_order
  AFTER INSERT ON public.orders
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_new_order();

-- 4. Cleanup any duplicate notifications that might have been created recently (optional but good for data integrity)
-- We won't delete existing data to avoid confusion, but we could if needed.

-- >>> END MIGRATION: 20260425171000_cleanup_duplicate_order_notifications.sql <<<

-- >>> BEGIN MIGRATION: 20260427133000_chat_push_navigation.sql <<<
-- Dodavanje conversation_id u notifications i ažuriranje push trigera za chat navigaciju

-- 1. Dodaj kolonu u notifications tabelu
ALTER TABLE public.notifications 
ADD COLUMN IF NOT EXISTS conversation_id UUID REFERENCES public.conversations(id) ON DELETE SET NULL;

-- 2. Ažuriraj notify_new_message funkciju da ubacuje conversation_id
CREATE OR REPLACE FUNCTION public.notify_new_message()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_buyer_id UUID;
  v_seller_id UUID;
  v_recipient_id UUID;
  v_sender_name TEXT;
BEGIN
  SELECT buyer_id, seller_id INTO v_buyer_id, v_seller_id
  FROM public.conversations WHERE id = NEW.conversation_id;

  IF NEW.sender_id = v_buyer_id THEN
    v_recipient_id := v_seller_id;
  ELSE
    v_recipient_id := v_buyer_id;
  END IF;

  SELECT COALESCE(farm_name, display_name, 'Korisnik') INTO v_sender_name
  FROM public.profiles WHERE id = NEW.sender_id;

  INSERT INTO notifications (user_id, type, title, body, conversation_id)
  VALUES (
    v_recipient_id,
    'new_message',
    'Nova poruka',
    COALESCE(v_sender_name, 'Korisnik') || ': ' || LEFT(NEW.body, 80),
    NEW.conversation_id
  );
  RETURN NEW;
END;
$$;

-- 3. Ažuriraj invoke_send_push da uključuje conversation_id u payload
CREATE OR REPLACE FUNCTION public.invoke_send_push()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  base_url TEXT;
  anon_key TEXT;
  fn_url TEXT;
BEGIN
  SELECT value INTO base_url FROM public.edge_config WHERE key = 'functions_base_url' LIMIT 1;
  SELECT value INTO anon_key FROM public.edge_config WHERE key = 'anon_key' LIMIT 1;

  IF base_url IS NULL OR base_url = '' THEN
    RETURN NEW;
  END IF;

  fn_url := base_url || '/functions/v1/send-push';

  PERFORM net.http_post(
    url := fn_url,
    body := jsonb_build_object(
      'user_id', NEW.user_id,
      'title', COALESCE(NEW.title, ''),
      'body', COALESCE(NEW.body, ''),
      'type', COALESCE(NEW.type::text, ''),
      'order_id', CASE WHEN NEW.order_id IS NOT NULL THEN NEW.order_id::text ELSE '' END,
      'ticket_id', CASE WHEN NEW.ticket_id IS NOT NULL THEN NEW.ticket_id::text ELSE '' END,
      'conversation_id', CASE WHEN NEW.conversation_id IS NOT NULL THEN NEW.conversation_id::text ELSE '' END
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || COALESCE(anon_key, ''),
      'apikey', COALESCE(anon_key, '')
    ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'invoke_send_push: %', SQLERRM;
    RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20260427133000_chat_push_navigation.sql <<<

-- >>> BEGIN MIGRATION: 20260427210000_push_notification_hygiene.sql <<<
-- Notification Hygiene & Duplicate Prevention
-- 1. Ensure user_push_tokens has a unique constraint on token itself.
-- This prevents the same device from having multiple entries under different installation_ids.

-- Cleanup duplicate tokens first (keep only the most recent one for each token string)
DELETE FROM public.user_push_tokens a
USING public.user_push_tokens b
WHERE a.id < b.id 
  AND a.token = b.token;

-- Add unique constraint if it doesn't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'user_push_tokens_token_key') THEN
        ALTER TABLE public.user_push_tokens ADD CONSTRAINT user_push_tokens_token_key UNIQUE (token);
    END IF;
END $$;

-- 2. Aggressively drop any suspected legacy duplicate triggers on messages and orders
DROP TRIGGER IF EXISTS on_message_inserted ON public.messages;
DROP TRIGGER IF EXISTS trg_notify_new_message ON public.messages;
DROP TRIGGER IF EXISTS notify_new_message_trigger ON public.messages;

-- Ensure on_new_message is the ONLY trigger for chat notifications
-- We don't drop on_message_insert because it's used for updating conversation.updated_at

-- 3. Consolidate notify_new_message logic (ensure it's robust)
CREATE OR REPLACE FUNCTION public.notify_new_message()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_buyer_id UUID;
  v_seller_id UUID;
  v_recipient_id UUID;
  v_sender_name TEXT;
BEGIN
  -- Avoid self-notifications
  SELECT buyer_id, seller_id INTO v_buyer_id, v_seller_id
  FROM public.conversations WHERE id = NEW.conversation_id;

  IF NEW.sender_id = v_buyer_id THEN
    v_recipient_id := v_seller_id;
  ELSE
    v_recipient_id := v_buyer_id;
  END IF;

  -- If for some reason we can't find recipient, don't crash
  IF v_recipient_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(NULLIF(btrim(farm_name), ''), NULLIF(btrim(display_name), ''), 'Korisnik') INTO v_sender_name
  FROM public.profiles WHERE id = NEW.sender_id;

  -- Use UPSERT to prevent duplicate notifications for the exact same message in the same second
  -- (rare but protects against weird trigger edge cases)
  INSERT INTO public.notifications (user_id, type, title, body, conversation_id)
  VALUES (
    v_recipient_id,
    'new_message',
    'Nova poruka 💬',
    COALESCE(v_sender_name, 'Korisnik') || ': ' || LEFT(NEW.body, 80),
    NEW.conversation_id
  )
  ON CONFLICT DO NOTHING;
  
  RETURN NEW;
END;
$$;

-- 4. Cleanup old order triggers again just to be safe
DROP TRIGGER IF EXISTS on_new_order ON public.orders;
DROP TRIGGER IF EXISTS trg_notify_new_order ON public.orders;
DROP TRIGGER IF EXISTS notify_new_order_trigger ON public.orders;

-- 5. Fix potential duplication in notifications trigger itself
-- Ensure only ONE trigger exists for push invocation
DROP TRIGGER IF EXISTS notify_push_trigger ON public.notifications;
DROP TRIGGER IF EXISTS trg_invoke_send_push ON public.notifications;
-- The active one should be on_notification_insert_send_push (from 20260227220000)

-- >>> END MIGRATION: 20260427210000_push_notification_hygiene.sql <<<

-- >>> BEGIN MIGRATION: 20260428121000_review_reminder_notification.sql <<<
CREATE OR REPLACE FUNCTION public.notify_order_status_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_title TEXT;
  v_body TEXT;
  v_target_user UUID;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'accepted' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina prihvaćena';
    v_body := 'Prodavac je prihvatio vašu porudžbinu.';
  ELSIF NEW.status = 'shipped' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina poslata';
    v_body := 'Prodavac je označio porudžbinu kao poslatu.';
  ELSIF NEW.status = 'rejected' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina odbijena';
    v_body := 'Prodavac je odbio vašu porudžbinu.';
  ELSIF NEW.status = 'cancelled_by_seller' THEN
    v_target_user := NEW.buyer_id;
    v_title := 'Porudžbina otkazana';
    v_body := 'Prodavac je otkazao porudžbinu.';
  ELSIF NEW.status = 'delivered' THEN
    v_target_user := NEW.seller_id;
    v_title := 'Kupac potvrdio prijem';
    v_body := 'Kupac je potvrdio da je primio porudžbinu.';

    -- Dodatna notifikacija za kupca da oceni proizvod i prodavca
    INSERT INTO public.notifications (user_id, order_id, type, title, body)
    VALUES (NEW.buyer_id, NEW.id, 'order_status_changed', 'Ocenite porudžbinu', 'Vaša porudžbina je isporučena! Molimo vas odvojite trenutak da ocenite proizvod i prodavca.');
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, order_id, type, title, body)
  VALUES (v_target_user, NEW.id, 'order_status_changed', v_title, v_body);

  RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20260428121000_review_reminder_notification.sql <<<

-- >>> BEGIN MIGRATION: 20260428121100_home_products_ranking_by_rating.sql <<<
DROP FUNCTION IF EXISTS public.get_home_products(int, text, text);

CREATE FUNCTION public.get_home_products(
  p_limit int DEFAULT 50,
  p_region text DEFAULT NULL,
  p_category text DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  seller_id uuid,
  category text,
  name text,
  price_per_kg numeric,
  min_order_kg numeric,
  available_kg numeric,
  description text,
  image_urls text[],
  pickup_options text[],
  location text,
  is_domestic boolean,
  available_now boolean,
  created_at timestamptz,
  order_count bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH sales AS (
    SELECT oi.product_id, COUNT(DISTINCT oi.order_id)::bigint AS cnt
    FROM order_items oi
    INNER JOIN orders o ON oi.order_id = o.id
    WHERE o.status IN ('accepted', 'delivered', 'sent', 'arhivirano')
    GROUP BY oi.product_id
  ),
  ratings AS (
    SELECT product_id, AVG(rating)::numeric AS avg_rating
    FROM reviews
    GROUP BY product_id
  )
  SELECT
    p.id, p.seller_id, p.category, p.name, p.price_per_kg, p.min_order_kg,
    p.available_kg, p.description, p.image_urls, p.pickup_options, p.location,
    p.is_domestic, p.available_now, p.created_at,
    COALESCE(s.cnt, 0)::bigint AS order_count
  FROM products p
  LEFT JOIN sales s ON s.product_id = p.id
  LEFT JOIN ratings r ON r.product_id = p.id
  WHERE (p_region IS NULL OR p_region = '' OR p.location = p_region)
    AND (p_category IS NULL OR p_category = '' OR p.category = p_category)
  ORDER BY
    (p.created_at >= NOW() - INTERVAL '14 days') DESC,
    COALESCE(r.avg_rating, 0) DESC,
    COALESCE(s.cnt, 0) DESC,
    p.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 100));
$$;

-- >>> END MIGRATION: 20260428121100_home_products_ranking_by_rating.sql <<<

-- >>> BEGIN MIGRATION: 20260428163000_products_indexing.sql <<<
-- Optimizacija performansi za tabelu products
-- Dodavanje indeksa za kolone koje se najčešće koriste u filterima i sortiranju

-- 1. Indeks za seller_id (prikaz svih proizvoda jednog prodavca)
CREATE INDEX IF NOT EXISTS idx_products_seller_id ON public.products(seller_id);

-- 2. Indeks za category (filtriranje po kategoriji)
CREATE INDEX IF NOT EXISTS idx_products_category ON public.products(category);

-- 3. Indeks za location (filtriranje po regiji)
CREATE INDEX IF NOT EXISTS idx_products_location ON public.products(location);

-- 4. Indeks za datum kreiranja (osnovno sortiranje "Najnovije")
CREATE INDEX IF NOT EXISTS idx_products_created_at_desc ON public.products(created_at DESC);

-- 5. Kombinovani indeks za dostupnost (čest filter na pretrazi)
CREATE INDEX IF NOT EXISTS idx_products_available_now ON public.products(available_now) WHERE available_now = true;

