-- >>> BEGIN MIGRATION: 20260904150000_profiles_privacy_view.sql <<<
-- ============================================================================
-- Migracija 20260904150000: Privacy — javni prikaz profila bez osetljivih podataka
--
-- RLS na `profiles` dozvoljava svakom prijavljenom da čita SVE kolone svih
-- korisnika (uključujući `email` i `phone`). Ovaj view maskira osetljive
-- kolone i služi kao jedini javni izvor profila sa klijenta:
--   - `email`  vidí samo vlasnik ili admin
--   - `phone`  vidí vlasnik, admin, ili bilo ko ako je `phone_public = true`
-- ============================================================================

-- Osiguraj da kolona postal_code postoji na profiles tabeli
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS postal_code TEXT;

CREATE OR REPLACE VIEW public.public_profiles
WITH (security_invoker = on)
AS
SELECT
  p.id,
  CASE WHEN (auth.uid() = p.id OR EXISTS (
        SELECT 1 FROM public.profiles v WHERE v.id = auth.uid() AND v.is_admin
      )) THEN p.email ELSE NULL END AS email,
  CASE WHEN (p.phone_public OR auth.uid() = p.id OR EXISTS (
        SELECT 1 FROM public.profiles v WHERE v.id = auth.uid() AND v.is_admin
      )) THEN p.phone ELSE NULL END AS phone,
  p.display_name,
  p.city,
  p.postal_code,
  p.role,
  p.is_guest,
  p.farm_name,
  p.location,
  p.profile_image_url,
  p.phone_public,
  p.is_verified,
  p.seller_story,
  p.farm_gallery_urls,
  p.seller_tags,
  p.seller_quick_replies,
  p.is_admin,
  p.lat,
  p.lng,
  p.created_at
FROM public.profiles p;

-- Performanse: bezbedan indeks za auth subquery (auth.uid() = profile id)
CREATE INDEX IF NOT EXISTS idx_profiles_is_admin ON public.profiles(id, is_admin);

-- >>> END MIGRATION: 20260904150000_profiles_privacy_view.sql <<<

-- >>> BEGIN MIGRATION: 20260904160000_products_with_ratings_security_invoker.sql <<<
-- ============================================================================
-- Migracija 20260904160000: Sigurnost – products_with_ratings security_invoker
--
-- Rešava Supabase linter finding: "Security Definer View" za products_with_ratings.
--
-- 1. Kreira get_product_order_count() kao SECURITY DEFINER STABLE funkciju sa
--    fiksnim search_path-om kako bi se broj prihvaćenih/isporučenih porudžbina
--    mogao javno agregirati bez izlaganja privatnih redova tabele orders.
-- 2. Kreira is_seller_verified() kao SECURITY DEFINER STABLE funkciju kako bi
--    i neautorizovani (anon) posetioci videli verified bedž na kartici proizvoda.
-- 3. Postavlja WITH (security_invoker = on) na public.products_with_ratings
--    tako da se view izvršava sa pravima korisnika koji postavlja upit.
-- 4. Održava search_products_fts funkciju koja vraća SETOF products_with_ratings.
-- ============================================================================

-- 1. Helper funkcija za agregaciju broja porudžbina
CREATE OR REPLACE FUNCTION public.get_product_order_count(p_product_id uuid)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COUNT(*)::bigint
  FROM public.orders
  WHERE product_id = p_product_id
    AND status IN ('accepted', 'delivered');
$$;

GRANT EXECUTE ON FUNCTION public.get_product_order_count(uuid) TO anon, authenticated;

-- 2. Helper funkcija za status verifikacije prodavca (bezbedno za anon korisnike)
CREATE OR REPLACE FUNCTION public.is_seller_verified(p_seller_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(is_verified, false)
  FROM public.profiles
  WHERE id = p_seller_id;
$$;

GRANT EXECUTE ON FUNCTION public.is_seller_verified(uuid) TO anon, authenticated;

-- 3. Ažuriranje view-a sa security_invoker = on
CREATE OR REPLACE VIEW public.products_with_ratings
WITH (security_invoker = on)
AS
SELECT
  p.id,
  p.seller_id,
  p.category,
  p.name,
  p.price_per_kg,
  p.min_order_kg,
  p.order_step,
  p.available_kg,
  p.unit_type,
  p.description,
  p.image_urls,
  p.pickup_options,
  p.location,
  p.is_domestic,
  p.available_now,
  p.delivery_mode,
  p.created_at,
  COALESCE(r.avg_rating, 0)::numeric   AS avg_rating,
  COALESCE(r.review_count, 0)::bigint  AS review_count,
  public.get_product_order_count(p.id) AS order_count,
  public.is_seller_verified(p.seller_id) AS seller_is_verified
FROM public.products p
LEFT JOIN (
  SELECT product_id, AVG(rating)::numeric AS avg_rating, COUNT(*)::bigint AS review_count
  FROM public.reviews
  WHERE product_id IS NOT NULL
  GROUP BY product_id
) r ON p.id = r.product_id;

GRANT SELECT ON public.products_with_ratings TO anon, authenticated;

-- 4. Obezbedi da search_products_fts ostaje sinhronizovan
CREATE OR REPLACE FUNCTION public.search_products_fts(
  p_query             text,
  p_category          text    DEFAULT NULL,
  p_region            text    DEFAULT NULL,
  p_available_now     boolean DEFAULT NULL,
  p_exclude_seller_id uuid    DEFAULT NULL,
  p_limit             int     DEFAULT 20,
  p_offset            int     DEFAULT 0
)
RETURNS SETOF public.products_with_ratings
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT pwr.*
  FROM public.products_with_ratings pwr
  JOIN public.products p ON p.id = pwr.id
  WHERE
    (p_category          IS NULL OR pwr.category     = p_category)        AND
    (p_region            IS NULL OR pwr.location     = p_region)          AND
    (p_available_now     IS NULL OR pwr.available_now = p_available_now)  AND
    (p_exclude_seller_id IS NULL OR pwr.seller_id   <> p_exclude_seller_id) AND
    p.search_vector @@ websearch_to_tsquery('simple', unaccent(p_query))
  ORDER BY
    ts_rank(p.search_vector, websearch_to_tsquery('simple', unaccent(p_query))) DESC,
    pwr.created_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION public.search_products_fts TO anon, authenticated;

-- >>> END MIGRATION: 20260904160000_products_with_ratings_security_invoker.sql <<<

-- >>> BEGIN MIGRATION: 20260904170000_classified_ads_moderation_and_limits.sql <<<
-- ============================================================================
-- Migracija 20260904170000: Moderacija, rate-limit i normalizacija gradova za classified_ads
--  1. Osiguranje funkcije is_admin()
--  2. Proširenje statusa oglasa (podrška za 'rejected' i 'flagged')
--  3. Normalizacija naziva grada (trim + initcap)
--  4. Anti-spam rate-limit na INSERT (max 20 oglasa/24h, min razmak 10s za ne-admine)
--  5. Dozvola administratorima (is_admin) za moderaciju (UPDATE/DELETE) oglasa
--  6. RPC funkcija admin_moderate_classified_ad
-- ============================================================================

-- 1) Osiguraj funkciju is_admin()
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND is_admin = true
  );
END;
$$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated, service_role;

-- 2) Proširenje statusa oglasa
DO $$
BEGIN
  ALTER TABLE public.classified_ads DROP CONSTRAINT IF EXISTS classified_ads_status_check;
  ALTER TABLE public.classified_ads ADD CONSTRAINT classified_ads_status_check
    CHECK (status IN ('active', 'sold', 'archived', 'rejected', 'flagged'));
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;

-- 3) Normalizacija postojećih gradova u bazi
UPDATE public.classified_ads
SET city = trim(initcap(city))
WHERE city IS NOT NULL;

-- 4) Ažurirana funkcija validacije sa rate-limitom i normalizacijom grada
CREATE OR REPLACE FUNCTION public.classified_ad_validate()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Normalizacija naziva grada
  IF NEW.city IS NOT NULL THEN
    NEW.city := trim(initcap(NEW.city));
    IF length(NEW.city) < 2 THEN
      RAISE EXCEPTION 'Naziv grada ili mesta mora imati bar 2 karaktera.';
    END IF;
  END IF;

  -- Besplatni ili poziv oglasi imaju cenu 0
  IF NEW.price_type IN ('free', 'call') THEN
    NEW.price := 0;
  END IF;

  -- Maksimalan broj slika je 8
  IF coalesce(array_length(NEW.images, 1), 0) > 8 THEN
    RAISE EXCEPTION 'Maksimalan broj slika je 8.';
  END IF;

  -- Minimalna dužina naslova
  IF length(trim(NEW.title)) < 3 THEN
    RAISE EXCEPTION 'Naslov oglasa mora imati bar 3 karaktera.';
  END IF;

  -- Rate-limit za kreiranje novih oglasa (samo na INSERT i samo ako korisnik nije admin)
  IF TG_OP = 'INSERT' AND NOT public.is_admin() THEN
    -- A) Minimalni razmak između dva oglasa: 10 sekundi (sprečava dvostruki submit i botove)
    IF EXISTS (
      SELECT 1 FROM public.classified_ads
      WHERE user_id = NEW.user_id
        AND created_at > now() - INTERVAL '10 seconds'
    ) THEN
      RAISE EXCEPTION 'Sačekajte nekoliko sekundi pre objave sledećeg oglasa.';
    END IF;

    -- B) Dnevni limit: maksimalno 20 oglasa u 24 časa po korisniku
    IF (
      SELECT count(*)
      FROM public.classified_ads
      WHERE user_id = NEW.user_id
        AND created_at > now() - INTERVAL '24 hours'
    ) >= 20 THEN
      RAISE EXCEPTION 'Dostigli ste dnevni limit za postavljanje oglasa (maksimalno 20 oglasa za 24h).';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_classified_ad_validate ON public.classified_ads;
CREATE TRIGGER trg_classified_ad_validate
  BEFORE INSERT OR UPDATE ON public.classified_ads
  FOR EACH ROW EXECUTE FUNCTION public.classified_ad_validate();

-- 5) RLS: Dozvoli i administratorima izmenu i brisanje oglasa radi moderacije
DROP POLICY IF EXISTS "classified_ads_update_owner" ON public.classified_ads;
CREATE POLICY "classified_ads_update_owner"
    ON public.classified_ads FOR UPDATE
    USING (auth.uid() = user_id OR public.is_admin())
    WITH CHECK (auth.uid() = user_id OR public.is_admin());

DROP POLICY IF EXISTS "classified_ads_delete_owner" ON public.classified_ads;
CREATE POLICY "classified_ads_delete_owner"
    ON public.classified_ads FOR DELETE
    USING (auth.uid() = user_id OR public.is_admin());

-- 6) RPC za administraciju/moderaciju oglasa
CREATE OR REPLACE FUNCTION public.admin_moderate_classified_ad(
    p_ad_id UUID,
    p_new_status TEXT
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Pristup odbijen: samo administrator može moderisati oglase.';
  END IF;

  IF p_new_status NOT IN ('active', 'archived', 'rejected') THEN
    RAISE EXCEPTION 'Nevažeći status moderacije: %', p_new_status;
  END IF;

  UPDATE public.classified_ads
  SET status = p_new_status,
      updated_at = now()
  WHERE id = p_ad_id;
END;
$$;

REVOKE ALL ON FUNCTION public.admin_moderate_classified_ad FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_moderate_classified_ad TO authenticated, service_role;

-- >>> END MIGRATION: 20260904170000_classified_ads_moderation_and_limits.sql <<<

