-- >>> BEGIN MIGRATION: 20260909160000_classified_category_condition_flag.sql <<<
-- ============================================================================
-- Migracija 20260909160000: Dodavanje kolone is_condition_applicable na classified_categories
-- Rešava arhitektonski problem C2 (dupliranje pravila o stanju predmeta u klijentu i bazi).
-- ============================================================================

-- 1. Dodavanje kolone is_condition_applicable sa podrazumevanom vrednošću true
ALTER TABLE public.classified_categories 
ADD COLUMN IF NOT EXISTS is_condition_applicable BOOLEAN NOT NULL DEFAULT true;

-- 2. Označavanje kategorija za koje stanje nema smisla (životinje, biljke, hrana, usluge, nekretnine)
UPDATE public.classified_categories 
SET is_condition_applicable = false
WHERE id IN (
    -- Glavni stubovi
    'ljubimci', 'usluge', 'nekretnine',
    
    -- Životinje i podkategorije
    'psi', 'lovacki_psi', 'cuvari_ovcari', 'mali_kucni_psi', 'terijeri_gonici', 'udomljavanje_pasa',
    'macke', 'rasne_macke', 'domace_macke', 'domace_zivotinje', 'stocarstvo_zivotinje', 'krave_telad',
    'ovce_jagnjad', 'koze_jarici', 'svinje_prasad', 'konji_magarci', 'zivina_ptice', 'kokoske_pilici',
    'curke', 'patke_guske', 'papagaji_ptice', 'golubovi', 'pcelarstvo', 'pcelinja_drustva_matice',
    'hrana_psi_macke', 'koncentrati_premiksi',
    
    -- Voće, povrće, sadnice, rasad, semena, stočna hrana
    'sadnice_semena', 'sadnice_voca', 'sadnice_vinove_loze', 'semenska_roba', 'semenski_krompir_luk',
    'rasad_povrca', 'stocna_hrana', 'balirano_seno_lucerka', 'balirana_slama', 'kukuruz_stocni',
    'zitarice_stocne', 'silaza_senaza', 'mekinje_sacme',
    
    -- Usluge
    'poljoprivredne_usluge', 'majstori_zanatlije', 'gradjevinske_usluge', 'prevoz_selidbe',
    'servis_mehanike', 'poslovi_zaposlenje',
    
    -- Nekretnine
    'stanovi', 'kuce_domacinstva', 'vikendice',
    'poljoprivredno_zemljiste', 'gradjevinski_placevi', 'poslovni_prostori', 'garaze_parking'
) OR (
    -- Sve podkategorije pod uslugama i nekretninama
    parent_id IN ('usluge', 'nekretnine')
);

-- Izuzetak: oprema za životinje, košnice i delovi mehanizacije imaju stanje
UPDATE public.classified_categories
SET is_condition_applicable = true
WHERE id IN ('oprema_za_zivotinje', 'delovi_za_traktore', 'prerada_voca_oprema');

-- 3. Pojednostavljeni trigger koji čita is_condition_applicable direktno iz kategorije
CREATE OR REPLACE FUNCTION public.enforce_classified_ad_condition()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_applicable BOOLEAN;
BEGIN
    SELECT is_condition_applicable
    INTO v_applicable
    FROM public.classified_categories
    WHERE id = NEW.category_id;

    IF v_applicable = false THEN
        NEW.condition := 'not_applicable';
    END IF;

    RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20260909160000_classified_category_condition_flag.sql <<<

-- >>> BEGIN MIGRATION: 20260909170000_preserve_created_at_on_update.sql <<<
-- ============================================================================
-- Migracija 20260909170000: Sprečavanje resetovanja created_at pri UPDATE-u
-- Garantuje na nivou baze da se created_at nikada ne menja na proizvodima i oglasima,
-- a automatski osvežava updated_at na oglasima.
-- ============================================================================

-- 1. Trigger za classified_ads: zadržava originalni created_at i osvežava updated_at
CREATE OR REPLACE FUNCTION public.preserve_classified_ad_created_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    NEW.created_at := OLD.created_at;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_preserve_classified_ad_created_at ON public.classified_ads;
CREATE TRIGGER trg_preserve_classified_ad_created_at
BEFORE UPDATE ON public.classified_ads
FOR EACH ROW
EXECUTE FUNCTION public.preserve_classified_ad_created_at();

-- 2. Trigger za products: zadržava originalni created_at
CREATE OR REPLACE FUNCTION public.preserve_product_created_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    NEW.created_at := OLD.created_at;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_preserve_product_created_at ON public.products;
CREATE TRIGGER trg_preserve_product_created_at
BEFORE UPDATE ON public.products
FOR EACH ROW
EXECUTE FUNCTION public.preserve_product_created_at();

-- >>> END MIGRATION: 20260909170000_preserve_created_at_on_update.sql <<<

-- >>> BEGIN MIGRATION: 20260909180000_classified_ads_phone_privacy.sql <<<
-- ============================================================================
-- Migracija 20260909180000: Privatnost telefona na malim oglasima (phone_public)
--
-- 1. Oduzimanje SELECT prava nad kolonom phone tabele classified_ads za
--    anon i authenticated uloge (sprečava curenje preko GET /rest/v1/classified_ads?select=phone).
-- 2. SECURITY DEFINER funkcija get_classified_ad_phone za bezbedno čitanje telefona
--    samo kada je phone_public = true (ili je pregledač vlasnik/admin).
-- 3. Privacy VIEW public_classified_ads (analogno public_profiles) sa
--    automatskim maskiranjem telefona na nivou reda i kolone.
-- ============================================================================

-- 1. Oduzmi direktno SELECT pravo nad kolonom phone sa osnovne tabele
REVOKE SELECT (phone) ON public.classified_ads FROM anon, authenticated;

-- Osiguraj da ulogovani korisnici mogu upisati svoj telefon pri unosu i izmeni
GRANT INSERT (phone), UPDATE (phone) ON public.classified_ads TO authenticated;

-- 2. RPC funkcija za kontrolisano čitanje broja telefona
CREATE OR REPLACE FUNCTION public.get_classified_ad_phone(p_ad_id UUID)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_phone TEXT;
  v_phone_public BOOLEAN;
  v_user_id UUID;
  v_status TEXT;
BEGIN
  SELECT phone, phone_public, user_id, status
  INTO v_phone, v_phone_public, v_user_id, v_status
  FROM public.classified_ads
  WHERE id = p_ad_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Vlasnik oglasa i admin uvek vide telefon (čak i ako je oglas prodat ili arhiviran)
  IF auth.uid() = v_user_id OR public.is_admin() THEN
    RETURN v_phone;
  END IF;

  -- Posetioci vide telefon samo ako je oglas aktivan i vlasnik je dozvolio javni prikaz
  IF v_status = 'active' AND v_phone_public THEN
    RETURN v_phone;
  END IF;

  RETURN NULL;
END;
$$;

-- Dozvoli pozivanje funkcije anonimnim i prijavljenim korisnicima
REVOKE ALL ON FUNCTION public.get_classified_ad_phone(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_classified_ad_phone(UUID) TO anon, authenticated;

-- 3. Privacy VIEW sa maskiranom kolonom telefona (analogno public_profiles)
CREATE OR REPLACE VIEW public.public_classified_ads AS
SELECT
  ca.id,
  ca.user_id,
  ca.title,
  ca.description,
  ca.price,
  ca.currency,
  ca.price_type,
  ca.category_id,
  ca.condition,
  ca.images,
  ca.city,
  CASE 
    WHEN (
      (ca.status = 'active' AND ca.phone_public) 
      OR auth.uid() = ca.user_id 
      OR public.is_admin()
    ) 
    THEN ca.phone 
    ELSE NULL 
  END AS phone,
  ca.phone_public,
  ca.status,
  ca.views_count,
  ca.created_at,
  ca.updated_at
FROM public.classified_ads ca
WHERE ca.status = 'active' OR auth.uid() = ca.user_id OR public.is_admin();

GRANT SELECT ON public.public_classified_ads TO anon, authenticated;

-- >>> END MIGRATION: 20260909180000_classified_ads_phone_privacy.sql <<<

-- >>> BEGIN MIGRATION: 20260909190000_profiles_privacy_and_anon_access.sql <<<
-- ============================================================================
-- Migracija 20260909190000: Privatnost tabele profiles i javni pristup za posetioce
--
-- 1. Ažuriranje RLS na public.profiles:
--    Dozvoljava čitanje javnih kolona i neulogovanim korisnicima (anon),
--    čime se rešava problem `profiles: null` (ime/avatar prodavca) u oglasima.
-- 2. Kolonska zaštita (REVOKE SELECT):
--    Oduzimanje SELECT prava nad kolonama email i phone na public.profiles
--    za uloge anon i authenticated.
-- 3. Rekonstrukcija public_profiles view-a sa definer pravima (security_invoker = off)
--    kako bi kroz CASE bezbedno servirao email i phone isključivo vlasniku/adminu.
-- 4. SECURITY DEFINER funkcija check_phone_exists za bezbednu proveru postojanja
--    broja bez izlaganja profila.
-- ============================================================================

-- 1. RLS na public.profiles: dozvoli čitanje svim posetiocima (anon i authenticated)
DROP POLICY IF EXISTS "Profiles are viewable by authenticated users" ON public.profiles;
DROP POLICY IF EXISTS "Profiles are viewable by all users" ON public.profiles;
CREATE POLICY "Profiles are viewable by all users"
  ON public.profiles FOR SELECT
  USING (true);

-- 2. Kolonska zaštita osetljivih podataka na osnovnoj tabeli profiles
REVOKE SELECT (email, phone) ON public.profiles FROM anon, authenticated;

-- Osiguraj da ulogovani korisnici mogu unositi i ažurirati svoj email i telefon
GRANT INSERT (email, phone), UPDATE (email, phone) ON public.profiles TO authenticated;

-- 3. Rekonstrukcija public_profiles view-a
-- View se izvršava sa pravima vlasnika (postgres) kako bi mogao pristupiti kolonama email i phone
-- i bezbedno primeniti logiku maskiranja (CASE WHEN).
CREATE OR REPLACE VIEW public.public_profiles AS
SELECT
  p.id,
  CASE WHEN (auth.uid() = p.id OR EXISTS (
        SELECT 1 FROM public.profiles v WHERE v.id = auth.uid() AND v.is_admin
      )) THEN p.email ELSE NULL END AS email,
  CASE WHEN (p.phone_public OR auth.uid() = p.id OR EXISTS (
        SELECT 1 FROM public.profiles v WHERE v.id = auth.uid() AND v.is_admin
      )) THEN p.phone ELSE NULL END AS phone,
  p.display_name,
  p.city,
  p.postal_code,
  p.role,
  p.is_guest,
  p.farm_name,
  p.location,
  p.profile_image_url,
  p.phone_public,
  p.is_verified,
  p.seller_story,
  p.farm_gallery_urls,
  p.seller_tags,
  p.seller_quick_replies,
  p.is_admin,
  p.lat,
  p.lng,
  p.created_at
FROM public.profiles p;

GRANT SELECT ON public.public_profiles TO anon, authenticated;

-- 4. RPC funkcija za proveru postojanja broja telefona pri registraciji
CREATE OR REPLACE FUNCTION public.check_phone_exists(p_phone TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_phone IS NULL OR trim(p_phone) = '' THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE phone = trim(p_phone)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.check_phone_exists(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_phone_exists(TEXT) TO anon, authenticated;

-- >>> END MIGRATION: 20260909190000_profiles_privacy_and_anon_access.sql <<<

-- >>> BEGIN MIGRATION: 20260909200000_classified_ads_and_push_fixes.sql <<<
-- ============================================================================
-- Migracija 20260909200000: Ispravke za preglede oglasa, moderaciju i push tajne
--
-- 1. increment_classified_ad_views:
--    - Omogućava anonimnim posetiocima (anon) beleženje pregleda
--    - Sprečava vlasnika oglasa da uvećava sopstveni brojač
--    - Uklanja globalni 60s blok koji je gušio legitimne istovremene posete
-- 2. admin_moderate_classified_ad:
--    - Proširenje dozvoljenih statusa na svih 5 iz CHECK constraint-a:
--      ('active', 'sold', 'archived', 'rejected', 'flagged')
-- 3. invoke_send_push:
--    - Podrška za Supabase Vault (vault.decrypted_secrets) uz fallback na edge_config
--      radi bezbedne rotacije anon/service ključeva van migracija
-- ============================================================================

-- 1) Poboljšana funkcija za brojanje pregleda oglasa
CREATE OR REPLACE FUNCTION public.increment_classified_ad_views(ad_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user  UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
BEGIN
  -- Pronađi vlasnika i status oglasa
  SELECT user_id, status
    INTO v_owner, v_status
  FROM public.classified_ads
  WHERE id = ad_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Samo aktivni oglasi dobijaju preglede
  IF v_status <> 'active' THEN
    RETURN;
  END IF;

  -- Vlasnik oglasa ne povećava sopstveni brojač pregleda
  IF v_user IS NOT NULL AND v_user = v_owner THEN
    RETURN;
  END IF;

  -- Inkrementiraj brojač i zabeleži vreme poslednjeg pregleda
  UPDATE public.classified_ads
  SET views_count = views_count + 1,
      last_view_at = now()
  WHERE id = ad_id;
END;
$$;

REVOKE ALL ON FUNCTION public.increment_classified_ad_views(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.increment_classified_ad_views(UUID) TO anon, authenticated, service_role;


-- 2) Proširena admin moderacija oglasa sa podrškom za 'sold' i 'flagged'
CREATE OR REPLACE FUNCTION public.admin_moderate_classified_ad(
    p_ad_id UUID,
    p_new_status TEXT
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Pristup odbijen: samo administrator može moderisati oglase.';
  END IF;

  IF p_new_status NOT IN ('active', 'sold', 'archived', 'rejected', 'flagged') THEN
    RAISE EXCEPTION 'Nevažeći status moderacije: %', p_new_status;
  END IF;

  UPDATE public.classified_ads
  SET status = p_new_status,
      updated_at = now()
  WHERE id = p_ad_id;
END;
$$;

REVOKE ALL ON FUNCTION public.admin_moderate_classified_ad(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_moderate_classified_ad(UUID, TEXT) TO authenticated, service_role;


-- 3) invoke_send_push sa dinamičkim čitanjem tajni iz Supabase Vault-a
CREATE OR REPLACE FUNCTION public.invoke_send_push()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  base_url TEXT;
  anon_key TEXT;
  fn_url TEXT;
BEGIN
  -- Pokušaj čitanja iz Supabase Vault-a (omogućava rotaciju bez novih SQL migracija)
  BEGIN
    SELECT decrypted_secret INTO anon_key 
    FROM vault.decrypted_secrets 
    WHERE name = 'anon_key' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    anon_key := NULL;
  END;

  BEGIN
    SELECT decrypted_secret INTO base_url 
    FROM vault.decrypted_secrets 
    WHERE name = 'functions_base_url' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    base_url := NULL;
  END;

  -- Fallback na public.edge_config tabelu ako Vault nije konfigurisan
  IF base_url IS NULL OR base_url = '' THEN
    SELECT value INTO base_url FROM public.edge_config WHERE key = 'functions_base_url' LIMIT 1;
  END IF;

  IF anon_key IS NULL OR anon_key = '' THEN
    SELECT value INTO anon_key FROM public.edge_config WHERE key = 'anon_key' LIMIT 1;
  END IF;

  IF base_url IS NULL OR base_url = '' THEN
    RETURN NEW;
  END IF;

  fn_url := base_url || '/functions/v1/send-push';

  PERFORM net.http_post(
    url := fn_url,
    body := jsonb_build_object(
      'user_id', NEW.user_id,
      'title', COALESCE(NEW.title, ''),
      'body', COALESCE(NEW.body, ''),
      'type', COALESCE(NEW.type::text, ''),
      'order_id', CASE WHEN NEW.order_id IS NOT NULL THEN NEW.order_id::text ELSE '' END,
      'ticket_id', CASE WHEN NEW.ticket_id IS NOT NULL THEN NEW.ticket_id::text ELSE '' END,
      'conversation_id', CASE WHEN NEW.conversation_id IS NOT NULL THEN NEW.conversation_id::text ELSE '' END
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || COALESCE(anon_key, ''),
      'apikey', COALESCE(anon_key, '')
    ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'invoke_send_push: %', SQLERRM;
    RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20260909200000_classified_ads_and_push_fixes.sql <<<

-- >>> BEGIN MIGRATION: 20260910150000_security_hardening_notifications_push_views.sql <<<
-- ============================================================================
-- Migracija 20260910150000: Sigurnosno učvršćivanje (Security Hardening)
--
-- S1: Restrikcija INSERT prava na notifications tabeli isključivo na service_role.
--     Korisnici ne mogu direktno unositi notifikacije niti okidati push.
--     Sistemski trigeri (notify_*) su SECURITY DEFINER i nastavljaju nesmetano da rade.
--
-- S2: Zaštita edge_config tabele preko RLS-a.
--     invoke_send_push sada preuzima service_role_key iz Vault-a ili edge_config-a
--     i šalje autorizovani zahtev ka send-push Edge funkciji.
--     Ažurirana push_health_summary dijagnostika.
--
-- S4: Zaštita i deduplikacija brojača pregleda oglasa (classified_ad_views).
--     Sprečava botove i zlonamerno pumpanje brojača pomoću 1-satnog per-viewer
--     prozora baziranog na user_id, installation_id ili IP hešu.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. S1: Uklanjanje opasne INSERT politike za authenticated korisnike
-- ----------------------------------------------------------------------------

DROP POLICY IF EXISTS "System can create notifications" ON public.notifications;
DROP POLICY IF EXISTS "Service role can create notifications" ON public.notifications;

-- Samo service_role (ili funkcije sa SECURITY DEFINER pravima) može direktno da ubacuje
CREATE POLICY "Service role can create notifications"
  ON public.notifications FOR INSERT
  TO service_role
  WITH CHECK (true);

-- Potvrđujemo da postojeća SELECT politika omogućava korisniku uvid samo u sopstvene notifikacije
DROP POLICY IF EXISTS "Users see own notifications" ON public.notifications;
CREATE POLICY "Users see own notifications"
  ON public.notifications FOR SELECT
  TO authenticated
  USING ((SELECT auth.uid()) = user_id);

-- ----------------------------------------------------------------------------
-- 2. S2: Zaštita edge_config tabele i prelazak na service_role_key
-- ----------------------------------------------------------------------------

-- Omogući RLS na tabeli sa osetljivim konfiguracijama (ako nije bio omogućen)
ALTER TABLE public.edge_config ENABLE ROW LEVEL SECURITY;

-- Oduzmi sva prava sa javnih i korisničkih uloga
REVOKE ALL ON public.edge_config FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.edge_config TO service_role;

-- Unos placeholder ključa za lokalni dev (ako već ne postoji)
INSERT INTO public.edge_config (key, value)
VALUES 
  ('service_role_key', '')
ON CONFLICT (key) DO NOTHING;

-- Ažurirana invoke_send_push funkcija koja koristi service_role_key
CREATE OR REPLACE FUNCTION public.invoke_send_push()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  base_url TEXT;
  service_key TEXT;
  fn_url TEXT;
BEGIN
  -- 1. Pokušaj čitanja 'service_role_key' iz Supabase Vault-a
  BEGIN
    SELECT decrypted_secret INTO service_key 
    FROM vault.decrypted_secrets 
    WHERE name = 'service_role_key' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    service_key := NULL;
  END;

  -- 2. Pokušaj čitanja 'functions_base_url' iz Supabase Vault-a
  BEGIN
    SELECT decrypted_secret INTO base_url 
    FROM vault.decrypted_secrets 
    WHERE name = 'functions_base_url' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    base_url := NULL;
  END;

  -- Fallback na public.edge_config tabelu ako Vault nije konfigurisan
  IF base_url IS NULL OR base_url = '' THEN
    SELECT value INTO base_url FROM public.edge_config WHERE key = 'functions_base_url' LIMIT 1;
  END IF;

  IF service_key IS NULL OR service_key = '' THEN
    SELECT value INTO service_key FROM public.edge_config WHERE key = 'service_role_key' LIMIT 1;
  END IF;

  -- Ako ni Vault ni edge_config nemaju service_role_key, ne možemo autorizovati Edge funkciju
  IF service_key IS NULL OR service_key = '' THEN
    RAISE WARNING 'invoke_send_push: service_role_key nije pronađen u Vault-u ni u edge_config-u. Push obaveštenje nije poslato.';
    RETURN NEW;
  END IF;

  IF base_url IS NULL OR base_url = '' THEN
    RETURN NEW;
  END IF;

  fn_url := base_url || '/functions/v1/send-push';

  PERFORM net.http_post(
    url := fn_url,
    body := jsonb_build_object(
      'user_id', NEW.user_id,
      'title', COALESCE(NEW.title, ''),
      'body', COALESCE(NEW.body, ''),
      'type', COALESCE(NEW.type::text, ''),
      'order_id', CASE WHEN NEW.order_id IS NOT NULL THEN NEW.order_id::text ELSE '' END,
      'ticket_id', CASE WHEN NEW.ticket_id IS NOT NULL THEN NEW.ticket_id::text ELSE '' END,
      'conversation_id', CASE WHEN NEW.conversation_id IS NOT NULL THEN NEW.conversation_id::text ELSE '' END
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_key,
      'apikey', service_key
    ),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'invoke_send_push: %', SQLERRM;
    RETURN NEW;
END;
$$;

-- Ažuriraj push_health_summary dijagnostiku da prepoznaje i service_role_key
CREATE OR REPLACE FUNCTION public.push_health_summary()
RETURNS TABLE (
  checked_at TIMESTAMPTZ,
  edge_config_ok BOOLEAN,
  functions_base_url TEXT,
  anon_key_present BOOLEAN,
  total_tokens BIGINT,
  users_with_tokens BIGINT,
  tokens_created_24h BIGINT,
  notifications_24h BIGINT,
  deliveries_24h BIGINT,
  successful_deliveries_24h BIGINT,
  failed_deliveries_24h BIGINT,
  success_rate_pct NUMERIC,
  last_notification_at TIMESTAMPTZ,
  last_delivery_at TIMESTAMPTZ,
  delivery_backlog_minutes NUMERIC,
  health TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_base_url TEXT;
  v_service_key TEXT;
  v_anon_key TEXT;
BEGIN
  -- Pokušaj čitanja iz Vault-a
  BEGIN
    SELECT decrypted_secret INTO v_base_url FROM vault.decrypted_secrets WHERE name = 'functions_base_url' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_base_url := NULL;
  END;

  BEGIN
    SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_service_key := NULL;
  END;

  BEGIN
    SELECT decrypted_secret INTO v_anon_key FROM vault.decrypted_secrets WHERE name = 'anon_key' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_anon_key := NULL;
  END;

  -- Fallback na public.edge_config
  IF v_base_url IS NULL OR v_base_url = '' THEN
    SELECT value INTO v_base_url FROM public.edge_config WHERE key = 'functions_base_url' LIMIT 1;
  END IF;

  IF v_service_key IS NULL OR v_service_key = '' THEN
    SELECT value INTO v_service_key FROM public.edge_config WHERE key = 'service_role_key' LIMIT 1;
  END IF;

  IF v_anon_key IS NULL OR v_anon_key = '' THEN
    SELECT value INTO v_anon_key FROM public.edge_config WHERE key = 'anon_key' LIMIT 1;
  END IF;

  RETURN QUERY
  WITH token_stats AS (
    SELECT
      COUNT(*) AS total_tokens,
      COUNT(DISTINCT user_id) AS users_with_tokens,
      COUNT(*) FILTER (WHERE user_push_tokens.created_at > NOW() - INTERVAL '24 hours') AS tokens_created_24h
    FROM public.user_push_tokens
  ),
  notification_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE notifications.created_at > NOW() - INTERVAL '24 hours') AS notifications_24h,
      MAX(notifications.created_at) AS last_notification_at
    FROM public.notifications
  ),
  delivery_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE push_delivery_logs.created_at > NOW() - INTERVAL '24 hours') AS deliveries_24h,
      COUNT(*) FILTER (
        WHERE push_delivery_logs.created_at > NOW() - INTERVAL '24 hours'
          AND status = 'success'
      ) AS successful_deliveries_24h,
      COUNT(*) FILTER (
        WHERE push_delivery_logs.created_at > NOW() - INTERVAL '24 hours'
          AND status IN ('error', 'partial', 'no_tokens', 'invalid_request')
      ) AS failed_deliveries_24h,
      MAX(push_delivery_logs.created_at) AS last_delivery_at
    FROM public.push_delivery_logs
  ),
  summary AS (
    SELECT
      NOW() AS checked_at,
      (v_base_url IS NOT NULL AND v_base_url <> ''
        AND ((v_service_key IS NOT NULL AND v_service_key <> '') OR (v_anon_key IS NOT NULL AND v_anon_key <> ''))) AS edge_config_ok,
      v_base_url AS functions_base_url,
      ((v_service_key IS NOT NULL AND v_service_key <> '') OR (v_anon_key IS NOT NULL AND v_anon_key <> '')) AS anon_key_present,
      token_stats.total_tokens,
      token_stats.users_with_tokens,
      token_stats.tokens_created_24h,
      notification_stats.notifications_24h,
      delivery_stats.deliveries_24h,
      delivery_stats.successful_deliveries_24h,
      delivery_stats.failed_deliveries_24h,
      ROUND(
        CASE
          WHEN delivery_stats.deliveries_24h = 0 THEN 0
          ELSE (delivery_stats.successful_deliveries_24h::NUMERIC / delivery_stats.deliveries_24h::NUMERIC) * 100
        END,
        2
      ) AS success_rate_pct,
      notification_stats.last_notification_at,
      delivery_stats.last_delivery_at,
      ROUND(
        CASE
          WHEN notification_stats.last_notification_at IS NULL THEN 0
          WHEN delivery_stats.last_delivery_at IS NULL THEN EXTRACT(EPOCH FROM (NOW() - notification_stats.last_notification_at)) / 60.0
          WHEN delivery_stats.last_delivery_at < notification_stats.last_notification_at THEN EXTRACT(EPOCH FROM (notification_stats.last_notification_at - delivery_stats.last_delivery_at)) / 60.0
          ELSE 0
        END,
        2
      ) AS delivery_backlog_minutes
    FROM token_stats, notification_stats, delivery_stats
  )
  SELECT
    summary.checked_at,
    summary.edge_config_ok,
    summary.functions_base_url,
    summary.anon_key_present,
    summary.total_tokens,
    summary.users_with_tokens,
    summary.tokens_created_24h,
    summary.notifications_24h,
    summary.deliveries_24h,
    summary.successful_deliveries_24h,
    summary.failed_deliveries_24h,
    summary.success_rate_pct,
    summary.last_notification_at,
    summary.last_delivery_at,
    summary.delivery_backlog_minutes,
    CASE
      WHEN NOT summary.edge_config_ok THEN 'misconfigured'
      WHEN summary.last_notification_at IS NOT NULL
        AND (summary.last_delivery_at IS NULL OR summary.last_delivery_at < summary.last_notification_at - INTERVAL '5 minutes') THEN 'stalled'
      WHEN summary.deliveries_24h > 0 AND summary.success_rate_pct < 80 THEN 'degraded'
      ELSE 'ok'
    END AS health
  FROM summary;
END;
$function$;


-- ----------------------------------------------------------------------------
-- 3. S4: Tabela pregleda i deduplikacija (rate limiting) za classified ads
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.classified_ad_views (
  ad_id UUID NOT NULL REFERENCES public.classified_ads(id) ON DELETE CASCADE,
  viewer_hash TEXT NOT NULL,
  last_viewed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (ad_id, viewer_hash)
);

ALTER TABLE public.classified_ad_views ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.classified_ad_views FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.classified_ad_views TO service_role;

CREATE INDEX IF NOT EXISTS idx_classified_ad_views_last_viewed
  ON public.classified_ad_views (last_viewed_at);

-- OBAVEZNO obriši postojeću verziju sa 1 argumentom pre kreiranja overload-a
-- kako PostgREST ne bi prijavljivao grešku nejasnog izbora kandidata (overload ambiguity)
DROP FUNCTION IF EXISTS public.increment_classified_ad_views(UUID);

CREATE OR REPLACE FUNCTION public.increment_classified_ad_views(
  ad_id UUID,
  p_viewer_id TEXT DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_headers JSONB;
  v_ip TEXT;
  v_viewer_hash TEXT;
BEGIN
  -- 1. Pronađi vlasnika i status oglasa
  SELECT user_id, status
    INTO v_owner, v_status
  FROM public.classified_ads
  WHERE id = ad_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 2. Samo aktivni oglasi dobijaju preglede
  IF v_status <> 'active' THEN
    RETURN;
  END IF;

  -- 3. Vlasnik oglasa ne povećava sopstveni brojač pregleda
  IF v_user IS NOT NULL AND v_user = v_owner THEN
    RETURN;
  END IF;

  -- 4. Odredi identifikator posetioca (viewer_hash)
  IF v_user IS NOT NULL THEN
    v_viewer_hash := 'usr:' || v_user::text;
  ELSIF p_viewer_id IS NOT NULL AND length(trim(p_viewer_id)) > 0 THEN
    v_viewer_hash := 'dev:' || md5(trim(p_viewer_id));
  ELSE
    BEGIN
      v_headers := current_setting('request.headers', true)::jsonb;
      v_ip := COALESCE(
        v_headers->>'cf-connecting-ip',
        v_headers->>'x-real-ip',
        split_part(v_headers->>'x-forwarded-for', ',', 1),
        'unknown'
      );
    EXCEPTION WHEN OTHERS THEN
      v_ip := 'unknown';
    END;
    v_viewer_hash := 'ip:' || md5(v_ip);
  END IF;

  -- 5. Deduplikacija: Ako je posetilac već pogledao oglas u proteklih 1 sat, ignoriši
  IF EXISTS (
    SELECT 1 FROM public.classified_ad_views
    WHERE classified_ad_views.ad_id = increment_classified_ad_views.ad_id
      AND classified_ad_views.viewer_hash = v_viewer_hash
      AND classified_ad_views.last_viewed_at > now() - INTERVAL '1 hour'
  ) THEN
    RETURN;
  END IF;

  -- 6. Zabeleži / osveži vreme pregleda u tabeli deduplikacije
  INSERT INTO public.classified_ad_views (ad_id, viewer_hash, last_viewed_at)
  VALUES (increment_classified_ad_views.ad_id, v_viewer_hash, now())
  ON CONFLICT (ad_id, viewer_hash)
  DO UPDATE SET last_viewed_at = now();

  -- 7. Inkrementiraj stvarni brojač pregleda na oglasu
  UPDATE public.classified_ads
  SET views_count = views_count + 1,
      last_view_at = now()
  WHERE id = increment_classified_ad_views.ad_id;
END;
$$;

REVOKE ALL ON FUNCTION public.increment_classified_ad_views(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.increment_classified_ad_views(UUID, TEXT) TO anon, authenticated, service_role;

