-- >>> BEGIN MIGRATION: 20260910160000_auth_rate_limiting_and_anti_enumeration.sql <<<
-- ============================================================================
-- Migracija: Zaštita Auth Sistema od Enumeracije Naloga i Rate Limiting
-- Datum: 2026-09-10
-- Opis:
--   1. Tabela auth_rate_limits za praćenje broja zahteva po IP adresi.
--   2. check_and_record_auth_rate_limit pomoćna funkcija.
--   3. Očvršćavanje funkcija check_email_exists i check_phone_exists
--      sa format-validacijom i limitom od maksimalno 10 zahteva u 5 minuta.
-- ============================================================================

-- 1. Tabela za praćenje auth rate limita
CREATE TABLE IF NOT EXISTS public.auth_rate_limits (
  id BIGSERIAL PRIMARY KEY,
  identifier TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  request_count INT NOT NULL DEFAULT 1,
  window_start TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX IF NOT EXISTS idx_auth_rate_limits_lookup
  ON public.auth_rate_limits (identifier, endpoint, window_start);

ALTER TABLE public.auth_rate_limits ENABLE ROW LEVEL SECURITY;

-- Dozvoli pristup samo service_role; anon i authenticated nemaju direktan pristup tabeli
DROP POLICY IF EXISTS "Service role manages auth rate limits" ON public.auth_rate_limits;
CREATE POLICY "Service role manages auth rate limits"
  ON public.auth_rate_limits
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- 2. Pomoćna funkcija za proveru i evidentiranje rate limita
CREATE OR REPLACE FUNCTION public.check_and_record_auth_rate_limit(
  p_endpoint TEXT,
  p_max_requests INT DEFAULT 10,
  p_window_seconds INT DEFAULT 300
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_headers JSONB;
  v_ip TEXT;
  v_now TIMESTAMPTZ := clock_timestamp();
  v_window_start TIMESTAMPTZ;
  v_count INT;
BEGIN
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_headers := '{}'::jsonb;
  END;

  -- Izdvajanje klijentske IP adrese iz standardnih proksija (Cloudflare, Supabase pooler)
  v_ip := coalesce(
    nullif(trim(v_headers->>'cf-connecting-ip'), ''),
    nullif(trim(split_part(v_headers->>'x-forwarded-for', ',', 1)), ''),
    nullif(trim(v_headers->>'x-real-ip'), ''),
    'unknown_client'
  );

  -- Periodično čišćenje starih unosa (5% šanse po pozivu da se obrišu unosi stariji od 1 sata)
  IF (random() < 0.05) THEN
    DELETE FROM public.auth_rate_limits
    WHERE window_start < v_now - INTERVAL '1 hour';
  END IF;

  -- Provera postojećeg aktivnog prozora
  SELECT window_start, request_count
  INTO v_window_start, v_count
  FROM public.auth_rate_limits
  WHERE identifier = v_ip
    AND endpoint = p_endpoint
    AND window_start > v_now - (p_window_seconds || ' seconds')::interval
  ORDER BY window_start DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    IF v_count >= p_max_requests THEN
      RETURN false; -- Prekoračen limit
    END IF;

    UPDATE public.auth_rate_limits
    SET request_count = request_count + 1
    WHERE identifier = v_ip
      AND endpoint = p_endpoint
      AND window_start = v_window_start;
  ELSE
    INSERT INTO public.auth_rate_limits (identifier, endpoint, request_count, window_start)
    VALUES (v_ip, p_endpoint, 1, v_now);
  END IF;

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.check_and_record_auth_rate_limit(TEXT, INT, INT) FROM PUBLIC;

-- 3. Očvršćena funkcija check_email_exists
CREATE OR REPLACE FUNCTION public.check_email_exists(p_email TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_trimmed TEXT;
  v_allowed BOOLEAN;
BEGIN
  IF p_email IS NULL THEN
    RETURN false;
  END IF;

  v_trimmed := lower(trim(p_email));

  -- Osnovna provera formata emaila bez upita u bazu ako je format nevalidan
  IF length(v_trimmed) < 5 OR v_trimmed NOT LIKE '%@%.%' THEN
    RETURN false;
  END IF;

  -- Provera rate limita: maks 10 provera u 5 minuta (300s)
  v_allowed := public.check_and_record_auth_rate_limit('check_email_exists', 10, 300);
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Prekoračen dozvoljeni broj provera. Molimo sačekajte nekoliko minuta.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Provera postojanja u profilima (ili auth.users)
  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE lower(email) = v_trimmed
  );
END;
$$;

REVOKE ALL ON FUNCTION public.check_email_exists(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_email_exists(TEXT) TO anon, authenticated;

-- 4. Očvršćena funkcija check_phone_exists
CREATE OR REPLACE FUNCTION public.check_phone_exists(p_phone TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_trimmed TEXT;
  v_allowed BOOLEAN;
BEGIN
  IF p_phone IS NULL THEN
    RETURN false;
  END IF;

  v_trimmed := trim(p_phone);

  -- Broj telefona mora imati barem 6 karaktera
  IF length(v_trimmed) < 6 THEN
    RETURN false;
  END IF;

  -- Provera rate limita: maks 10 provera u 5 minuta (300s)
  v_allowed := public.check_and_record_auth_rate_limit('check_phone_exists', 10, 300);
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Prekoračen dozvoljeni broj provera. Molimo sačekajte nekoliko minuta.'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.profiles WHERE phone = v_trimmed
  );
END;
$$;

REVOKE ALL ON FUNCTION public.check_phone_exists(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_phone_exists(TEXT) TO anon, authenticated;

-- >>> END MIGRATION: 20260910160000_auth_rate_limiting_and_anti_enumeration.sql <<<

-- >>> BEGIN MIGRATION: 20260910170000_classified_ad_views_bot_detection.sql <<<
-- ============================================================================
-- Migration: 20260910170000_classified_ad_views_bot_detection.sql
-- Description:
--   1. Filter bot visits from classified ad view counter (User-Agent detection).
--   2. Extend deduplication window from 1h to 24h.
--   3. Combine IP + User-Agent in anonymous viewer hash for more accurate NAT tracking.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.increment_classified_ad_views(
  ad_id UUID,
  p_viewer_id TEXT DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_headers JSONB;
  v_ua TEXT;
  v_ip TEXT;
  v_viewer_hash TEXT;
BEGIN
  -- 1. Pronađi vlasnika i status oglasa
  SELECT user_id, status
    INTO v_owner, v_status
  FROM public.classified_ads
  WHERE id = ad_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 2. Samo aktivni oglasi dobijaju preglede
  IF v_status <> 'active' THEN
    RETURN;
  END IF;

  -- 3. Vlasnik oglasa ne povećava sopstveni brojač pregleda
  IF v_user IS NOT NULL AND v_user = v_owner THEN
    RETURN;
  END IF;

  -- 4. Detekcija User-Agent-a i blokada botova/crawlere/scrapers/social previewera
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_ua := lower(COALESCE(v_headers->>'user-agent', ''));
  EXCEPTION WHEN OTHERS THEN
    v_headers := '{}'::jsonb;
    v_ua := '';
  END;

  -- Filtriraj poznate botove, crawlera, scrapere i link preview servise
  IF v_ua ~* '(bot|crawl|spider|slurp|curl|wget|python|scrapy|aiohttp|httpx|headless|chrome-lighthouse|lighthouse|preview|scraper|facebookexternalhit|whatsapp|telegrambot|discordbot|slackbot|archive\.org|semrush|ahrefs|bingbot|googlebot|yandex|bytespider)' THEN
    RETURN;
  END IF;

  -- Provera viewer_id parametra na bot obrasce
  IF p_viewer_id IS NOT NULL AND p_viewer_id ~* '^(bot|spider|crawler)' THEN
    RETURN;
  END IF;

  -- 5. Odredi identifikator posetioca (viewer_hash)
  IF v_user IS NOT NULL THEN
    v_viewer_hash := 'usr:' || v_user::text;
  ELSIF p_viewer_id IS NOT NULL AND length(trim(p_viewer_id)) > 0 THEN
    v_viewer_hash := 'dev:' || md5(trim(p_viewer_id));
  ELSE
    v_ip := COALESCE(
      v_headers->>'cf-connecting-ip',
      v_headers->>'x-real-ip',
      split_part(v_headers->>'x-forwarded-for', ',', 1),
      'unknown'
    );
    -- Kombinujemo IP i User-Agent kako posetioci sa istog NAT/IP ali različitih uređaja ne bi delili limit
    v_viewer_hash := 'ip_ua:' || md5(v_ip || ':' || v_ua);
  END IF;

  -- 6. Deduplikacija: Ako je posetilac već pogledao oglas u proteklih 24 sata, ignoriši
  IF EXISTS (
    SELECT 1 FROM public.classified_ad_views
    WHERE classified_ad_views.ad_id = increment_classified_ad_views.ad_id
      AND classified_ad_views.viewer_hash = v_viewer_hash
      AND classified_ad_views.last_viewed_at > now() - INTERVAL '24 hours'
  ) THEN
    RETURN;
  END IF;

  -- 7. Zabeleži / osveži vreme pregleda u tabeli deduplikacije
  INSERT INTO public.classified_ad_views (ad_id, viewer_hash, last_viewed_at)
  VALUES (increment_classified_ad_views.ad_id, v_viewer_hash, now())
  ON CONFLICT (ad_id, viewer_hash)
  DO UPDATE SET last_viewed_at = now();

  -- 8. Inkrementiraj stvarni brojač pregleda na oglasu
  UPDATE public.classified_ads
  SET views_count = views_count + 1,
      last_view_at = now()
  WHERE id = increment_classified_ad_views.ad_id;
END;
$$;

REVOKE ALL ON FUNCTION public.increment_classified_ad_views(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.increment_classified_ad_views(UUID, TEXT) TO anon, authenticated, service_role;

-- >>> END MIGRATION: 20260910170000_classified_ad_views_bot_detection.sql <<<

-- >>> BEGIN MIGRATION: 20260910180000_strictly_disable_condition_for_non_applicable_categories.sql <<<
-- ============================================================================
-- Migracija 20260910180000: Stroga eliminacija stanja ("Novo" / "Polovno")
-- za nekretnine, usluge, žive životinje, useve, semena i hranu.
-- Rešava problem gde su podkategorije 3. nivoa (npr. prodaja_stanova, prodaja_kuca)
-- imale is_condition_applicable = true jer im je parent_id bio 2. nivo, a ne koren.
-- ============================================================================

-- 1. Rekurzivno ažuriranje svih potomaka (1, 2. i 3. nivo) krovnih grana
WITH RECURSIVE non_applicable_tree AS (
    -- Bazni korenski čvorovi i podgrane
    SELECT id, parent_id
    FROM public.classified_categories
    WHERE id IN (
        'nekretnine',
        'usluge',
        'psi',
        'macke',
        'domace_zivotinje',
        'zivina_ptice',
        'stocna_hrana',
        'sadnice_semena'
    )
    UNION ALL
    -- Rekurzivno svi potomci
    SELECT c.id, c.parent_id
    FROM public.classified_categories c
    INNER JOIN non_applicable_tree t ON c.parent_id = t.id
)
UPDATE public.classified_categories
SET is_condition_applicable = false
WHERE id IN (SELECT id FROM non_applicable_tree);

-- 2. Eksplicitno navođenje svih pojedinačnih podkategorija za potpunu robusnost
UPDATE public.classified_categories
SET is_condition_applicable = false
WHERE id IN (
    -- Krovne kategorije
    'nekretnine', 'usluge', 'ljubimci',

    -- Nekretnine - Nivo 2 i Nivo 3
    'stanovi', 'prodaja_stanova', 'izdavanje_stanova', 'stan_na_dan',
    'kuce_domacinstva', 'prodaja_kuca', 'seoska_domacinstva', 'izdavanje_kuca',
    'vikendice', 'planinske_vikendice', 'vikendice_reka_jezero', 'brvnare_eko_kuce',
    'poljoprivredno_zemljiste', 'njive_oranice', 'vocnjaci_vinogradi', 'sume_pasnjaci',
    'gradjevinski_placevi', 'placevi_za_kuce', 'industrijski_placevi',
    'poslovni_prostori', 'lokali', 'kancelarije', 'magacini_hale',
    'garaze_parking', 'prodaja_garaza', 'izdavanje_garaza',

    -- Usluge - Nivo 2 i Nivo 3
    'poljoprivredne_usluge', 'oranje_setva', 'zetva_kombajniranje', 'baliranje_usluge', 'orezivanje_prskanje_voca', 'seca_cepanje_drva',
    'majstori_zanatlije', 'vodoinstalaterske_usluge', 'elektricarske_usluge', 'molerski_gipsarski_radovi', 'keramicari_plocice', 'bravarske_usluge',
    'gradjevinske_usluge', 'iskopi_bageri', 'zidanje_betoniranje', 'krovopokrivacki_radovi', 'asfaltiranje_behaton', 'rusenje_odvoz_suta',
    'prevoz_selidbe', 'kombi_prevoz', 'kamionski_prevoz', 'slep_sluzba', 'selidbe_usluge',
    'servis_mehanike', 'servis_traktora', 'automehanicari', 'autolimari_farbari', 'vulkanizerske_usluge',
    'poslovi_zaposlenje', 'sezonski_poslovi', 'poslovi_gradjevina', 'poslovi_vozaci', 'poslovi_ugostiteljstvo',

    -- Žive životinje i pčele
    'psi', 'lovacki_psi', 'cuvari_ovcari', 'mali_kucni_psi', 'terijeri_gonici', 'udomljavanje_pasa',
    'macke', 'rasne_macke', 'domace_macke',
    'domace_zivotinje', 'stocarstvo_zivotinje', 'krave_telad', 'ovce_jagnjad', 'koze_jarici', 'svinje_prasad', 'konji_magarci',
    'zivina_ptice', 'kokoske_pilici', 'curke', 'patke_guske', 'papagaji_ptice', 'golubovi',
    'pcelinja_drustva_matice',

    -- Hrana za životinje, usevi, sadnice i semena
    'hrana_psi_macke', 'koncentrati_premiksi',
    'stocna_hrana', 'balirano_seno_lucerka', 'balirana_slama', 'kukuruz_stocni', 'zitarice_stocne', 'silaza_senaza', 'mekinje_sacme',
    'sadnice_semena', 'sadnice_voca', 'sadnice_vinove_loze', 'semenska_roba', 'semenski_krompir_luk', 'rasad_povrca'
);

-- 3. Zaštita i potvrda za fizičku opremu koja MOŽE imati stanje (Novo / Polovno)
UPDATE public.classified_categories
SET is_condition_applicable = true
WHERE id IN (
    'oprema_za_zivotinje', 'boksevi_kucice_kavezi', 'hranilice_pojilice_muzilice',
    'pcelarstvo', 'kosnice_ramovi', 'vrcajke_za_med', 'pcelarski_pribor',
    'delovi_za_traktore', 'delovi_motora_traktori', 'gume_za_traktore', 'hidraulika_traktori', 'kardani_kacenja', 'delovi_kombajni_balirke',
    'prerada_voca_oprema', 'kazani_za_rakiju', 'mlinovi_za_voce', 'prese_za_voce', 'burad_prohrom_drvo', 'flase_baloni_staklo',
    'navodnjavanje_plastenici', 'plastenici_folije', 'kap_po_kap_trake', 'pumpe_za_navodnjavanje', 'rezervoari_ibc'
);

-- 4. Rekurzivni trigger koji garantuje da stanje 'not_applicable' važi za celu hijerarhiju
CREATE OR REPLACE FUNCTION public.enforce_classified_ad_condition()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_applicable BOOLEAN;
    v_root_id TEXT;
BEGIN
    -- 1. Provera direktno iz kategorije
    SELECT is_condition_applicable
    INTO v_applicable
    FROM public.classified_categories
    WHERE id = NEW.category_id;

    -- 2. Ako nije eksplicitno podešeno (ili je true, ali predak spada u strogo neprikladne)
    IF v_applicable IS NULL OR v_applicable = true THEN
        WITH RECURSIVE cat_ancestors AS (
            SELECT id, parent_id
            FROM public.classified_categories
            WHERE id = NEW.category_id
            UNION ALL
            SELECT c.id, c.parent_id
            FROM public.classified_categories c
            INNER JOIN cat_ancestors a ON c.id = a.parent_id
        )
        SELECT id INTO v_root_id
        FROM cat_ancestors
        WHERE id IN ('nekretnine', 'usluge', 'psi', 'macke', 'domace_zivotinje', 'zivina_ptice', 'stocna_hrana', 'sadnice_semena')
        LIMIT 1;

        -- Ako je predak neka od ovih grana, a nije izuzetak opreme
        IF v_root_id IS NOT NULL AND NEW.category_id NOT IN (
            'oprema_za_zivotinje', 'boksevi_kucice_kavezi', 'hranilice_pojilice_muzilice',
            'kosnice_ramovi', 'vrcajke_za_med', 'pcelarski_pribor',
            'delovi_za_traktore', 'prerada_voca_oprema', 'navodnjavanje_plastenici'
        ) THEN
            v_applicable := false;
        END IF;
    END IF;

    IF v_applicable = false THEN
        NEW.condition := 'not_applicable';
    END IF;

    RETURN NEW;
END;
$$;

-- 5. Ažuriranje svih postojećih oglasa koji pripadaju neprikladnim kategorijama
UPDATE public.classified_ads
SET condition = 'not_applicable'
WHERE category_id IN (
    SELECT id FROM public.classified_categories WHERE is_condition_applicable = false
)
AND condition != 'not_applicable';

-- >>> END MIGRATION: 20260910180000_strictly_disable_condition_for_non_applicable_categories.sql <<<

-- >>> BEGIN MIGRATION: 20260910190000_comprehensive_security_hardening.sql <<<
-- ============================================================================
-- Migration: 20260910190000_comprehensive_security_hardening.sql
-- Description:
--   1. Storage Security (P0 & P1):
--      - Remove overly permissive storage policies on product-images.
--      - Enforce owner prefix (auth.uid()) on uploads.
--      - Add FOR DELETE and FOR UPDATE policies for product-images, farm-gallery, profiles.
--   2. Chat Conversations Security (P1):
--      - Replace FOR ALL policy on conversations with granular SELECT, INSERT, UPDATE.
--      - Eliminate client-side DELETE on conversations to prevent cascade deletion of messages.
--   3. Chat Messages Security (P1):
--      - Prevent modifying body, sender_id, created_at, conversation_id (enforce_message_update_restrictions).
--      - Restrict messages UPDATE strictly to read_at by recipients.
--      - Add FOR DELETE policy allowing only sender to delete own messages.
--   4. Order Status Transition Role Security (P1-P2):
--      - Enforce role validation in enforce_order_status_transition().
--      - Buyer cannot accept, reject, ship, or cancel as seller.
--      - Seller cannot mark as delivered (only buyer confirms receipt).
--      - Lock buyer_id and seller_id from being mutated via UPDATE.
--      - Support both 'arhivirano' and 'archived' in check constraint.
--   5. Classified Ad Views Race Condition & Cleanup (P2):
--      - Make increment_classified_ad_views fully atomic (eliminates race condition).
--      - Add probabilistic periodic cleanup of classified_ad_views (>14 days).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. STORAGE POLICIES HARDENING (P0 & P1)
-- ----------------------------------------------------------------------------

-- Ukloni sve stare/nesigurne politike sa storage.objects
DROP POLICY IF EXISTS "Allow product image uploads 16wiy3a_0" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated upload product-images" ON storage.objects;
DROP POLICY IF EXISTS "Public read product-images" ON storage.objects;
DROP POLICY IF EXISTS "Public read profiles" ON storage.objects;
DROP POLICY IF EXISTS "Public read farm-gallery" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated upload profiles" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated update profiles" ON storage.objects;
DROP POLICY IF EXISTS "Sellers upload own farm gallery" ON storage.objects;
DROP POLICY IF EXISTS "Users can delete own product images" ON storage.objects;
DROP POLICY IF EXISTS "Users can update own product images" ON storage.objects;
DROP POLICY IF EXISTS "Sellers can delete own farm gallery images" ON storage.objects;
DROP POLICY IF EXISTS "Sellers can update own farm gallery" ON storage.objects;
DROP POLICY IF EXISTS "Users can delete own profile image" ON storage.objects;

-- 1.1 Javni SELECT za sve public buckete
CREATE POLICY "Public read product-images"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'product-images');

CREATE POLICY "Public read profiles"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'profiles');

CREATE POLICY "Public read farm-gallery"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'farm-gallery');

-- 1.2 Profiles (vlasnik uređuje samo svoj userId.jpg)
CREATE POLICY "Users upload own profile image"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'profiles'
    AND name = ((select auth.uid())::text || '.jpg')
  );

CREATE POLICY "Users update own profile image"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'profiles'
    AND name = ((select auth.uid())::text || '.jpg')
  );

