-- >>> BEGIN MIGRATION: 20260917130000_enable_rls_on_product_summaries.sql <<<
-- ============================================================================
-- Sigurnost: RLS i zaštita integriteta nad tabelama agregata
-- Datum: 2026-09-17
--
-- Tabele public.product_review_summary i public.product_order_summary
-- sadrže agregate koje održavaju isključivo interni SECURITY DEFINER trigeri.
--
-- Ova migracija:
-- 1. Uključuje Row Level Security (RLS) na obe tabele.
-- 2. Oduzima (REVOKE) INSERT, UPDATE, DELETE, TRUNCATE od rola anon i authenticated.
-- 3. Kreira FOR SELECT RLS politike kako bi javni upiti (i security_invoker view
--    products_with_ratings) imali neometano pravo čitanja podataka.
-- ============================================================================

ALTER TABLE public.product_review_summary ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_order_summary ENABLE ROW LEVEL SECURITY;

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.product_review_summary FROM anon, authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.product_order_summary FROM anon, authenticated;

DROP POLICY IF EXISTS "summary_read" ON public.product_review_summary;
CREATE POLICY "summary_read" ON public.product_review_summary
  FOR SELECT
  TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS "summary_read" ON public.product_order_summary;
CREATE POLICY "summary_read" ON public.product_order_summary
  FOR SELECT
  TO anon, authenticated
  USING (true);

-- >>> END MIGRATION: 20260917130000_enable_rls_on_product_summaries.sql <<<

-- >>> BEGIN MIGRATION: 20260917140000_profiles_column_select_security.sql <<<
-- ============================================================================
-- Sigurnost: Zabrana direktnog čitanja email/phone nad tabelom profiles
-- Datum: 2026-09-17
--
-- PROBLEM:
-- REVOKE SELECT (email, phone) u migraciji 20260909190000 nije imao efekta
-- ukoliko je uloga imala table-level SELECT (PostgreSQL pravilo: table privilege
-- nadjačava column revoke). Zbog toga su osetljivi podaci (email, phone)
-- mogli biti pročitani direktno preko 'profiles' tabele.
--
-- REŠENJE:
-- 1. Oduzmi table-level SELECT sa public.profiles od anon i authenticated.
-- 2. Eksplicitno dodeli kolonski SELECT samo za bezbedne (ne-osetljive) kolone.
-- 3. Pristup email-u i broju telefona ide isključivo kroz SECURITY DEFINER
--    view public_profiles (koji štiti podatke kroz CASE WHEN za vlasnika/admina)
--    ili kroz namensku funkciju check_phone_exists.
-- ============================================================================

-- 1. Oduzmi table-level SELECT privilegiju
REVOKE SELECT ON public.profiles FROM anon, authenticated;

-- 2. Dodeli pravo čitanja isključivo nad bezbednim kolonama
GRANT SELECT (
  id, display_name, city, postal_code, role, is_guest, farm_name, location,
  profile_image_url, phone_public, is_verified, seller_story, farm_gallery_urls,
  seller_tags, seller_quick_replies, is_admin, lat, lng, created_at, updated_at
) ON public.profiles TO anon, authenticated;

-- >>> END MIGRATION: 20260917140000_profiles_column_select_security.sql <<<

-- >>> BEGIN MIGRATION: 20260917150000_revoke_write_on_security_definer_views.sql <<<
-- ============================================================================
-- Sigurnost: Zabrana operacija pisanja nad SECURITY DEFINER view-ovima
-- Datum: 2026-09-17
--
-- PROBLEM:
-- View-ovi public.public_profiles i public.public_classified_ads se izvršavaju
-- kao vlasnik (postgres / definer) radi bezbednog maskiranja osetljivih podataka
-- (email, phone). Ukoliko na njima postoji default write grant, INSERT/UPDATE/DELETE
-- bi se izvršavao sa pravima vlasnika i mogao bi zaobići RLS osnovnih tabela.
--
-- REŠENJE:
-- Eksplicitno oduzmi INSERT, UPDATE, DELETE, TRUNCATE nad ovim view-ovima
-- za uloge PUBLIC, anon i authenticated. View-ovi služe isključivo za čitanje.
-- ============================================================================

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.public_profiles FROM PUBLIC, anon, authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.public_classified_ads FROM PUBLIC, anon, authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.products_with_ratings FROM PUBLIC, anon, authenticated;

-- >>> END MIGRATION: 20260917150000_revoke_write_on_security_definer_views.sql <<<

-- >>> BEGIN MIGRATION: 20260917160000_align_unit_piece_order_step.sql <<<
-- ============================================================================
-- Usklađivanje: Prirodni korak za komadne proizvode (unit_type = 'kom')
-- Datum: 2026-09-17
--
-- PROBLEM:
-- Heuristički korak 10 za unit_type = 'kom' sprečava naručivanje manjih ili
-- fleksibilnih količina (npr. 6 jaja, 1 kokoška, 1 tegla/komad) i može dovesti
-- do kršenja constraint-a (min_order_kg deljivo sa order_step i order_step <= min_order_kg).
--
-- REŠENJE:
-- `order_step = LEAST(1, min_order_kg)`:
--   - min_order_kg >= 1 -> step = 1 (prirodni korak od 1 komada),
--   - min_order_kg  < 1 -> step = min_order_kg (poštuje CHECK order_step <= min_order_kg).
--
-- NAPOMENA o alignment CHECK-u: `products_min_order_step_alignment_check`
-- (dodat u 20260916100000) zahteva da min_order_kg bude tačan umnožak
-- order_step-a. Za necelobrojni min_order_kg >= 1 (npr. 3.5), step = 1 bi taj
-- CHECK kršio, ali takva (min, step) kombinacija ne može postojati u stanju u
-- kom se ova migracija izvršava: 20260916100000 je prethodno uskladila podatke
-- i aktivirala validirani CHECK, pa WHERE ovde u konzistentnom stanju ne hvata
-- nijednu liniju. Ipak, ako se nađe nekonzistentna linija, poslednji DO blok
-- prekida migraciju uz jasnu poruku (umesto tihog kvara ili enigmatične
-- constraint greške).
-- ============================================================================

UPDATE public.products
SET order_step = LEAST(1, min_order_kg)
WHERE unit_type = 'kom'
  AND order_step > 0
  AND min_order_kg > 0
  AND (
    order_step > min_order_kg
    OR abs(min_order_kg - (ROUND(min_order_kg / order_step) * order_step)) > 0.000001
  );

-- Konačni integritetni ček: ako i dalje postoji kom proizvod koji ne zadovoljava
-- constraint-e (npr. zbog nevalidne postojeće vrednosti), migracija se prekida
-- uz jasnu poruku, a transakcija se vraća u početno stanje.
DO $$
DECLARE
  v_problems INT;
BEGIN
  SELECT count(*)
    INTO v_problems
    FROM public.products
   WHERE unit_type = 'kom'
     AND (
       order_step <= 0
       OR min_order_kg <= 0
       OR order_step > min_order_kg
       OR CASE
            WHEN order_step > 0 THEN
              abs(min_order_kg - (ROUND(min_order_kg / order_step) * order_step)) > 0.000001
            ELSE TRUE
          END
     );

  IF v_problems > 0 THEN
    RAISE EXCEPTION
      'Prekid migracije: % kom proizvoda ne zadovoljava order_step/min_order_kg constraint-e.',
      v_problems;
  END IF;
END;
$$;

-- >>> END MIGRATION: 20260917160000_align_unit_piece_order_step.sql <<<

-- >>> BEGIN MIGRATION: 20260917170000_secure_chat_images_and_storage_privacy.sql <<<
-- ==============================================================================
-- 20260917170000_secure_chat_images_and_storage_privacy.sql
-- R3-A: Zatvaranje bezbednosnog propusta privatnosti chat slika
--
-- 1. Postavlja bucket `chat-images` na `public = false`.
-- 2. Uklanja blanket public SELECT politiku i omogućava pristup isključivo
--    učesnicima razgovora (buyer_id ili seller_id) i administratorima.
-- 3. Sprečava neautorizovan upload u tuđe razgovore (konverzija u proveru učešća).
-- 4. Uklanja mogućnost uploada u legacy `chat/` folder javnog `product-images` bucketa.
-- ==============================================================================

-- 1. Učini `chat-images` bucket privatnim
UPDATE storage.buckets
SET public = false
WHERE id = 'chat-images';

-- 2. Ukloni nesigurnu blanket SELECT politiku
DROP POLICY IF EXISTS "Public read chat-images" ON storage.objects;
DROP POLICY IF EXISTS "Participants read chat-images" ON storage.objects;

-- 3. Dozvoli SELECT samo učesnicima razgovora ili administratorima
-- Putanja objekta: `<userId>/<conversationId>/<filename>`
-- (storage.foldername(name))[2] predstavlja conversation_id
CREATE POLICY "Participants read chat-images"
  ON storage.objects
  FOR SELECT
  TO authenticated
  USING (
    bucket_id = 'chat-images'
    AND (
      EXISTS (
        SELECT 1 FROM public.conversations c
        WHERE c.id::text = (storage.foldername(name))[2]
          AND (c.buyer_id = (SELECT auth.uid()) OR c.seller_id = (SELECT auth.uid()))
      )
      OR public.is_admin()
    )
  );

-- 4. Ograniči INSERT: ulogovani korisnik sme da uploaduje samo u svoj folder i samo u razgovor gde je učesnik
DROP POLICY IF EXISTS "Authenticated upload chat-images" ON storage.objects;
CREATE POLICY "Authenticated upload chat-images"
  ON storage.objects
  FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'chat-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
    AND EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id::text = (storage.foldername(name))[2]
        AND (c.buyer_id = (SELECT auth.uid()) OR c.seller_id = (SELECT auth.uid()))
    )
  );

-- 5. Ograniči UPDATE i DELETE na vlasnika fajla (ili admina za delete)
DROP POLICY IF EXISTS "Owner update chat-images" ON storage.objects;
CREATE POLICY "Owner update chat-images"
  ON storage.objects
  FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'chat-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
  )
  WITH CHECK (
    bucket_id = 'chat-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
  );

DROP POLICY IF EXISTS "Owner delete chat-images" ON storage.objects;
CREATE POLICY "Owner delete chat-images"
  ON storage.objects
  FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'chat-images'
    AND (
      (storage.foldername(name))[1] = (SELECT auth.uid())::text
      OR public.is_admin()
    )
  );

-- 6. Spreči upload chat slika u javni `product-images` bucket
DROP POLICY IF EXISTS "Users upload own product images" ON storage.objects;
CREATE POLICY "Users upload own product images"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'product-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
    AND (storage.foldername(name))[1] != 'chat'
  );

DROP POLICY IF EXISTS "Users update own product images" ON storage.objects;
CREATE POLICY "Users update own product images"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'product-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
    AND (storage.foldername(name))[1] != 'chat'
  );

DROP POLICY IF EXISTS "Users delete own product images" ON storage.objects;
CREATE POLICY "Users delete own product images"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'product-images'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
    AND (storage.foldername(name))[1] != 'chat'
  );

-- >>> END MIGRATION: 20260917170000_secure_chat_images_and_storage_privacy.sql <<<

-- >>> BEGIN MIGRATION: 20260917180000_secure_push_health_views_and_rpc.sql <<<
-- Migration: 20260917180000_secure_push_health_views_and_rpc.sql
-- R3-B: Zaštita push-health view-ova i funkcija (ograničenje pristupa isključivo administratorima)

-- 1. Oduzmi SELECT / ALL na view-ovima od anon, authenticated i PUBLIC
REVOKE ALL ON public.push_health_dashboard FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.push_health_user_issues FROM PUBLIC, anon, authenticated;

-- Osiguraj pristup za service_role
GRANT SELECT ON public.push_health_dashboard TO service_role;
GRANT SELECT ON public.push_health_user_issues TO service_role;

-- 2. Oduzmi direktno izvršavanje osnovnih push health funkcija
REVOKE EXECUTE ON FUNCTION public.push_health_summary() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.push_health_summary() TO service_role;

REVOKE EXECUTE ON FUNCTION public.push_user_health(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.push_user_health(UUID) TO service_role;

-- 3. Kreiraj SECURITY DEFINER RPC funkciju za push_health_dashboard dostupnu samo administratorima
CREATE OR REPLACE FUNCTION public.admin_get_push_health_dashboard()
RETURNS SETOF public.push_health_dashboard
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Sigurnosna provera: samo ulogovani administratori
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Pristup odbijen: samo administratori mogu pristupiti push health dijagnostici.';
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.push_health_dashboard;
END;
$$;

-- 4. Kreiraj SECURITY DEFINER RPC funkciju za push_health_user_issues dostupnu samo administratorima
CREATE OR REPLACE FUNCTION public.admin_get_push_health_user_issues()
RETURNS SETOF public.push_health_user_issues
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Sigurnosna provera: samo ulogovani administratori
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Pristup odbijen: samo administratori mogu pristupiti podacima o problemima sa push notifikacijama korisnika.';
  END IF;

  RETURN QUERY
  SELECT *
  FROM public.push_health_user_issues
  ORDER BY latest_notification_at DESC NULLS LAST;
END;
$$;

-- 5. Dozvole na RPC funkcijama: zabrani PUBLIC, dozvoli samo authenticated i service_role
REVOKE ALL ON FUNCTION public.admin_get_push_health_dashboard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_get_push_health_dashboard() TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.admin_get_push_health_user_issues() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_get_push_health_user_issues() TO authenticated, service_role;

COMMENT ON FUNCTION public.admin_get_push_health_dashboard() IS
'Bezbedni RPC za push health dashboard: proverava da li je pozivalac administrator pre vraćanja metrika.';

COMMENT ON FUNCTION public.admin_get_push_health_user_issues() IS
'Bezbedni RPC za push health probleme korisnika: proverava da li je pozivalac administrator pre vraćanja podataka.';

-- >>> END MIGRATION: 20260917180000_secure_push_health_views_and_rpc.sql <<<

