-- >>> BEGIN MIGRATION: 20261006160000_pass_classified_ad_id_to_push_notifications.sql <<<
-- ============================================================================
-- Migracija 20261006160000: Prosleđivanje classified_ad_id i apikey hedera u push notifikacije
-- ============================================================================

-- 1. Ažuriraj send_push_notification da šalje apikey i Authorization hedere
CREATE OR REPLACE FUNCTION public.send_push_notification(
  p_user_id         uuid,
  p_title           text,
  p_body            text,
  p_type            text,
  p_order_id        text  DEFAULT ''::text,
  p_ticket_id       text  DEFAULT ''::text,
  p_conversation_id text  DEFAULT ''::text,
  p_data            jsonb DEFAULT '{}'::jsonb
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  base_url    TEXT;
  service_key TEXT;
  fn_url      TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;

  -- 1. Čitanje service_role_key isključivo iz Supabase Vault-a
  BEGIN
    SELECT decrypted_secret INTO service_key 
    FROM vault.decrypted_secrets 
    WHERE name = 'service_role_key' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    service_key := NULL;
  END;

  -- 2. Čitanje functions_base_url iz Vault-a ili edge_config fallback
  BEGIN
    SELECT decrypted_secret INTO base_url 
    FROM vault.decrypted_secrets 
    WHERE name = 'functions_base_url' 
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    base_url := NULL;
  END;

  IF base_url IS NULL OR base_url = '' THEN
    SELECT value INTO base_url FROM public.edge_config WHERE key = 'functions_base_url' LIMIT 1;
  END IF;

  IF service_key IS NULL OR service_key = '' OR base_url IS NULL OR base_url = '' THEN
    RAISE WARNING 'send_push_notification: Nedostaje konfiguracija (Vault service_role_key ili URL).';
    RETURN false;
  END IF;

  fn_url := base_url || '/functions/v1/send-push';

  PERFORM net.http_post(
    url := fn_url,
    body := jsonb_build_object(
      'user_id', p_user_id,
      'title', COALESCE(p_title, ''),
      'body', COALESCE(p_body, ''),
      'type', COALESCE(p_type, ''),
      'order_id', COALESCE(p_order_id, ''),
      'ticket_id', COALESCE(p_ticket_id, ''),
      'conversation_id', COALESCE(p_conversation_id, ''),
      'data', COALESCE(p_data, '{}'::jsonb)
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_key,
      'apikey', service_key
    ),
    timeout_milliseconds := 5000
  );

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'send_push_notification greška: %', SQLERRM;
  RETURN false;
END;
$$;

-- 2. Ažuriraj invoke_send_push trigger funkciju da prosledi i classified_ad_id
CREATE OR REPLACE FUNCTION public.invoke_send_push()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.send_push_notification(
    p_user_id := NEW.user_id,
    p_title := COALESCE(NEW.title, ''),
    p_body := COALESCE(NEW.body, ''),
    p_type := COALESCE(NEW.type::text, ''),
    p_order_id := CASE WHEN NEW.order_id IS NOT NULL THEN NEW.order_id::text ELSE '' END,
    p_ticket_id := CASE WHEN NEW.ticket_id IS NOT NULL THEN NEW.ticket_id::text ELSE '' END,
    p_conversation_id := CASE WHEN NEW.conversation_id IS NOT NULL THEN NEW.conversation_id::text ELSE '' END,
    p_data := jsonb_build_object(
      'classified_ad_id', CASE WHEN NEW.classified_ad_id IS NOT NULL THEN NEW.classified_ad_id::text ELSE '' END
    )
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'invoke_send_push greška: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- >>> END MIGRATION: 20261006160000_pass_classified_ad_id_to_push_notifications.sql <<<

-- >>> BEGIN MIGRATION: 20261006164000_fix_public_profiles_security_definer.sql <<<
-- ============================================================================
-- Fix: public_profiles i public_classified_ads moraju biti SECURITY DEFINER
-- Datum: 2026-10-06
--
-- PROBLEM:
-- Tabela public.profiles ima REVOKE SELECT za anon i authenticated kako bi se
-- sprečilo curenje privatnih kolona (email, telefon).
-- View-ovi public_profiles i public_classified_ads su imali uključen
-- security_invoker = true, zbog čega je PostgreSQL proveravao privilegije
-- pozivaoca nad osnovnom tabelom profiles i vraćao grešku 42501:
-- "permission denied for table profiles".
--
-- REŠENJE:
-- 1. Postavi security_invoker = false na public_profiles i public_classified_ads.
-- 2. View se izvršava sa pravima vlasnika (postgres), a interna CASE WHEN logika
--    view-a bezbedno maskira email i telefon ako korisnik nije vlasnik ili admin.
-- 3. Zadrži eksplicitni REVOKE za pisanje (INSERT/UPDATE/DELETE/TRUNCATE).
-- 4. Osiguraj GRANT SELECT za anon i authenticated.
-- ============================================================================

ALTER VIEW public.public_profiles SET (security_invoker = false);
ALTER VIEW public.public_classified_ads SET (security_invoker = false);

REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.public_profiles FROM PUBLIC, anon, authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.public_classified_ads FROM PUBLIC, anon, authenticated;

GRANT SELECT ON public.public_profiles TO anon, authenticated;
GRANT SELECT ON public.public_classified_ads TO anon, authenticated;

-- >>> END MIGRATION: 20261006164000_fix_public_profiles_security_definer.sql <<<

-- >>> BEGIN MIGRATION: 20261007073000_server_side_order_archive_and_product_stats.sql <<<
-- ============================================================================
-- Server-side Order Archive Retention & Product Stats
-- ============================================================================
-- 1. Automatsko postavljanje server-side timestamp-ova pri arhiviranju porudžbine:
--    - archived_at = now()
--    - expires_at = now() + INTERVAL '12 months' (eliminacija oslanjanja na klijentski sat)
-- 2. RPC archive_order(p_order_id) za bezbedno arhiviranje sa strane kupca ili prodavca.
-- 3. RPC get_product_stats(p_product_id) za brz O(1) dohvat agregata ocena i broja recenzija.
-- ============================================================================

-- 1. Triger za server-side datum arhive i retention
CREATE OR REPLACE FUNCTION public.set_order_archived_timestamps()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.status = 'archived' AND (OLD.status IS DISTINCT FROM 'archived') THEN
    NEW.archived_at := COALESCE(NEW.archived_at, now());
    NEW.expires_at := now() + INTERVAL '12 months';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_set_order_archived_timestamps ON public.orders;
CREATE TRIGGER trg_set_order_archived_timestamps
  BEFORE UPDATE OF status ON public.orders
  FOR EACH ROW
  EXECUTE FUNCTION public.set_order_archived_timestamps();

-- 2. RPC archive_order
CREATE OR REPLACE FUNCTION public.archive_order(p_order_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_order RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Niste prijavljeni.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT id, buyer_id, seller_id, status
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Porudžbina nije pronađena.' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_order.buyer_id != v_uid AND v_order.seller_id != v_uid THEN
    RAISE EXCEPTION 'Nemate dozvolu za arhiviranje ove porudžbine.' USING ERRCODE = 'insufficient_privilege';
  END IF;

  UPDATE public.orders
  SET status = 'archived'
  WHERE id = p_order_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.archive_order(UUID) TO authenticated;

-- 3. RPC get_product_stats
CREATE OR REPLACE FUNCTION public.get_product_stats(p_product_id UUID)
RETURNS JSON
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT json_build_object(
    'avg_rating', COALESCE(s.avg_rating, (SELECT ROUND(AVG(rating)::numeric, 1)::float FROM public.reviews WHERE product_id = p_product_id)),
    'review_count', COALESCE(s.review_count, (SELECT COUNT(*)::int FROM public.reviews WHERE product_id = p_product_id))
  )
  FROM (SELECT 1) _
  LEFT JOIN public.product_review_summary s ON s.product_id = p_product_id;
$$;

GRANT EXECUTE ON FUNCTION public.get_product_stats(UUID) TO anon, authenticated;

-- >>> END MIGRATION: 20261007073000_server_side_order_archive_and_product_stats.sql <<<

-- >>> BEGIN MIGRATION: 20261007074500_search_diacritics_normalization.sql <<<
-- ============================================================================
-- Migracija: Normalizacija dijakritika u pretrazi proizvoda i trigram podrška
-- Datum: 2026-10-07
-- 
-- 1. Kreira/osigurava ekstenzije unaccent i pg_trgm.
-- 2. Kreira GIN trigram indeks nad unaccent(lower(name)) za brzu sličnost i ILIKE.
-- 3. Kreira helper normalize_search_text za srpske znakove (uključujući đ/Đ -> dj/Dj).
-- 4. Ažurira search_vector trigger i podatke sa normalizovanim tekstom.
-- 5. Ažurira search_products_fts sa FTS + trigram/unaccent pokrivanjem.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 1. Immutable unaccent wrapper potreban za PostgreSQL indeksne izraze
CREATE OR REPLACE FUNCTION public.immutable_unaccent(t text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT public.unaccent(coalesce(t, ''));
$$;

-- 2. Helper funkcija za srpsku normalizaciju (unaccent ne pokriva đ/Đ u difoltnim pravilima)
CREATE OR REPLACE FUNCTION public.normalize_search_text(t text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT translate(
    public.immutable_unaccent(t),
    'đĐ',
    'djDj'
  );
$$;

-- 3. Trigram GIN indeks nad nazivom proizvoda sa uklonjenim akcentima
CREATE INDEX IF NOT EXISTS idx_products_name_trgm_unaccent
  ON public.products USING gin (public.immutable_unaccent(lower(name)) gin_trgm_ops);

-- 3. Ažuriranje trigger funkcije za search_vector
CREATE OR REPLACE FUNCTION public.products_search_vector_update()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
BEGIN
  NEW.search_vector := to_tsvector('simple',
    public.normalize_search_text(NEW.name) || ' ' ||
    public.immutable_unaccent(NEW.name) || ' ' ||
    public.normalize_search_text(NEW.description) || ' ' ||
    public.immutable_unaccent(NEW.description)
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_products_search_vector ON public.products;
CREATE TRIGGER trg_products_search_vector
  BEFORE INSERT OR UPDATE OF name, description ON public.products
  FOR EACH ROW EXECUTE FUNCTION public.products_search_vector_update();

-- 4. Backfill postojećih proizvoda
UPDATE public.products
SET search_vector = to_tsvector('simple',
  public.normalize_search_text(name) || ' ' ||
  public.immutable_unaccent(name) || ' ' ||
  public.normalize_search_text(description) || ' ' ||
  public.immutable_unaccent(description)
);

-- 5. RPC pretrage proizvoda sa podrškom za dijakritike i toleranciju tipfelera (pg_trgm + unaccent)
CREATE OR REPLACE FUNCTION public.search_products_fts(
  p_query             text,
  p_category          text    DEFAULT NULL,
  p_region            text    DEFAULT NULL,
  p_available_now     boolean DEFAULT NULL,
  p_exclude_seller_id uuid    DEFAULT NULL,
  p_limit             int     DEFAULT 20,
  p_offset            int     DEFAULT 0
)
RETURNS SETOF public.products_with_ratings
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
  SELECT
    p.id,
    p.seller_id,
    p.category,
    p.name,
    p.price_per_kg,
    p.min_order_kg,
    p.order_step,
    p.available_kg,
    p.unit_type,
    p.description,
    p.image_urls,
    p.pickup_options,
    p.location,
    p.is_domestic,
    p.available_now,
    p.delivery_mode,
    p.created_at,
    COALESCE(r.avg_rating, 0)::numeric   AS avg_rating,
    COALESCE(r.review_count, 0)::bigint  AS review_count,
    COALESCE(o.order_count, 0)::bigint   AS order_count,
    COALESCE(prof.is_verified, false)    AS seller_is_verified
  FROM public.products p
  LEFT JOIN public.product_review_summary r ON r.product_id = p.id
  LEFT JOIN public.product_order_summary o ON o.product_id = p.id
  LEFT JOIN public.public_profiles prof ON prof.id = p.seller_id
  WHERE
    (
      p.search_vector @@ websearch_to_tsquery('simple', public.normalize_search_text(p_query))
      OR p.search_vector @@ websearch_to_tsquery('simple', public.immutable_unaccent(p_query))
      OR public.immutable_unaccent(lower(p.name)) ILIKE ('%' || public.immutable_unaccent(lower(p_query)) || '%')
      OR word_similarity(public.immutable_unaccent(lower(p_query)), public.immutable_unaccent(lower(p.name))) >= 0.35
      OR similarity(public.immutable_unaccent(lower(p.name)), public.immutable_unaccent(lower(p_query))) >= 0.3
    ) AND
    (p_category          IS NULL OR p.category     = p_category)             AND
    (p_region            IS NULL OR p.location     = p_region)               AND
    (p_available_now     IS NULL OR p.available_now = p_available_now)       AND
    (p_exclude_seller_id IS NULL OR p.seller_id   <> p_exclude_seller_id)
  ORDER BY
    ts_rank(p.search_vector, websearch_to_tsquery('simple', public.normalize_search_text(p_query))) DESC,
    word_similarity(public.immutable_unaccent(lower(p_query)), public.immutable_unaccent(lower(p.name))) DESC,
    similarity(public.immutable_unaccent(lower(p.name)), public.immutable_unaccent(lower(p_query))) DESC,
    p.created_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION public.search_products_fts TO anon, authenticated;

-- >>> END MIGRATION: 20261007074500_search_diacritics_normalization.sql <<<

-- >>> BEGIN MIGRATION: 20261007080000_chat_and_realtime_hardening.sql <<<
-- Migracija: 20261007080000_chat_and_realtime_hardening.sql
-- Učvršćivanje Chat i Realtime arhitekture:
-- 1. Zaštita od self-conversations (buyer_id <> seller_id)
-- 2. Scoped razgovori vezani za porudžbinu (order_id) bez preskakanja zaglavlja i prepisivanja
-- 3. Bounded server-side RPC za označavanje poruka pročitanim (mark_conversation_read)

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Zaštita: buyer_id <> seller_id
-- ─────────────────────────────────────────────────────────────────────────────

-- Očisti eventualne stare nevažeće self-razgovore (ako postoje iz testova)
DELETE FROM public.conversations WHERE buyer_id = seller_id;

ALTER TABLE public.conversations
  DROP CONSTRAINT IF EXISTS chk_conversations_distinct_parties;

ALTER TABLE public.conversations
  ADD CONSTRAINT chk_conversations_distinct_parties
  CHECK (buyer_id <> seller_id);

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Scoped indeksi razgovora (order_id, product_id, ad_id, general)
-- ─────────────────────────────────────────────────────────────────────────────

-- Ukloni stare indekse
DROP INDEX IF EXISTS public.idx_conversations_buyer_seller_product;
DROP INDEX IF EXISTS public.idx_conversations_buyer_seller_ad;
DROP INDEX IF EXISTS public.idx_conversations_buyer_seller_general;
DROP INDEX IF EXISTS public.idx_conversations_order;

-- Razreši eventualne duple zapise za isti order_id pre kreiranja UNIQUE indeksa
DO $$
BEGIN
  IF EXISTS (
    SELECT order_id FROM public.conversations
    WHERE order_id IS NOT NULL
    GROUP BY order_id HAVING COUNT(*) > 1
  ) THEN
    -- Preusmeri poruke sa starijih duplikata na najnoviji razgovor
    UPDATE public.messages m
    SET conversation_id = target.id
    FROM (
      SELECT DISTINCT ON (c.order_id) c.id, c.order_id
      FROM public.conversations c
      WHERE c.order_id IS NOT NULL
      ORDER BY c.order_id, c.updated_at DESC, c.id DESC
    ) target
    JOIN public.conversations dup ON dup.order_id = target.order_id
    WHERE m.conversation_id = dup.id AND dup.id <> target.id;

    -- Obriši višak duplikata
    DELETE FROM public.conversations dup
    USING (
      SELECT DISTINCT ON (c.order_id) c.id, c.order_id
      FROM public.conversations c
      WHERE c.order_id IS NOT NULL
      ORDER BY c.order_id, c.updated_at DESC, c.id DESC
    ) keeper
    WHERE dup.order_id = keeper.order_id AND dup.id <> keeper.id;
  END IF;
END $$;

-- a) Zaseban razgovor vezan za konkretnu porudžbinu (jedinstven po order_id)
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversations_order
  ON public.conversations (order_id)
  WHERE order_id IS NOT NULL;

-- b) Razgovor vezan za proizvod (samo opšti upiti pre poručivanja, gde order_id IS NULL)
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversations_buyer_seller_product
  ON public.conversations (buyer_id, seller_id, product_id)
  WHERE product_id IS NOT NULL AND order_id IS NULL;

-- c) Razgovor vezan za mali oglas (gde order_id IS NULL)
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversations_buyer_seller_ad
  ON public.conversations (buyer_id, seller_id, ad_id)
  WHERE ad_id IS NOT NULL AND order_id IS NULL;

-- d) Opšti razgovor bez predmeta i bez porudžbine
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversations_buyer_seller_general
  ON public.conversations (buyer_id, seller_id)
  WHERE product_id IS NULL AND ad_id IS NULL AND order_id IS NULL;

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. Server-side RPC za označavanje pročitanih poruka sa limitom
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.mark_conversation_read(
  p_conversation_id UUID,
  p_limit INT DEFAULT 200
)
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_updated INT := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Provera da je trenutno prijavljeni korisnik učesnik u razgovoru
  IF NOT EXISTS (
    SELECT 1 FROM public.conversations
    WHERE id = p_conversation_id
      AND (buyer_id = v_user_id OR seller_id = v_user_id)
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Bounded set-based update poruka koje nisu poslate od strane trenutnog korisnika
  WITH to_update AS (
    SELECT id
    FROM public.messages
    WHERE conversation_id = p_conversation_id
      AND sender_id <> v_user_id
      AND read_at IS NULL
    ORDER BY created_at DESC
    LIMIT GREATEST(1, LEAST(p_limit, 1000))
  )
  UPDATE public.messages m
  SET read_at = NOW()
  FROM to_update
  WHERE m.id = to_update.id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;

GRANT EXECUTE ON FUNCTION public.mark_conversation_read(UUID, INT) TO authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. Ažuriranje funkcije get_conversations_for_user (prioritet order_id)
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_conversations_for_user(p_user_id UUID)
RETURNS JSONB
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    jsonb_agg(row_to_json(t)::jsonb ORDER BY (row_to_json(t) ->> 'updated_at') DESC),
    '[]'::jsonb
  )
  FROM (
    SELECT
      c.id,
      c.buyer_id,
      c.seller_id,
      c.order_id,
      c.product_id,
      c.ad_id,
      c.created_at,
      c.updated_at,
      COALESCE(
        CASE WHEN c.buyer_id = p_user_id
             THEN COALESCE(ps.farm_name, ps.display_name)
             ELSE COALESCE(pb.farm_name, pb.display_name)
        END,
        'Korisnik'
      )                                                                    AS other_party_name,
      CASE WHEN c.buyer_id = p_user_id
           THEN ps.profile_image_url
           ELSE pb.profile_image_url
      END                                                                  AS other_party_image_url,
      lm.body                                                              AS last_message_body,
      lm.created_at                                                        AS last_message_at,
      (SELECT COUNT(*)::int
         FROM public.messages m2
        WHERE m2.conversation_id = c.id
          AND m2.sender_id      != p_user_id
          AND m2.read_at         IS NULL)                                  AS unread_count,
      COALESCE(cup.is_favorite, false)                                     AS is_favorite,
      COALESCE(cup.hidden, false)                                          AS hidden,
      COALESCE(
        (SELECT oi.product_name FROM public.order_items oi WHERE oi.order_id = c.order_id LIMIT 1),
        (SELECT o.product_name FROM public.orders o WHERE o.id = c.order_id),
        p.name,
        ad.title
      )                                                                    AS item_title,
      COALESCE(
        p.image_urls[1],
        ad.images[1]
      )                                                                    AS item_image_url,
      COALESCE(p.price_per_kg, ad.price)                                   AS item_price,
      COALESCE(p.unit_type, ad.currency)                                   AS item_unit,
      CASE
        WHEN c.order_id IS NOT NULL THEN 'order'
        WHEN c.product_id IS NOT NULL THEN 'product'
        WHEN c.ad_id IS NOT NULL THEN 'ad'
        ELSE NULL
      END                                                                  AS item_type
    FROM public.conversations c
    JOIN public.profiles pb ON pb.id = c.buyer_id
    JOIN public.profiles ps ON ps.id = c.seller_id
    LEFT JOIN public.products p ON p.id = c.product_id
    LEFT JOIN public.classified_ads ad ON ad.id = c.ad_id
    LEFT JOIN public.conversation_user_prefs cup
      ON cup.conversation_id = c.id AND cup.user_id = p_user_id
    LEFT JOIN LATERAL (
      SELECT body, created_at
        FROM public.messages
       WHERE conversation_id = c.id
       ORDER BY created_at DESC
       LIMIT 1
    ) lm ON true
    WHERE (c.buyer_id = p_user_id OR c.seller_id = p_user_id)
      AND p_user_id = auth.uid()
    ORDER BY c.updated_at DESC
    LIMIT 50
  ) t;
$$;

